window.APP_DATA.phonics = [
  // 2026-08-02 全面重寫：一律以教育部《國語一字多音審訂表》為準
  // ---- 國小 1-4（p001-p100 前段）----
  {id:"p001",grade:1,word:"行走",target:"行",zhuyin:"ㄒㄧㄥˊ",pinyin:"xíng",wrong:[{z:"ㄏㄤˊ",p:"háng"},{z:"ㄒㄧㄥˋ",p:"xìng"}],note:"「行走」的「行」讀ㄒㄧㄥˊ；「銀行」「行列」讀ㄏㄤˊ。",deep:"1. 注音比較\n行：ㄒㄧㄥˊ（二聲）＝行走、行為；ㄏㄤˊ（二聲）＝行列、銀行；ㄒㄧㄥˋ（四聲）＝品行、德行\n2. 國字拆解與造字原因\n行：象形字，甲骨文像四通八達的十字路口，本義是道路。人在路上走→「行走」（ㄒㄧㄥˊ）；道路上店鋪成排→「行列、銀行」（ㄏㄤˊ）；一個人走過的路如同他的作為→「品行」（ㄒㄧㄥˋ）。"},
  {id:"p002",grade:1,word:"長大",target:"長",zhuyin:"ㄓㄤˇ",pinyin:"zhǎng",wrong:[{z:"ㄔㄤˊ",p:"cháng"},{z:"ㄓㄤˋ",p:"zhàng"}],note:"「長大」「長輩」讀ㄓㄤˇ；「長短」讀ㄔㄤˊ。",deep:"1. 注音比較\n長：ㄓㄤˇ（三聲）＝長大、長輩；ㄔㄤˊ（二聲）＝長短、長久；ㄓㄤˋ＝無此音（易與「漲」「帳」混淆）\n2. 國字拆解與造字原因\n長：象形字，像長髮老人拄杖之形。頭髮要時間才留得長→「生長、年長」（ㄓㄤˇ）；長髮下垂形容距離、時間的長度→「長短、長久」（ㄔㄤˊ）。"},
  {id:"p003",grade:1,word:"為什麼",target:"為",zhuyin:"ㄨㄟˋ",pinyin:"wèi",wrong:[{z:"ㄨㄟˊ",p:"wéi"},{z:"ㄨㄟˇ",p:"wěi"}],note:"「為什麼」「因為」讀ㄨㄟˋ；「作為」「成為」讀ㄨㄟˊ。",deep:"1. 注音比較\n為：ㄨㄟˋ（四聲）＝為什麼、因為、為了；ㄨㄟˊ（二聲）＝成為、行為、大有可為；ㄨㄟˇ＝無此音\n2. 國字拆解與造字原因\n為：會意字，甲骨文像一隻手牽著大象幫人做事，本義是做、作為→「行為、成為」（ㄨㄟˊ）；替誰做事、為了什麼目的→「因為、為了」（ㄨㄟˋ）。記法：表「目的、原因」讀四聲，表「做、當」讀二聲。"},
  {id:"p004",grade:1,word:"著急",target:"著",zhuyin:"ㄓㄠˊ",pinyin:"zháo",wrong:[{z:"ㄓㄜ",p:"zhe"},{z:"ㄓㄨˋ",p:"zhù"}],note:"「著急」「著火」讀ㄓㄠˊ；「看著」讀輕聲ㄓㄜ；「著作」讀ㄓㄨˋ。",deep:"1. 注音比較\n著：ㄓㄠˊ（二聲）＝著急、著火；˙ㄓㄜ（輕聲）＝看著、坐著；ㄓㄨˋ（四聲）＝著作、顯著\n2. 國字拆解與造字原因\n著：形聲字，「艹」＋「者」（聲）。本義是寫定、記載→「著作、顯著」（ㄓㄨˋ）；引申為附著、碰上→「著火、著急」（ㄓㄠˊ）；再虛化成表示動作持續的助詞→「看著」（輕聲）。"},
  {id:"p005",grade:1,word:"和氣",target:"和",zhuyin:"ㄏㄜˊ",pinyin:"hé",wrong:[{z:"ㄏㄨㄛˋ",p:"huò"},{z:"ㄏㄢˋ",p:"hàn"}],note:"「和氣」「和平」讀ㄏㄜˊ；「攪和」讀ㄏㄨㄛˋ。",deep:"1. 注音比較\n和：ㄏㄜˊ（二聲）＝和氣、和平；ㄏㄨㄛˋ（四聲）＝攪和、和藥；ㄏㄢˋ（四聲）＝「我和你」（表「與」的口語音）\n2. 國字拆解與造字原因\n和：形聲字，「口」＋「禾」（聲）。本義是聲音互相應和、和諧，引申為溫和、和平（ㄏㄜˊ）；把東西摻在一起攪拌→「攪和」（ㄏㄨㄛˋ）；當連接詞「與」用時口語讀ㄏㄢˋ。"},
  {id:"p006",grade:1,word:"音樂",target:"樂",zhuyin:"ㄩㄝˋ",pinyin:"yuè",wrong:[{z:"ㄌㄜˋ",p:"lè"},{z:"ㄧㄠˋ",p:"yào"}],note:"「音樂」「樂器」讀ㄩㄝˋ；「快樂」讀ㄌㄜˋ。",deep:"1. 注音比較\n樂：ㄩㄝˋ（四聲）＝音樂、樂器；ㄌㄜˋ（四聲）＝快樂、樂觀；ㄧㄠˋ（四聲）＝仁者樂山（喜好，文言）\n2. 國字拆解與造字原因\n樂：象形字，像木架上張著絲弦的樂器，本義是樂器、音樂（ㄩㄝˋ）；音樂使人愉快→「快樂」（ㄌㄜˋ）；心中喜愛→「仁者樂山、智者樂水」（ㄧㄠˋ）。三個讀音是「樂器→快樂→喜好」的意義引申。"},
  {id:"p007",grade:1,word:"好人",target:"好",zhuyin:"ㄏㄠˇ",pinyin:"hǎo",wrong:[{z:"ㄏㄠˋ",p:"hào"},{z:"ㄏㄡˇ",p:"hǒu"}],note:"「好人」讀ㄏㄠˇ；「好奇」「愛好」讀ㄏㄠˋ。",deep:"1. 注音比較\n好：ㄏㄠˇ（三聲）＝好人、美好；ㄏㄠˋ（四聲）＝好奇、愛好、好學；ㄏㄡˇ＝無此音（是「吼」的讀音）\n2. 國字拆解與造字原因\n好：會意字，「女」＋「子」，母親抱著孩子，是最美善的畫面，本義美好（ㄏㄠˇ）；對美好事物心生喜愛→「愛好、好奇」（ㄏㄠˋ）。記法：當形容詞讀三聲，當動詞「喜愛」讀四聲。"},
  {id:"p008",grade:1,word:"睡覺",target:"覺",zhuyin:"ㄐㄧㄠˋ",pinyin:"jiào",wrong:[{z:"ㄐㄩㄝˊ",p:"jué"},{z:"ㄐㄧㄠˇ",p:"jiǎo"}],note:"「睡覺」讀ㄐㄧㄠˋ；「感覺」「發覺」讀ㄐㄩㄝˊ。",deep:"1. 注音比較\n覺：ㄐㄧㄠˋ（四聲）＝睡覺、午覺；ㄐㄩㄝˊ（二聲）＝感覺、發覺、覺悟；ㄐㄧㄠˇ＝無此音\n2. 國字拆解與造字原因\n覺：形聲字，「學（省略）」＋「見」，本義是睡醒、醒悟——醒來才「看見」明白→「發覺、覺悟、感覺」（ㄐㄩㄝˊ）；一睡一醒算一次，量詞化→「睡一覺、午覺」（ㄐㄧㄠˋ）。"},
  {id:"p009",grade:1,word:"背書包",target:"背",zhuyin:"ㄅㄟ",pinyin:"bēi",wrong:[{z:"ㄅㄟˋ",p:"bèi"},{z:"ㄆㄟ",p:"pēi"}],note:"「背書包」（負載）讀ㄅㄟ；「背書」「背後」讀ㄅㄟˋ。",deep:"1. 注音比較\n背：ㄅㄟ（一聲）＝背書包、背負；ㄅㄟˋ（四聲）＝背後、背書、違背；ㄆㄟ＝無此音（是「胚」的讀音）\n2. 國字拆解與造字原因\n背：形聲字，「月（肉）」＋「北」（聲，甲骨文「北」像兩人背對背）。本義是背部（ㄅㄟˋ）；用背部扛東西的動作→「背書包」（ㄅㄟ）。記法：當名詞或「背誦、違背」讀四聲，當「用背扛」的動作讀一聲。"},
  {id:"p010",grade:1,word:"教書",target:"教",zhuyin:"ㄐㄧㄠ",pinyin:"jiāo",wrong:[{z:"ㄐㄧㄠˋ",p:"jiào"},{z:"ㄑㄧㄠ",p:"qiāo"}],note:"「教書」「教你」讀ㄐㄧㄠ；「教育」「教室」讀ㄐㄧㄠˋ。",deep:"1. 注音比較\n教：ㄐㄧㄠ（一聲）＝教書、教我寫字；ㄐㄧㄠˋ（四聲）＝教育、教室、宗教；ㄑㄧㄠ＝無此音（是「敲」的讀音）\n2. 國字拆解與造字原因\n教：會意字，右邊「攵」是手持教鞭，左邊是孩子在學習，長輩持鞭督導孩子。當動作「傳授」讀ㄐㄧㄠ（教你）；當名詞或制度（教育、宗教、教室）讀ㄐㄧㄠˋ。"},
  {id:"p011",grade:1,word:"數星星",target:"數",zhuyin:"ㄕㄨˇ",pinyin:"shǔ",wrong:[{z:"ㄕㄨˋ",p:"shù"},{z:"ㄕㄨㄛˋ",p:"shuò"}],note:"「數星星」（計算）讀ㄕㄨˇ；「數字」讀ㄕㄨˋ。",deep:"1. 注音比較\n數：ㄕㄨˇ（三聲）＝數星星、數不清；ㄕㄨˋ（四聲）＝數字、數學；ㄕㄨㄛˋ（四聲）＝數見不鮮（屢次，文言）\n2. 國字拆解與造字原因\n數：形聲字，「攵」＋「婁」（聲）。本義是一個一個計算→「數星星」（ㄕㄨˇ）；計算出來的結果是數目→「數字、數學」（ㄕㄨˋ）；一次又一次、頻繁→「數見不鮮」（ㄕㄨㄛˋ）。"},
  {id:"p012",grade:2,word:"種子",target:"種",zhuyin:"ㄓㄨㄥˇ",pinyin:"zhǒng",wrong:[{z:"ㄓㄨㄥˋ",p:"zhòng"},{z:"ㄔㄨㄥˊ",p:"chóng"}],note:"「種子」「種類」讀ㄓㄨㄥˇ；「種樹」「種植」讀ㄓㄨㄥˋ。",deep:"1. 注音比較\n種：ㄓㄨㄥˇ（三聲）＝種子、種類；ㄓㄨㄥˋ（四聲）＝種樹、種植；ㄔㄨㄥˊ＝無此音（是「蟲」的讀音）\n2. 國字拆解與造字原因\n種：形聲字，「禾」＋「重」（聲）。本義是穀物的種子（名詞，ㄓㄨㄥˇ），引申為類別；把種子埋進土裡的動作（動詞）讀ㄓㄨㄥˋ。記法：名詞三聲、動詞四聲。"},
  {id:"p013",grade:2,word:"勉強",target:"強",zhuyin:"ㄑㄧㄤˇ",pinyin:"qiǎng",wrong:[{z:"ㄑㄧㄤˊ",p:"qiáng"},{z:"ㄐㄧㄤˋ",p:"jiàng"}],note:"「勉強」「強迫」讀ㄑㄧㄤˇ；「強壯」讀ㄑㄧㄤˊ；「倔強」讀ㄐㄧㄤˋ。",deep:"1. 注音比較\n強：ㄑㄧㄤˇ（三聲）＝勉強、強迫；ㄑㄧㄤˊ（二聲）＝強壯、堅強；ㄐㄧㄤˋ（四聲）＝倔強\n2. 國字拆解與造字原因\n強：形聲字，從「虫」、「弘」聲，本是一種米蟲的名字，後借來表「有力」→「強壯」（ㄑㄧㄤˊ）；用力迫使別人→「勉強、強迫」（ㄑㄧㄤˇ）；個性硬不聽勸→「倔強」（ㄐㄧㄤˋ）。"},
  {id:"p014",grade:2,word:"處理",target:"處",zhuyin:"ㄔㄨˇ",pinyin:"chǔ",wrong:[{z:"ㄔㄨˋ",p:"chù"},{z:"ㄔㄨˊ",p:"chú"}],note:"「處理」「相處」讀ㄔㄨˇ；「到處」「處所」讀ㄔㄨˋ。",deep:"1. 注音比較\n處：ㄔㄨˇ（三聲）＝處理、相處；ㄔㄨˋ（四聲）＝到處、處所；ㄔㄨˊ＝無此音（是「除」的讀音）\n2. 國字拆解與造字原因\n處：從「虍」（虎）從「処」（人靠几而止），本義是停留、安頓。當動詞「安頓、對待」→「處理、相處」（ㄔㄨˇ）；停留的地方（名詞）→「處所、到處」（ㄔㄨˋ）。記法：動詞三聲、名詞四聲。"},
  {id:"p015",grade:2,word:"便利",target:"便",zhuyin:"ㄅㄧㄢˋ",pinyin:"biàn",wrong:[{z:"ㄆㄧㄢˊ",p:"pián"},{z:"ㄅㄧㄢˇ",p:"biǎn"}],note:"「便利」「方便」讀ㄅㄧㄢˋ；「便宜」讀ㄆㄧㄢˊ。",deep:"1. 注音比較\n便：ㄅㄧㄢˋ（四聲）＝便利、方便、便當；ㄆㄧㄢˊ（二聲）＝便宜；ㄅㄧㄢˇ＝無此音（是「貶」的讀音）\n2. 國字拆解與造字原因\n便：會意字，「亻」＋「更」（改變），人調整姿勢使自己安適，本義是安適、順利→「方便、便利」（ㄅㄧㄢˋ）；價錢讓人輕鬆負擔→「便宜」（ㄆㄧㄢˊ）。"},
  {id:"p016",grade:2,word:"便宜",target:"便",zhuyin:"ㄆㄧㄢˊ",pinyin:"pián",wrong:[{z:"ㄅㄧㄢˋ",p:"biàn"},{z:"ㄅㄧㄢ",p:"biān"}],note:"「便宜」讀ㄆㄧㄢˊ；「便當」「順便」讀ㄅㄧㄢˋ。",deep:"1. 注音比較\n便：ㄆㄧㄢˊ（二聲）＝便宜；ㄅㄧㄢˋ（四聲）＝便當、順便、隨便；ㄅㄧㄢ＝無此音（是「邊」的讀音）\n2. 國字拆解與造字原因\n便：「亻」＋「更」，人改變姿勢求安適。表「安適、順利」讀ㄅㄧㄢˋ；只有「便宜」（價格低）一詞讀ㄆㄧㄢˊ，要特別記住。"},
  {id:"p017",grade:2,word:"血液",target:"血",zhuyin:"ㄒㄧㄝˇ",pinyin:"xiě",wrong:[{z:"ㄒㄩㄝˋ",p:"xuè"},{z:"ㄒㄧㄝˋ",p:"xiè"}],note:"審訂音「血」語音讀ㄒㄧㄝˇ，如「血液」「流血」。",deep:"1. 注音比較\n血：ㄒㄧㄝˇ（三聲）＝血液、流血（語音）；ㄒㄩㄝˋ＝舊讀音，審訂表已統讀ㄒㄧㄝˇ；ㄒㄧㄝˋ＝無此音（是「謝」的讀音）\n2. 國字拆解與造字原因\n血：指事字，「皿」（器皿）上加一點，表示祭祀時滴在器皿中的牲血。教育部審訂音把「血」統一讀ㄒㄧㄝˇ，不再分文白讀音。"},
  {id:"p018",grade:2,word:"塞住",target:"塞",zhuyin:"ㄙㄞ",pinyin:"sāi",wrong:[{z:"ㄙㄞˋ",p:"sài"},{z:"ㄙㄜˋ",p:"sè"}],note:"「塞住」「塞車」讀ㄙㄞ；「邊塞」讀ㄙㄞˋ；「閉塞」「阻塞」讀ㄙㄜˋ。",deep:"1. 注音比較\n塞：ㄙㄞ（一聲）＝塞住、塞車；ㄙㄞˋ（四聲）＝邊塞、要塞；ㄙㄜˋ（四聲）＝閉塞、阻塞（文言用法）\n2. 國字拆解與造字原因\n塞：會意兼形聲，「宀」（屋）內用「工」形土塊填堵，下加「土」。本義是填堵→「塞住」（ㄙㄞ）；堵住敵人的邊防要地→「邊塞」（ㄙㄞˋ）；文言的「堵塞不通」→「閉塞、阻塞」（ㄙㄜˋ）。"},
  {id:"p019",grade:2,word:"折斷",target:"折",zhuyin:"ㄓㄜˊ",pinyin:"zhé",wrong:[{z:"ㄕㄜˊ",p:"shé"},{z:"ㄓㄜ",p:"zhē"}],note:"「折斷」「打折」讀ㄓㄜˊ；「繩子折了」（斷）讀ㄕㄜˊ；「折騰」讀ㄓㄜ。",deep:"1. 注音比較\n折：ㄓㄜˊ（二聲）＝折斷、打折、折紙；ㄕㄜˊ（二聲）＝繩子折了（斷掉）、折本；ㄓㄜ（一聲）＝折騰\n2. 國字拆解與造字原因\n折：會意字，「扌（手）」＋「斤」（斧頭），用手拿斧砍斷東西，本義是弄斷→「折斷」（ㄓㄜˊ）；東西自己斷掉、虧損讀ㄕㄜˊ（繩子折了、折本）；翻來覆去讀ㄓㄜ（折騰）。"},
  {id:"p020",grade:2,word:"降低",target:"降",zhuyin:"ㄐㄧㄤˋ",pinyin:"jiàng",wrong:[{z:"ㄒㄧㄤˊ",p:"xiáng"},{z:"ㄍㄤˋ",p:"gàng"}],note:"「降低」「降雨」讀ㄐㄧㄤˋ；「投降」「降服」讀ㄒㄧㄤˊ。",deep:"1. 注音比較\n降：ㄐㄧㄤˋ（四聲）＝降低、降雨、下降；ㄒㄧㄤˊ（二聲）＝投降、降服；ㄍㄤˋ＝無此音\n2. 國字拆解與造字原因\n降：會意字，「阝（阜，土山）」＋「夅」（兩腳向下走），從山上往下走，本義是下來→「下降、降雨」（ㄐㄧㄤˋ）；向敵人低頭屈服→「投降」（ㄒㄧㄤˊ）。"},
  {id:"p021",grade:2,word:"還書",target:"還",zhuyin:"ㄏㄨㄢˊ",pinyin:"huán",wrong:[{z:"ㄏㄞˊ",p:"hái"},{z:"ㄒㄩㄢˊ",p:"xuán"}],note:"「還書」「歸還」讀ㄏㄨㄢˊ；「還有」「還沒」讀ㄏㄞˊ。",deep:"1. 注音比較\n還：ㄏㄨㄢˊ（二聲）＝還書、歸還、還原；ㄏㄞˊ（二聲）＝還有、還沒；ㄒㄩㄢˊ＝無此音（是「旋」的讀音）\n2. 國字拆解與造字原因\n還：形聲字，「辶（走）」＋「瞏」（聲），本義是返回→「歸還、還原」（ㄏㄨㄢˊ）；由「返回」虛化成副詞「仍然、尚且」→「還有、還沒」（ㄏㄞˊ）。"},
  {id:"p022",grade:2,word:"倒水",target:"倒",zhuyin:"ㄉㄠˋ",pinyin:"dào",wrong:[{z:"ㄉㄠˇ",p:"dǎo"},{z:"ㄊㄠˊ",p:"táo"}],note:"「倒水」「倒車」讀ㄉㄠˋ；「跌倒」「倒下」讀ㄉㄠˇ。",deep:"1. 注音比較\n倒：ㄉㄠˋ（四聲）＝倒水、倒車、倒退；ㄉㄠˇ（三聲）＝跌倒、倒下、倒閉；ㄊㄠˊ＝無此音（是「逃」的讀音）\n2. 國字拆解與造字原因\n倒：形聲字，「亻」＋「到」（聲）。人向下傾倒、垮下讀ㄉㄠˇ（跌倒）；上下顛倒、反方向的動作讀ㄉㄠˋ（倒水、倒車）。記法：自己倒下三聲，把東西反過來四聲。"},
  {id:"p023",grade:2,word:"假日",target:"假",zhuyin:"ㄐㄧㄚˋ",pinyin:"jià",wrong:[{z:"ㄐㄧㄚˇ",p:"jiǎ"},{z:"ㄒㄧㄚˊ",p:"xiá"}],note:"「假日」「放假」讀ㄐㄧㄚˋ；「真假」「假裝」讀ㄐㄧㄚˇ。",deep:"1. 注音比較\n假：ㄐㄧㄚˋ（四聲）＝假日、放假、請假；ㄐㄧㄚˇ（三聲）＝真假、假裝、假如；ㄒㄧㄚˊ＝無此音（是「霞」的讀音）\n2. 國字拆解與造字原因\n假：形聲字，「亻」＋「叚」（聲，借），本義是借→不是真的（借來的）讀ㄐㄧㄚˇ（假裝）；向公家「借」來的休息時間讀ㄐㄧㄚˋ（放假）。"},
  {id:"p024",grade:2,word:"中獎",target:"中",zhuyin:"ㄓㄨㄥˋ",pinyin:"zhòng",wrong:[{z:"ㄓㄨㄥ",p:"zhōng"},{z:"ㄔㄨㄥ",p:"chōng"}],note:"「中獎」「猜中」讀ㄓㄨㄥˋ；「中間」「中央」讀ㄓㄨㄥ。",deep:"1. 注音比較\n中：ㄓㄨㄥˋ（四聲）＝中獎、猜中、命中；ㄓㄨㄥ（一聲）＝中間、中央；ㄔㄨㄥ＝無此音（是「充」的讀音）\n2. 國字拆解與造字原因\n中：象形字，像旗杆立在範圍的正中央，本義是中央→「中間」（ㄓㄨㄥ）；射箭正好射到中心→「命中、中獎」（ㄓㄨㄥˋ）。記法：位置一聲，打中目標四聲。"},
  {id:"p025",grade:2,word:"重新",target:"重",zhuyin:"ㄔㄨㄥˊ",pinyin:"chóng",wrong:[{z:"ㄓㄨㄥˋ",p:"zhòng"},{z:"ㄔㄨㄥ",p:"chōng"}],note:"「重新」「重複」讀ㄔㄨㄥˊ；「重量」「重要」讀ㄓㄨㄥˋ。",deep:"1. 注音比較\n重：ㄔㄨㄥˊ（二聲）＝重新、重複、重疊；ㄓㄨㄥˋ（四聲）＝重量、重要；ㄔㄨㄥ＝無此音（是「充」的讀音）\n2. 國字拆解與造字原因\n重：會意字，像人背著沉重的行囊，本義是分量大→「重量、重要」（ㄓㄨㄥˋ）；一層又一層、再來一次→「重複、重新」（ㄔㄨㄥˊ）。"},
  {id:"p026",grade:3,word:"樂器",target:"樂",zhuyin:"ㄩㄝˋ",pinyin:"yuè",wrong:[{z:"ㄌㄜˋ",p:"lè"},{z:"ㄌㄠˋ",p:"lào"}],note:"「樂器」「樂團」讀ㄩㄝˋ；「歡樂」讀ㄌㄜˋ。",deep:"1. 注音比較\n樂：ㄩㄝˋ（四聲）＝樂器、樂團、音樂；ㄌㄜˋ（四聲）＝歡樂、快樂；ㄌㄠˋ＝地名用音（如河北樂亭）\n2. 國字拆解與造字原因\n樂：象形字，像木架上張著絲弦的樂器，本義是樂器、音樂（ㄩㄝˋ）；音樂使人愉悅→「快樂」（ㄌㄜˋ）。與樂器音樂有關讀ㄩㄝˋ。"},
  {id:"p027",grade:3,word:"傳達",target:"傳",zhuyin:"ㄔㄨㄢˊ",pinyin:"chuán",wrong:[{z:"ㄓㄨㄢˋ",p:"zhuàn"},{z:"ㄔㄨㄢˇ",p:"chuǎn"}],note:"「傳達」「流傳」讀ㄔㄨㄢˊ；「傳記」「自傳」讀ㄓㄨㄢˋ。",deep:"1. 注音比較\n傳：ㄔㄨㄢˊ（二聲）＝傳達、流傳、傳球；ㄓㄨㄢˋ（四聲）＝傳記、自傳、水滸傳；ㄔㄨㄢˇ＝無此音（是「喘」的讀音）\n2. 國字拆解與造字原因\n傳：形聲字，「亻」＋「專」（聲），本義是驛站接力遞送文書→輾轉遞送（ㄔㄨㄢˊ，傳達、流傳）；記錄人生平的文字→「傳記」（ㄓㄨㄢˋ）。記法：動詞二聲、書名人物記事四聲。"},
  {id:"p028",grade:3,word:"說服",target:"說",zhuyin:"ㄕㄨㄟˋ",pinyin:"shuì",wrong:[{z:"ㄕㄨㄛ",p:"shuō"},{z:"ㄩㄝˋ",p:"yuè"}],note:"「說服」「遊說」讀ㄕㄨㄟˋ；「說話」讀ㄕㄨㄛ。",deep:"1. 注音比較\n說：ㄕㄨㄟˋ（四聲）＝說服、遊說；ㄕㄨㄛ（一聲）＝說話、說明；ㄩㄝˋ＝通「悅」（文言，不亦說乎）\n2. 國字拆解與造字原因\n說：形聲字，「言」＋「兌」（聲），本義是解釋、講述（ㄕㄨㄛ）；用言語打動別人聽從自己→「說服、遊說」（ㄕㄨㄟˋ）；古通「悅」（ㄩㄝˋ）。"},
  {id:"p029",grade:3,word:"翹起",target:"翹",zhuyin:"ㄑㄧㄠˋ",pinyin:"qiào",wrong:[{z:"ㄑㄧㄠˊ",p:"qiáo"},{z:"ㄑㄧㄠˇ",p:"qiǎo"}],note:"「翹起」「翹尾巴」讀ㄑㄧㄠˋ；「翹首」「翹楚」讀ㄑㄧㄠˊ。",deep:"1. 注音比較\n翹：ㄑㄧㄠˋ（四聲）＝翹起、翹尾巴、翹課；ㄑㄧㄠˊ（二聲）＝翹首、翹楚；ㄑㄧㄠˇ＝無此音\n2. 國字拆解與造字原因\n翹：形聲字，「羽」＋「堯」（聲，高），本義是鳥尾上的長羽，鳥尾上揚→「翹起」（ㄑㄧㄠˋ）；抬頭盼望、出眾之才讀ㄑㄧㄠˊ（翹首、翹楚）。"},
  {id:"p030",grade:3,word:"暴露",target:"露",zhuyin:"ㄌㄨˋ",pinyin:"lù",wrong:[{z:"ㄌㄡˋ",p:"lòu"},{z:"ㄌㄨˊ",p:"lú"}],note:"「暴露」「揭露」讀ㄌㄨˋ；「露臉」「露一手」讀ㄌㄡˋ。",deep:"1. 注音比較\n露：ㄌㄨˋ（四聲）＝暴露、揭露、露水；ㄌㄡˋ（四聲）＝露臉、露一手、露餡（口語）；ㄌㄨˊ＝無此音（是「盧」的讀音）\n2. 國字拆解與造字原因\n露：形聲字，「雨」＋「路」（聲），本義是露水——水氣在外凝結，引申為顯現在外（暴露）。書面語讀ㄌㄨˋ，口語顯現義讀ㄌㄡˋ（露臉、露馬腳）。"},
  {id:"p031",grade:3,word:"骨骼",target:"骼",zhuyin:"ㄍㄜˊ",pinyin:"gé",wrong:[{z:"ㄍㄜˋ",p:"gè"},{z:"ㄌㄨㄛˋ",p:"luò"}],note:"「骨骼」的「骼」讀ㄍㄜˊ。",deep:"1. 注音比較\n骼：ㄍㄜˊ（二聲）＝骨骼；ㄍㄜˋ＝無此音（是「個」的讀音）；ㄌㄨㄛˋ＝無此音（是「洛」的讀音）\n2. 國字拆解與造字原因\n骼：形聲字，「骨」＋「各」（聲），本義是骨頭，「骨骼」指支撐身體的骨架。從「各」得聲的字有的讀ㄍㄜˊ（骼、格），別受「各」（ㄍㄜˋ）影響誤讀。"},
  {id:"p032",grade:3,word:"地殼",target:"殼",zhuyin:"ㄑㄧㄠˋ",pinyin:"qiào",wrong:[{z:"ㄎㄜˊ",p:"ké"},{z:"ㄎㄜˇ",p:"kě"}],note:"「地殼」「金蟬脫殼」讀ㄑㄧㄠˋ；「貝殼」「蛋殼」讀ㄎㄜˊ。",deep:"1. 注音比較\n殼：ㄑㄧㄠˋ（四聲）＝地殼、金蟬脫殼（文讀）；ㄎㄜˊ（二聲）＝貝殼、蛋殼（語讀）；ㄎㄜˇ＝無此音（是「可」的讀音）\n2. 國字拆解與造字原因\n殼：從「殳」（敲擊），本義是堅硬的外皮。日常口語的殼讀ㄎㄜˊ（蛋殼）；學術與成語中的文讀音讀ㄑㄧㄠˋ（地殼、甲殼、金蟬脫殼）。"},
  {id:"p033",grade:3,word:"興趣",target:"興",zhuyin:"ㄒㄧㄥˋ",pinyin:"xìng",wrong:[{z:"ㄒㄧㄥ",p:"xīng"},{z:"ㄒㄧㄥˇ",p:"xǐng"}],note:"「興趣」「高興」讀ㄒㄧㄥˋ；「興起」「興建」讀ㄒㄧㄥ。",deep:"1. 注音比較\n興：ㄒㄧㄥˋ（四聲）＝興趣、高興、興致；ㄒㄧㄥ（一聲）＝興起、興建、復興；ㄒㄧㄥˇ＝無此音（是「醒」的讀音）\n2. 國字拆解與造字原因\n興：會意字，甲骨文像眾人四手共抬一物，本義是抬起、發動→「興建、興起」（ㄒㄧㄥ）；心情被「抬起來」的愉悅感→「高興、興趣」（ㄒㄧㄥˋ）。記法：動詞一聲、情緒四聲。"},
  {id:"p034",grade:3,word:"答應",target:"應",zhuyin:"ㄧㄥˋ",pinyin:"yìng",wrong:[{z:"ㄧㄥ",p:"yīng"},{z:"ㄧㄥˇ",p:"yǐng"}],note:"「答應」「反應」讀ㄧㄥˋ；「應該」「應當」讀ㄧㄥ。",deep:"1. 注音比較\n應：ㄧㄥˋ（四聲）＝答應、反應、應付；ㄧㄥ（一聲）＝應該、應當；ㄧㄥˇ＝無此音（是「影」的讀音）\n2. 國字拆解與造字原因\n應：形聲字，從「心」、「䧹」（聲），本義是心裡回應→「答應、回應」（ㄧㄥˋ）；由「理當回應」引申為「應該」（ㄧㄥ）。記法：回應動作四聲、應該一聲。"},
  {id:"p035",grade:3,word:"乾淨",target:"乾",zhuyin:"ㄍㄢ",pinyin:"gān",wrong:[{z:"ㄑㄧㄢˊ",p:"qián"},{z:"ㄍㄢˋ",p:"gàn"}],note:"「乾淨」「乾燥」讀ㄍㄢ；「乾坤」讀ㄑㄧㄢˊ。",deep:"1. 注音比較\n乾：ㄍㄢ（一聲）＝乾淨、乾燥、餅乾；ㄑㄧㄢˊ（二聲）＝乾坤、乾隆；ㄍㄢˋ＝無此音（是「幹」的讀音）\n2. 國字拆解與造字原因\n乾：形聲字，本義是上出的日光，引申為沒有水分→「乾燥」（ㄍㄢ）；《易經》以乾為天→「乾坤」（ㄑㄧㄢˊ）。記法：沒水分讀ㄍㄢ，天地讀ㄑㄧㄢˊ。"},
  {id:"p036",grade:3,word:"差別",target:"差",zhuyin:"ㄔㄚ",pinyin:"chā",wrong:[{z:"ㄔㄚˋ",p:"chà"},{z:"ㄔㄞ",p:"chāi"}],note:"「差別」「差異」讀ㄔㄚ；「差勁」讀ㄔㄚˋ；「出差」讀ㄔㄞ。",deep:"1. 注音比較\n差：ㄔㄚ（一聲）＝差別、差異、差距；ㄔㄚˋ（四聲）＝差勁、差不多；ㄔㄞ（一聲）＝出差、差遣；（另有ㄘ，參差）\n2. 國字拆解與造字原因\n差：本義是失當、不相合→兩者不同「差別」（ㄔㄚ）；品質不好「差勁」（ㄔㄚˋ）；被派去辦事「出差」（ㄔㄞ）。一字多音都由「不齊、分派」的本義引申。"},
  {id:"p037",grade:3,word:"倒楣",target:"楣",zhuyin:"ㄇㄟˊ",pinyin:"méi",wrong:[{z:"ㄇㄟˇ",p:"měi"},{z:"ㄇㄟˋ",p:"mèi"}],note:"「倒楣」的「楣」讀ㄇㄟˊ，本指門框上的橫木。",deep:"1. 注音比較\n楣：ㄇㄟˊ（二聲）＝倒楣、門楣；ㄇㄟˇ＝無此音（是「美」的讀音）；ㄇㄟˋ＝無此音（是「妹」的讀音）\n2. 國字拆解與造字原因\n楣：形聲字，「木」＋「眉」（聲），本義是門框上的橫木（像門的眉毛）。科舉時代家有喜事在門楣掛旗，失利則「倒楣」——放倒旗杆，引申為運氣不好。"},
  {id:"p038",grade:3,word:"蝸牛",target:"蝸",zhuyin:"ㄍㄨㄚ",pinyin:"guā",wrong:[{z:"ㄨㄛ",p:"wō"},{z:"ㄍㄨㄛ",p:"guō"}],note:"審訂音「蝸牛」的「蝸」讀ㄍㄨㄚ。",deep:"1. 注音比較\n蝸：ㄍㄨㄚ（一聲）＝蝸牛、蝸居（審訂音）；ㄨㄛ＝舊讀，審訂表不採；ㄍㄨㄛ＝無此音（是「鍋」的讀音）\n2. 國字拆解與造字原因\n蝸：形聲字，「虫」＋「咼」（聲），背著螺旋殼的軟體動物。教育部審訂音定讀ㄍㄨㄚ，注意別跟「窩」（ㄨㄛ）混淆。"},
  {id:"p039",grade:3,word:"挑戰",target:"挑",zhuyin:"ㄊㄧㄠˇ",pinyin:"tiǎo",wrong:[{z:"ㄊㄧㄠ",p:"tiāo"},{z:"ㄊㄧㄠˋ",p:"tiào"}],note:"「挑戰」「挑釁」讀ㄊㄧㄠˇ；「挑選」「挑水」讀ㄊㄧㄠ。",deep:"1. 注音比較\n挑：ㄊㄧㄠˇ（三聲）＝挑戰、挑釁、挑燈；ㄊㄧㄠ（一聲）＝挑選、挑水；ㄊㄧㄠˋ＝無此音（是「跳」的讀音）\n2. 國字拆解與造字原因\n挑：形聲字，「扌」＋「兆」（聲）。用肩擔、用眼選讀ㄊㄧㄠ（挑水、挑選）；用竿撥動、引動對方讀ㄊㄧㄠˇ（挑燈、挑戰、挑撥）。"},
  {id:"p040",grade:3,word:"漂亮",target:"漂",zhuyin:"ㄆㄧㄠˋ",pinyin:"piào",wrong:[{z:"ㄆㄧㄠ",p:"piāo"},{z:"ㄆㄧㄠˇ",p:"piǎo"}],note:"「漂亮」讀ㄆㄧㄠˋ；「漂流」讀ㄆㄧㄠ；「漂白」讀ㄆㄧㄠˇ。",deep:"1. 注音比較\n漂：ㄆㄧㄠˋ（四聲）＝漂亮；ㄆㄧㄠ（一聲）＝漂流、漂浮；ㄆㄧㄠˇ（三聲）＝漂白\n2. 國字拆解與造字原因\n漂：形聲字，「氵」＋「票」（聲），本義是浮在水上（ㄆㄧㄠ）；用水沖洗使潔白讀ㄆㄧㄠˇ（漂白）；洗得潔白好看→「漂亮」（ㄆㄧㄠˋ）。三個音是「浮→洗→美」的引申。"},
  {id:"p041",grade:3,word:"曾經",target:"曾",zhuyin:"ㄘㄥˊ",pinyin:"céng",wrong:[{z:"ㄗㄥ",p:"zēng"},{z:"ㄘㄥ",p:"cēng"}],note:"「曾經」讀ㄘㄥˊ；「曾祖父」「姓曾」讀ㄗㄥ。",deep:"1. 注音比較\n曾：ㄘㄥˊ（二聲）＝曾經、未曾；ㄗㄥ（一聲）＝曾祖父、姓曾；ㄘㄥ＝無此音\n2. 國字拆解與造字原因\n曾：象形字，像蒸食的炊具（甑的本字）。假借為副詞「曾經」（ㄘㄥˊ）；隔兩代的親屬「曾祖」與姓氏讀ㄗㄥ。"},
  {id:"p042",grade:3,word:"泡沫",target:"沫",zhuyin:"ㄇㄛˋ",pinyin:"mò",wrong:[{z:"ㄇㄟˋ",p:"mèi"},{z:"ㄇㄚˇ",p:"mǎ"}],note:"「泡沫」的「沫」讀ㄇㄛˋ。",deep:"1. 注音比較\n沫：ㄇㄛˋ（四聲）＝泡沫、口沫；ㄇㄟˋ＝無此音（是「妹」的讀音）；ㄇㄚˇ＝無此音（是「馬」的讀音）\n2. 國字拆解與造字原因\n沫：形聲字，「氵」＋「末」（聲），水的細碎泡泡（末＝細小）。從「末」（ㄇㄛˋ）得聲，別受「妹」影響誤讀。"},
  {id:"p043",grade:4,word:"垃圾",target:"垃",zhuyin:"ㄌㄜˋ",pinyin:"lè",wrong:[{z:"ㄌㄚ",p:"lā"},{z:"ㄌㄞˋ",p:"lài"}],note:"台灣審訂音「垃圾」讀ㄌㄜˋ ㄙㄜˋ。",deep:"1. 注音比較\n垃：ㄌㄜˋ（四聲）＝垃圾（審訂音ㄌㄜˋ ㄙㄜˋ）；ㄌㄚ＝大陸讀法（lājī），台灣審訂表不採；ㄌㄞˋ＝無此音\n2. 國字拆解與造字原因\n垃：形聲字，「土」＋「立」（聲），髒土穢物堆積。台灣審訂音「垃圾」讀ㄌㄜˋ ㄙㄜˋ，與大陸讀音不同，考試以審訂音為準。"},
  {id:"p044",grade:4,word:"液體",target:"液",zhuyin:"ㄧˋ",pinyin:"yì",wrong:[{z:"ㄧㄝˋ",p:"yè"},{z:"ㄧㄝˇ",p:"yě"}],note:"審訂音「液」讀ㄧˋ，如「液體」「血液」。",deep:"1. 注音比較\n液：ㄧˋ（四聲）＝液體、血液、汁液（審訂音）；ㄧㄝˋ＝俗讀，審訂表不採；ㄧㄝˇ＝無此音（是「也」的讀音）\n2. 國字拆解與造字原因\n液：形聲字，「氵」＋「夜」（聲），能流動的水狀物質。審訂音讀ㄧˋ，注意口語常誤讀成ㄧㄝˋ。"},
  {id:"p045",grade:4,word:"攜帶",target:"攜",zhuyin:"ㄒㄧ",pinyin:"xī",wrong:[{z:"ㄒㄧㄝˊ",p:"xié"},{z:"ㄏㄨㄟˊ",p:"huí"}],note:"審訂音「攜」讀ㄒㄧ，如「攜帶」「攜手」。",deep:"1. 注音比較\n攜：ㄒㄧ（一聲）＝攜帶、攜手（審訂音）；ㄒㄧㄝˊ＝俗讀，審訂表不採；ㄏㄨㄟˊ＝無此音\n2. 國字拆解與造字原因\n攜：形聲字，「扌」＋「巂」（聲），用手提著、帶著→攜帶、提攜。審訂音讀ㄒㄧ，常被誤讀成ㄒㄧㄝˊ。"},
  {id:"p046",grade:4,word:"跌倒",target:"跌",zhuyin:"ㄉㄧㄝˊ",pinyin:"dié",wrong:[{z:"ㄉㄧㄝ",p:"diē"},{z:"ㄊㄧㄝ",p:"tiē"}],note:"審訂音「跌」讀ㄉㄧㄝˊ，如「跌倒」「下跌」。",deep:"1. 注音比較\n跌：ㄉㄧㄝˊ（二聲）＝跌倒、下跌（審訂音）；ㄉㄧㄝ＝俗讀一聲，審訂表不採；ㄊㄧㄝ＝無此音（是「貼」的讀音）\n2. 國字拆解與造字原因\n跌：形聲字，「足」＋「失」（聲），腳失去平衡而摔倒——「失足」二字合成一個「跌」字，很好記。審訂音讀二聲ㄉㄧㄝˊ。"},
  {id:"p047",grade:4,word:"攻擊",target:"擊",zhuyin:"ㄐㄧˊ",pinyin:"jí",wrong:[{z:"ㄐㄧ",p:"jī"},{z:"ㄑㄧˋ",p:"qì"}],note:"審訂音「擊」讀ㄐㄧˊ，如「攻擊」「打擊」。",deep:"1. 注音比較\n擊：ㄐㄧˊ（二聲）＝攻擊、打擊、射擊（審訂音）；ㄐㄧ＝俗讀一聲，審訂表不採；ㄑㄧˋ＝無此音\n2. 國字拆解與造字原因\n擊：從「手」，上為「毄」（車軸相撞），用手敲打、攻打。審訂音讀二聲ㄐㄧˊ，口語常誤讀成一聲。"},
  {id:"p048",grade:4,word:"研究",target:"究",zhuyin:"ㄐㄧㄡˋ",pinyin:"jiù",wrong:[{z:"ㄐㄧㄡ",p:"jiū"},{z:"ㄐㄧㄡˇ",p:"jiǔ"}],note:"審訂音「究」讀ㄐㄧㄡˋ，如「研究」「終究」。",deep:"1. 注音比較\n究：ㄐㄧㄡˋ（四聲）＝研究、終究、追究（審訂音）；ㄐㄧㄡ＝俗讀一聲，審訂表不採；ㄐㄧㄡˇ＝無此音（是「九」的讀音）\n2. 國字拆解與造字原因\n究：形聲字，「穴」＋「九」（聲），本義是洞穴的盡頭→追查到底（研究、追究）。審訂音讀四聲ㄐㄧㄡˋ。"},
  {id:"p049",grade:4,word:"曝曬",target:"曝",zhuyin:"ㄆㄨˋ",pinyin:"pù",wrong:[{z:"ㄅㄠˋ",p:"bào"},{z:"ㄆㄠˋ",p:"pào"}],note:"「曝曬」「一曝十寒」讀ㄆㄨˋ；「曝光」亦讀ㄆㄨˋ。",deep:"1. 注音比較\n曝：ㄆㄨˋ（四聲）＝曝曬、曝光、一曝十寒；ㄅㄠˋ＝俗讀，審訂表不採；ㄆㄠˋ＝無此音\n2. 國字拆解與造字原因\n曝：形聲字，「日」＋「暴」（聲），在太陽下曬。「暴」本身就是曬的象形（日下捧米曝曬），加「日」更明確。讀ㄆㄨˋ，「曝光」勿讀成ㄅㄠˋ光。"},
  {id:"p050",grade:4,word:"麻痺",target:"痺",zhuyin:"ㄅㄧˋ",pinyin:"bì",wrong:[{z:"ㄆㄧˊ",p:"pí"},{z:"ㄅㄟˋ",p:"bèi"}],note:"「麻痺」的「痺」讀ㄅㄧˋ。",deep:"1. 注音比較\n痺：ㄅㄧˋ（四聲）＝麻痺；ㄆㄧˊ＝無此音（是「皮」的讀音）；ㄅㄟˋ＝無此音（是「備」的讀音）\n2. 國字拆解與造字原因\n痺：形聲字，「疒」（疾病）＋「卑」（聲），肢體失去知覺的病症→麻痺。疒字旁表示與疾病有關。"},
  {id:"p051",grade:4,word:"骰子",target:"骰",zhuyin:"ㄊㄡˊ",pinyin:"tóu",wrong:[{z:"ㄕㄞˇ",p:"shǎi"},{z:"ㄉㄡˇ",p:"dǒu"}],note:"「骰子」的「骰」讀ㄊㄡˊ，俗讀ㄕㄞˇ非審訂音。",deep:"1. 注音比較\n骰：ㄊㄡˊ（二聲）＝骰子（審訂音）；ㄕㄞˇ＝俗讀（色子），審訂表不採；ㄉㄡˇ＝無此音（是「斗」的讀音）\n2. 國字拆解與造字原因\n骰：形聲字，「骨」＋「投」（省聲），骨頭做的、用來「投」擲的賭具。審訂音讀ㄊㄡˊ，與「投」同音好記。"},
  {id:"p052",grade:4,word:"蛤蜊",target:"蛤",zhuyin:"ㄍㄜˊ",pinyin:"gé",wrong:[{z:"ㄏㄚˊ",p:"há"},{z:"ㄎㄜˊ",p:"ké"}],note:"「蛤蜊」讀ㄍㄜˊ ㄌㄧˊ；「蛤蟆」讀ㄏㄚˊ。",deep:"1. 注音比較\n蛤：ㄍㄜˊ（二聲）＝蛤蜊；ㄏㄚˊ（二聲）＝蛤蟆；ㄎㄜˊ＝無此音（是「殼」的語讀）\n2. 國字拆解與造字原因\n蛤：形聲字，「虫」＋「合」（聲），雙殼「合」起來的貝類→蛤蜊（ㄍㄜˊ）；「蛤蟆」（青蛙、蟾蜍）讀ㄏㄚˊ。同字兩音指不同動物。"},
  {id:"p053",grade:4,word:"混合",target:"混",zhuyin:"ㄏㄨㄣˋ",pinyin:"hùn",wrong:[{z:"ㄏㄨㄣˊ",p:"hún"},{z:"ㄎㄨㄣˋ",p:"kùn"}],note:"「混合」「混亂」讀ㄏㄨㄣˋ；「混水摸魚」的「混」亦讀ㄏㄨㄣˋ。",deep:"1. 注音比較\n混：ㄏㄨㄣˋ（四聲）＝混合、混亂、混水摸魚；ㄏㄨㄣˊ（二聲）＝混蛋（口語罵語）；ㄎㄨㄣˋ＝無此音（是「困」的讀音）\n2. 國字拆解與造字原因\n混：形聲字，「氵」＋「昆」（聲），本義是水勢盛大，水流交雜→摻雜（混合）、雜亂（混亂）。標準音讀ㄏㄨㄣˋ。"},
  {id:"p054",grade:4,word:"寧可",target:"寧",zhuyin:"ㄋㄧㄥˊ",pinyin:"níng",wrong:[{z:"ㄋㄧㄥˋ",p:"nìng"},{z:"ㄋㄧㄥˇ",p:"nǐng"}],note:"審訂音「寧可」「寧願」讀ㄋㄧㄥˊ；「寧死不屈」亦讀ㄋㄧㄥˊ。",deep:"1. 注音比較\n寧：ㄋㄧㄥˊ（二聲）＝寧可、寧願、安寧、寧死不屈（審訂音統讀）；ㄋㄧㄥˋ＝舊讀（寧可），審訂表不採；ㄋㄧㄥˇ＝無此音\n2. 國字拆解與造字原因\n寧：會意字，屋（宀）內有食器（皿），豐衣足食心安定，本義是安定→安寧；「寧可」是「情願求安」的引申。審訂音一律讀ㄋㄧㄥˊ。"},
  {id:"p055",grade:4,word:"率領",target:"率",zhuyin:"ㄕㄨㄞˋ",pinyin:"shuài",wrong:[{z:"ㄌㄩˋ",p:"lǜ"},{z:"ㄕㄨㄛˋ",p:"shuò"}],note:"「率領」「率先」讀ㄕㄨㄞˋ；「效率」「機率」讀ㄌㄩˋ。",deep:"1. 注音比較\n率：ㄕㄨㄞˋ（四聲）＝率領、率先、坦率；ㄌㄩˋ（四聲）＝效率、機率、比率；ㄕㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n率：象形字，像捕鳥的網，本義是循著、帶領→「率領」（ㄕㄨㄞˋ）；數學上兩數相比的值讀ㄌㄩˋ（比率、效率）。記法：帶頭讀ㄕㄨㄞˋ，數值讀ㄌㄩˋ。"},
  {id:"p056",grade:4,word:"參差",target:"參",zhuyin:"ㄘㄣ",pinyin:"cēn",wrong:[{z:"ㄘㄢ",p:"cān"},{z:"ㄕㄣ",p:"shēn"}],note:"「參差不齊」讀ㄘㄣ ㄘ；「參加」讀ㄘㄢ；「人參」讀ㄕㄣ。",deep:"1. 注音比較\n參：ㄘㄣ（一聲）＝參差不齊；ㄘㄢ（一聲）＝參加、參觀；ㄕㄣ（一聲）＝人參、海參\n2. 國字拆解與造字原因\n參：象形字，像參星（三顆星）在人頭上，本義是星宿名（ㄕㄣ）；三者並列引申為加入其中→「參加」（ㄘㄢ）；長短不齊→「參差」（ㄘㄣ）。一字三音各司其職。"},
  {id:"p057",grade:4,word:"當鋪",target:"當",zhuyin:"ㄉㄤˋ",pinyin:"dàng",wrong:[{z:"ㄉㄤ",p:"dāng"},{z:"ㄊㄤˊ",p:"táng"}],note:"「當鋪」「典當」「上當」讀ㄉㄤˋ；「當然」「當時」讀ㄉㄤ。",deep:"1. 注音比較\n當：ㄉㄤˋ（四聲）＝當鋪、典當、上當、當作；ㄉㄤ（一聲）＝當然、當時、擔當；ㄊㄤˊ＝無此音（是「堂」的讀音）\n2. 國字拆解與造字原因\n當：形聲字，「田」＋「尚」（聲），本義是兩塊田相抵、相等→面對、承擔讀ㄉㄤ（當面、擔當）；用物品抵押換錢讀ㄉㄤˋ（典當、當鋪）。"},
  {id:"p058",grade:4,word:"分量",target:"量",zhuyin:"ㄌㄧㄤˋ",pinyin:"liàng",wrong:[{z:"ㄌㄧㄤˊ",p:"liáng"},{z:"ㄌㄧㄤˇ",p:"liǎng"}],note:"「分量」「重量」讀ㄌㄧㄤˋ；「測量」「量身」讀ㄌㄧㄤˊ。",deep:"1. 注音比較\n量：ㄌㄧㄤˋ（四聲）＝分量、重量、力量；ㄌㄧㄤˊ（二聲）＝測量、量身、量體溫；ㄌㄧㄤˇ＝無此音（是「兩」的讀音）\n2. 國字拆解與造字原因\n量：從「重（省）」，上像量器開口，本義是用器具計測（動詞，ㄌㄧㄤˊ）；計測的結果、多寡（名詞）讀ㄌㄧㄤˋ。記法：動詞二聲、名詞四聲。"},
  {id:"p059",grade:4,word:"迷藏",target:"藏",zhuyin:"ㄘㄤˊ",pinyin:"cáng",wrong:[{z:"ㄗㄤˋ",p:"zàng"},{z:"ㄔㄤˊ",p:"cháng"}],note:"「捉迷藏」「收藏」讀ㄘㄤˊ；「寶藏」「西藏」讀ㄗㄤˋ。",deep:"1. 注音比較\n藏：ㄘㄤˊ（二聲）＝捉迷藏、收藏、躲藏；ㄗㄤˋ（四聲）＝寶藏、西藏、藏族；ㄔㄤˊ＝無此音（是「常」的讀音）\n2. 國字拆解與造字原因\n藏：形聲字，「艹」＋「臧」（聲），草木遮蔽而隱匿→躲藏（ㄘㄤˊ）；收存起來的珍寶、儲藏之所讀ㄗㄤˋ（寶藏）。記法：動作二聲、名詞四聲。"},
  {id:"p060",grade:4,word:"稱職",target:"稱",zhuyin:"ㄔㄣˋ",pinyin:"chèn",wrong:[{z:"ㄔㄥ",p:"chēng"},{z:"ㄔㄥˋ",p:"chèng"}],note:"「稱職」「稱心」「對稱」讀ㄔㄣˋ；「稱讚」「名稱」讀ㄔㄥ。",deep:"1. 注音比較\n稱：ㄔㄣˋ（四聲）＝稱職、稱心、對稱、相稱；ㄔㄥ（一聲）＝稱讚、名稱、稱呼；ㄔㄥˋ＝同「秤」（磅秤）\n2. 國字拆解與造字原因\n稱：形聲字，「禾」＋「爯」（舉），舉起穀物衡量輕重，本義是衡量→叫出名號（稱呼，ㄔㄥ）；輕重恰好相合→「稱職、對稱」（ㄔㄣˋ）。"},
  {id:"p061",grade:4,word:"要求",target:"要",zhuyin:"ㄧㄠ",pinyin:"yāo",wrong:[{z:"ㄧㄠˋ",p:"yào"},{z:"ㄧㄠˇ",p:"yǎo"}],note:"「要求」「要脅」讀ㄧㄠ；「重要」「需要」讀ㄧㄠˋ。",deep:"1. 注音比較\n要：ㄧㄠ（一聲）＝要求、要脅；ㄧㄠˋ（四聲）＝重要、需要、要不要；ㄧㄠˇ＝無此音（是「咬」的讀音）\n2. 國字拆解與造字原因\n要：象形字，像人雙手叉腰，本義是腰（「腰」的本字）。腰是身體中樞→重要（ㄧㄠˋ）；攔腰截求、強求讀ㄧㄠ（要求、要脅）。"},
  {id:"p062",grade:4,word:"呼喊",target:"喊",zhuyin:"ㄏㄢˇ",pinyin:"hǎn",wrong:[{z:"ㄏㄢˋ",p:"hàn"},{z:"ㄎㄢˇ",p:"kǎn"}],note:"「呼喊」的「喊」讀ㄏㄢˇ。",deep:"1. 注音比較\n喊：ㄏㄢˇ（三聲）＝呼喊、喊叫；ㄏㄢˋ＝無此音（是「漢」的讀音）；ㄎㄢˇ＝無此音（是「砍」的讀音）\n2. 國字拆解與造字原因\n喊：形聲字，「口」＋「咸」（聲），大聲呼叫。從「咸」得聲的字有喊（ㄏㄢˇ）、鹹（ㄒㄧㄢˊ）、減（ㄐㄧㄢˇ），聲隨字轉，別誤讀。"},
  {id:"p063",grade:4,word:"膝蓋",target:"膝",zhuyin:"ㄒㄧ",pinyin:"xī",wrong:[{z:"ㄑㄧ",p:"qī"},{z:"ㄒㄧˊ",p:"xí"}],note:"「膝蓋」的「膝」讀ㄒㄧ，常被誤讀成ㄑㄧ。",deep:"1. 注音比較\n膝：ㄒㄧ（一聲）＝膝蓋、護膝、促膝長談；ㄑㄧ＝誤讀（受「漆」影響）；ㄒㄧˊ＝無此音（是「習」的讀音）\n2. 國字拆解與造字原因\n膝：形聲字，「月（肉）」＋「桼」（聲），大腿小腿相接的關節。「桼」是「漆」的本字，但「膝」讀ㄒㄧ不讀ㄑㄧ，是常見誤讀字。"},
  {id:"p064",grade:4,word:"符合",target:"符",zhuyin:"ㄈㄨˊ",pinyin:"fú",wrong:[{z:"ㄈㄨˇ",p:"fǔ"},{z:"ㄈㄨˋ",p:"fù"}],note:"「符合」「符號」讀ㄈㄨˊ。",deep:"1. 注音比較\n符：ㄈㄨˊ（二聲）＝符合、符號、護身符；ㄈㄨˇ＝無此音（是「府」的讀音）；ㄈㄨˋ＝無此音（是「付」的讀音）\n2. 國字拆解與造字原因\n符：形聲字，「竹」＋「付」（聲），古代用竹片做的信物，剖成兩半，相合為證→「符合」（兩半相合）、「符號」（表意的記號）。"},
  {id:"p065",grade:4,word:"氛圍",target:"氛",zhuyin:"ㄈㄣ",pinyin:"fēn",wrong:[{z:"ㄈㄣˋ",p:"fèn"},{z:"ㄈㄣˊ",p:"fén"}],note:"「氣氛」「氛圍」的「氛」讀ㄈㄣ，常被誤讀成ㄈㄣˋ。",deep:"1. 注音比較\n氛：ㄈㄣ（一聲）＝氣氛、氛圍（審訂音）；ㄈㄣˋ＝誤讀；ㄈㄣˊ＝無此音（是「墳」的讀音）\n2. 國字拆解與造字原因\n氛：形聲字，「气」＋「分」（聲），瀰漫的雲氣，引申為環境中的情調感覺→氣氛。讀一聲ㄈㄣ，「氣氛」勿讀成「氣ㄈㄣˋ」。"},
  {id:"p066",grade:5,word:"倔強",target:"倔",zhuyin:"ㄐㄩㄝˊ",pinyin:"jué",wrong:[{z:"ㄐㄩㄝˋ",p:"juè"},{z:"ㄑㄩ",p:"qū"}],note:"「倔強」讀ㄐㄩㄝˊ ㄐㄧㄤˋ。",deep:"1. 注音比較\n倔：ㄐㄩㄝˊ（二聲）＝倔強；ㄐㄩㄝˋ＝誤讀；ㄑㄩ＝無此音（是「屈」的讀音）\n2. 國字拆解與造字原因\n倔：形聲字，「亻」＋「屈」（聲），性情剛硬不肯屈服→「倔強」（ㄐㄩㄝˊ ㄐㄧㄤˋ）。注意「強」在此讀ㄐㄧㄤˋ。"},
  {id:"p067",grade:5,word:"栽贓",target:"贓",zhuyin:"ㄗㄤ",pinyin:"zāng",wrong:[{z:"ㄗㄤˋ",p:"zàng"},{z:"ㄘㄤˊ",p:"cáng"}],note:"「栽贓」「贓物」的「贓」讀ㄗㄤ。",deep:"1. 注音比較\n贓：ㄗㄤ（一聲）＝栽贓、贓物、貪贓枉法；ㄗㄤˋ＝誤讀；ㄘㄤˊ＝無此音（是「藏」的讀音）\n2. 國字拆解與造字原因\n贓：形聲字，「貝」（錢財）＋「臧」（聲），用不正當手段得來的財物→贓款、贓物。讀一聲ㄗㄤ。"},
  {id:"p068",grade:5,word:"松柏",target:"柏",zhuyin:"ㄅㄛˊ",pinyin:"bó",wrong:[{z:"ㄅㄞˇ",p:"bǎi"},{z:"ㄆㄛˋ",p:"pò"}],note:"審訂音「松柏」「柏樹」讀ㄅㄛˊ；「柏油」讀ㄅㄞˇ。",deep:"1. 注音比較\n柏：ㄅㄛˊ（二聲）＝松柏、柏樹、柏林（審訂音）；ㄅㄞˇ（三聲）＝柏油；ㄆㄛˋ＝無此音（是「魄」的讀音）\n2. 國字拆解與造字原因\n柏：形聲字，「木」＋「白」（聲），常綠喬木。樹木義審訂音讀ㄅㄛˊ（松柏長青）；外來語音譯「柏油」讀ㄅㄞˇ。"},
  {id:"p069",grade:5,word:"剖析",target:"剖",zhuyin:"ㄆㄡˇ",pinyin:"pǒu",wrong:[{z:"ㄆㄛ",p:"pō"},{z:"ㄈㄡˇ",p:"fǒu"}],note:"「剖析」「解剖」的「剖」讀ㄆㄡˇ。",deep:"1. 注音比較\n剖：ㄆㄡˇ（三聲）＝剖析、解剖、剖開；ㄆㄛ＝無此音；ㄈㄡˇ＝無此音（是「否」的讀音）\n2. 國字拆解與造字原因\n剖：形聲字，「刂」（刀）＋「咅」（聲），用刀切開→解剖；把道理切開細看→剖析。讀ㄆㄡˇ。"},
  {id:"p070",grade:5,word:"畸形",target:"畸",zhuyin:"ㄐㄧ",pinyin:"jī",wrong:[{z:"ㄑㄧˊ",p:"qí"},{z:"ㄧˋ",p:"yì"}],note:"「畸形」的「畸」讀ㄐㄧ，常被誤讀成ㄑㄧˊ。",deep:"1. 注音比較\n畸：ㄐㄧ（一聲）＝畸形、畸零地；ㄑㄧˊ＝誤讀（受「奇」影響）；ㄧˋ＝無此音\n2. 國字拆解與造字原因\n畸：形聲字，「田」＋「奇」（聲），本義是劃分田地後剩下的不方正零地→不正常、不整齊（畸形）。從「奇」得聲卻讀ㄐㄧ，常考誤讀字。"},
  {id:"p071",grade:5,word:"堤防",target:"堤",zhuyin:"ㄊㄧˊ",pinyin:"tí",wrong:[{z:"ㄉㄧ",p:"dī"},{z:"ㄕˋ",p:"shì"}],note:"審訂音「堤」讀ㄊㄧˊ，如「堤防」「河堤」。",deep:"1. 注音比較\n堤：ㄊㄧˊ（二聲）＝堤防、河堤、堤岸（審訂音）；ㄉㄧ＝大陸及俗讀，審訂表不採；ㄕˋ＝無此音\n2. 國字拆解與造字原因\n堤：形聲字，「土」＋「是」（聲），沿水邊築起擋水的土壩。台灣審訂音讀ㄊㄧˊ，與「提」同音好記。"},
  {id:"p072",grade:5,word:"包紮",target:"紮",zhuyin:"ㄓㄚˊ",pinyin:"zhá",wrong:[{z:"ㄗㄚ",p:"zā"},{z:"ㄓㄚˇ",p:"zhǎ"}],note:"審訂音「包紮」「駐紮」的「紮」讀ㄓㄚˊ。",deep:"1. 注音比較\n紮：ㄓㄚˊ（二聲）＝包紮、駐紮（審訂音）；ㄗㄚ＝俗讀，審訂表不採；ㄓㄚˇ＝無此音\n2. 國字拆解與造字原因\n紮：形聲字，「糸」（繩）＋「札」（聲），用繩捆綁→包紮；軍隊「捆好行囊安營」→駐紮。審訂音讀ㄓㄚˊ。"},
  {id:"p073",grade:5,word:"匕首",target:"匕",zhuyin:"ㄅㄧˇ",pinyin:"bǐ",wrong:[{z:"ㄅㄧˋ",p:"bì"},{z:"ㄆㄧˇ",p:"pǐ"}],note:"「匕首」的「匕」讀ㄅㄧˇ。",deep:"1. 注音比較\n匕：ㄅㄧˇ（三聲）＝匕首；ㄅㄧˋ＝誤讀；ㄆㄧˇ＝無此音（是「匹」的讀音）\n2. 國字拆解與造字原因\n匕：象形字，像古代取食的匙勺，也像短劍之形→匕首（短劍，柄頭如匙）。讀三聲ㄅㄧˇ。"},
  {id:"p074",grade:5,word:"庇護",target:"庇",zhuyin:"ㄅㄧˋ",pinyin:"bì",wrong:[{z:"ㄆㄧˋ",p:"pì"},{z:"ㄅㄧˇ",p:"bǐ"}],note:"「庇護」「庇蔭」的「庇」讀ㄅㄧˋ。",deep:"1. 注音比較\n庇：ㄅㄧˋ（四聲）＝庇護、庇蔭、包庇；ㄆㄧˋ＝誤讀；ㄅㄧˇ＝無此音（是「比」的讀音）\n2. 國字拆解與造字原因\n庇：形聲字，「广」（屋）＋「比」（聲），在屋簷下遮蔽→保護（庇護）。讀ㄅㄧˋ。"},
  {id:"p075",grade:5,word:"呵護",target:"呵",zhuyin:"ㄏㄜ",pinyin:"hē",wrong:[{z:"ㄎㄜ",p:"kē"},{z:"ㄚ",p:"ā"}],note:"「呵護」「呵斥」的「呵」讀ㄏㄜ。",deep:"1. 注音比較\n呵：ㄏㄜ（一聲）＝呵護、呵斥、呵氣；ㄎㄜ＝無此音；ㄚ＝語氣詞用法（同「啊」）\n2. 國字拆解與造字原因\n呵：形聲字，「口」＋「可」（聲），本義是大聲責喝（呵斥），呵氣取暖引申為照顧保護（呵護）。讀ㄏㄜ。"},
  {id:"p076",grade:5,word:"綻放",target:"綻",zhuyin:"ㄓㄢˋ",pinyin:"zhàn",wrong:[{z:"ㄉㄧㄥˋ",p:"dìng"},{z:"ㄔㄢˊ",p:"chán"}],note:"「綻放」「破綻」的「綻」讀ㄓㄢˋ。",deep:"1. 注音比較\n綻：ㄓㄢˋ（四聲）＝綻放、破綻、皮開肉綻；ㄉㄧㄥˋ＝無此音（是「定」的讀音）；ㄔㄢˊ＝無此音\n2. 國字拆解與造字原因\n綻：形聲字，「糸」＋「定」（聲），本義是衣縫裂開（破綻）→花苞裂開盛開（綻放）。從「定」得聲卻讀ㄓㄢˋ，常考。"},
  {id:"p077",grade:5,word:"憧憬",target:"憧",zhuyin:"ㄔㄨㄥ",pinyin:"chōng",wrong:[{z:"ㄊㄨㄥˊ",p:"tóng"},{z:"ㄓㄨㄤˋ",p:"zhuàng"}],note:"「憧憬」讀ㄔㄨㄥ ㄐㄧㄥˇ。",deep:"1. 注音比較\n憧：ㄔㄨㄥ（一聲）＝憧憬；ㄊㄨㄥˊ＝誤讀（受「童」影響）；ㄓㄨㄤˋ＝無此音（是「撞」的讀音）\n2. 國字拆解與造字原因\n憧：形聲字，「忄」＋「童」（聲），心神往來不定，引申為對未來的嚮往→「憧憬」（ㄔㄨㄥ ㄐㄧㄥˇ）。"},
  {id:"p078",grade:5,word:"瀰漫",target:"瀰",zhuyin:"ㄇㄧˊ",pinyin:"mí",wrong:[{z:"ㄋㄧˊ",p:"ní"},{z:"ㄇㄧˇ",p:"mǐ"}],note:"「瀰漫」的「瀰」讀ㄇㄧˊ。",deep:"1. 注音比較\n瀰：ㄇㄧˊ（二聲）＝瀰漫；ㄋㄧˊ＝無此音（是「泥」的讀音）；ㄇㄧˇ＝無此音（是「米」的讀音）\n2. 國字拆解與造字原因\n瀰：形聲字，「氵」＋「彌」（聲），水滿布的樣子→煙霧、氣氛滿布（瀰漫）。與「彌」同音ㄇㄧˊ。"},
  {id:"p079",grade:5,word:"贗品",target:"贗",zhuyin:"ㄧㄢˋ",pinyin:"yàn",wrong:[{z:"ㄧㄥ",p:"yīng"},{z:"ㄧㄢˊ",p:"yán"}],note:"「贗品」的「贗」讀ㄧㄢˋ，偽造的意思。",deep:"1. 注音比較\n贗：ㄧㄢˋ（四聲）＝贗品；ㄧㄥ＝無此音（是「鷹」的讀音）；ㄧㄢˊ＝無此音（是「言」的讀音）\n2. 國字拆解與造字原因\n贗：形聲字，「貝」（財貨）＋「雁」（聲），偽造的財貨→贗品（假貨）。與「雁」形近，但讀ㄧㄢˋ。"},
  {id:"p080",grade:5,word:"魁梧",target:"梧",zhuyin:"ㄨˊ",pinyin:"wú",wrong:[{z:"ㄨˇ",p:"wǔ"},{z:"ㄨˋ",p:"wù"}],note:"「魁梧」讀ㄎㄨㄟˊ ㄨˊ。",deep:"1. 注音比較\n梧：ㄨˊ（二聲）＝魁梧、梧桐；ㄨˇ＝誤讀；ㄨˋ＝無此音（是「悟」的讀音）\n2. 國字拆解與造字原因\n梧：形聲字，「木」＋「吾」（聲），梧桐樹高大挺直→形容人高大壯碩（魁梧，ㄎㄨㄟˊ ㄨˊ）。"},
  {id:"p081",grade:5,word:"淬鍊",target:"淬",zhuyin:"ㄘㄨㄟˋ",pinyin:"cuì",wrong:[{z:"ㄗㄨˊ",p:"zú"},{z:"ㄙㄨㄟˋ",p:"suì"}],note:"「淬鍊」「淬火」的「淬」讀ㄘㄨㄟˋ。",deep:"1. 注音比較\n淬：ㄘㄨㄟˋ（四聲）＝淬鍊、淬火；ㄗㄨˊ＝無此音（是「卒」的讀音）；ㄙㄨㄟˋ＝無此音（是「碎」的讀音）\n2. 國字拆解與造字原因\n淬：形聲字，「氵」＋「卒」（聲），鑄劍時把燒紅的金屬浸入水中使堅硬→淬火；引申為磨練（淬鍊）。讀ㄘㄨㄟˋ。"},
  {id:"p082",grade:5,word:"粗糙",target:"糙",zhuyin:"ㄘㄠ",pinyin:"cāo",wrong:[{z:"ㄗㄠˋ",p:"zào"},{z:"ㄘㄠˋ",p:"cào"}],note:"「粗糙」的「糙」讀ㄘㄠ。",deep:"1. 注音比較\n糙：ㄘㄠ（一聲）＝粗糙、糙米；ㄗㄠˋ＝無此音（是「造」的讀音）；ㄘㄠˋ＝誤讀\n2. 國字拆解與造字原因\n糙：形聲字，「米」＋「造」（聲），米沒舂精，表面粗礪→糙米；引申為不細緻（粗糙）。讀一聲ㄘㄠ。"},
  {id:"p083",grade:5,word:"執拗",target:"拗",zhuyin:"ㄋㄧㄡˋ",pinyin:"niù",wrong:[{z:"ㄠˇ",p:"ǎo"},{z:"ㄠˋ",p:"ào"}],note:"「執拗」（固執）讀ㄋㄧㄡˋ；「拗斷」讀ㄠˇ。",deep:"1. 注音比較\n拗：ㄋㄧㄡˋ（四聲）＝執拗（固執）；ㄠˇ（三聲）＝拗斷、拗折；ㄠˋ（四聲）＝拗口\n2. 國字拆解與造字原因\n拗：形聲字，「扌」＋「幼」（聲），本義是用手折彎（ㄠˇ，拗斷）；性子彆扭不順讀ㄋㄧㄡˋ（執拗）；文句念起來不順讀ㄠˋ（拗口）。一字三音依語義區分。"},
  {id:"p084",grade:5,word:"友誼",target:"誼",zhuyin:"ㄧˋ",pinyin:"yì",wrong:[{z:"ㄧˊ",p:"yí"},{z:"ㄧˇ",p:"yǐ"}],note:"「友誼」「情誼」的「誼」讀ㄧˋ。",deep:"1. 注音比較\n誼：ㄧˋ（四聲）＝友誼、情誼、聯誼；ㄧˊ＝誤讀（受「宜」影響）；ㄧˇ＝無此音\n2. 國字拆解與造字原因\n誼：形聲字，「言」＋「宜」（聲），本義是合宜的道理，引申為人與人合宜的交情→友誼。從「宜」得聲卻讀ㄧˋ，常考誤讀字。"},
  {id:"p085",grade:5,word:"氣魄",target:"魄",zhuyin:"ㄆㄛˋ",pinyin:"pò",wrong:[{z:"ㄅㄛˊ",p:"bó"},{z:"ㄊㄨㄛˋ",p:"tuò"}],note:"「氣魄」「魄力」讀ㄆㄛˋ；「落魄」亦讀ㄆㄛˋ。",deep:"1. 注音比較\n魄：ㄆㄛˋ（四聲）＝氣魄、魄力、落魄；ㄅㄛˊ＝「落魄」舊讀，審訂表統讀ㄆㄛˋ；ㄊㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n魄：形聲字，「鬼」＋「白」（聲），古人認為依附形體的精神為「魄」（魂魄）→精神力量（氣魄、魄力）。審訂音統讀ㄆㄛˋ。"},
  {id:"p086",grade:6,word:"沮喪",target:"沮",zhuyin:"ㄐㄩˇ",pinyin:"jǔ",wrong:[{z:"ㄑㄧㄝˇ",p:"qiě"},{z:"ㄗㄨˇ",p:"zǔ"}],note:"「沮喪」的「沮」讀ㄐㄩˇ。",deep:"1. 注音比較\n沮：ㄐㄩˇ（三聲）＝沮喪；ㄑㄧㄝˇ＝無此音（是「且」的讀音）；ㄗㄨˇ＝無此音（是「阻」的讀音）\n2. 國字拆解與造字原因\n沮：形聲字，「氵」＋「且」（聲），本義是水名，假借表頹敗、氣餒→沮喪。讀ㄐㄩˇ，別受「阻」影響誤讀。"},
  {id:"p087",grade:6,word:"賦予",target:"賦",zhuyin:"ㄈㄨˋ",pinyin:"fù",wrong:[{z:"ㄈㄨˇ",p:"fǔ"},{z:"ㄨˇ",p:"wǔ"}],note:"「賦予」「天賦」的「賦」讀ㄈㄨˋ。",deep:"1. 注音比較\n賦：ㄈㄨˋ（四聲）＝賦予、天賦、詩詞歌賦；ㄈㄨˇ＝無此音（是「腐」的讀音）；ㄨˇ＝無此音\n2. 國字拆解與造字原因\n賦：形聲字，「貝」（財）＋「武」（聲），本義是徵收田稅→朝廷「給與」人民負擔，引申為授與（賦予）、天生具備（天賦），也是文體名（漢賦）。"},
  {id:"p088",grade:6,word:"毋庸置疑",target:"毋",zhuyin:"ㄨˊ",pinyin:"wú",wrong:[{z:"ㄨˋ",p:"wù"},{z:"ㄇㄨˇ",p:"mǔ"}],note:"「毋」讀ㄨˊ，不要、不可的意思。",deep:"1. 注音比較\n毋：ㄨˊ（二聲）＝毋庸置疑、寧缺毋濫；ㄨˋ＝無此音（是「勿」的讀音）；ㄇㄨˇ＝無此音（是「母」的讀音）\n2. 國字拆解與造字原因\n毋：指事字，「母」字加一筆貫穿，表示禁止之意——不要、不可。與「母」形近，注意分辨：毋（ㄨˊ）中間是一橫貫穿，母（ㄇㄨˇ）是兩點。"},
  {id:"p089",grade:6,word:"阻撓",target:"撓",zhuyin:"ㄋㄠˊ",pinyin:"náo",wrong:[{z:"ㄖㄠˊ",p:"ráo"},{z:"ㄋㄠˇ",p:"nǎo"}],note:"「阻撓」「不屈不撓」的「撓」讀ㄋㄠˊ。",deep:"1. 注音比較\n撓：ㄋㄠˊ（二聲）＝阻撓、不屈不撓；ㄖㄠˊ＝無此音（是「饒」的讀音）；ㄋㄠˇ＝無此音（是「惱」的讀音）\n2. 國字拆解與造字原因\n撓：形聲字，「扌」＋「堯」（聲），本義是攪動、使彎曲→阻撓（從中攪擾）、不屈不撓（不彎曲）。讀ㄋㄠˊ。"},
  {id:"p090",grade:6,word:"闢謠",target:"闢",zhuyin:"ㄆㄧˋ",pinyin:"pì",wrong:[{z:"ㄅㄧˋ",p:"bì"},{z:"ㄆㄧ",p:"pī"}],note:"「闢謠」「開闢」的「闢」讀ㄆㄧˋ。",deep:"1. 注音比較\n闢：ㄆㄧˋ（四聲）＝闢謠、開闢、精闢；ㄅㄧˋ＝古通「避」「辟」的讀音；ㄆㄧ＝無此音（是「批」的讀音）\n2. 國字拆解與造字原因\n闢：形聲字，「門」＋「辟」（聲），本義是打開門→開拓（開闢）、駁斥使真相打開（闢謠）。讀ㄆㄧˋ。"},
  {id:"p091",grade:6,word:"塑膠",target:"塑",zhuyin:"ㄙㄨˋ",pinyin:"sù",wrong:[{z:"ㄕㄨㄛˋ",p:"shuò"},{z:"ㄙㄨㄛˋ",p:"suò"}],note:"「塑膠」「雕塑」的「塑」讀ㄙㄨˋ。",deep:"1. 注音比較\n塑：ㄙㄨˋ（四聲）＝塑膠、雕塑、塑造；ㄕㄨㄛˋ＝無此音（是「朔」的讀音）；ㄙㄨㄛˋ＝誤讀\n2. 國字拆解與造字原因\n塑：形聲字，「土」＋「朔」（聲），用泥土捏造形象→雕塑、塑造。從「朔」（ㄕㄨㄛˋ）得聲卻讀ㄙㄨˋ，常考誤讀字。"},
  {id:"p092",grade:6,word:"琺瑯",target:"琺",zhuyin:"ㄈㄚˋ",pinyin:"fà",wrong:[{z:"ㄈㄚ",p:"fā"},{z:"ㄈㄚˇ",p:"fǎ"}],note:"「琺瑯」讀ㄈㄚˋ ㄌㄤˊ。",deep:"1. 注音比較\n琺：ㄈㄚˋ（四聲）＝琺瑯；ㄈㄚ＝無此音（是「發」的讀音）；ㄈㄚˇ＝無此音（是「法」的讀音）\n2. 國字拆解與造字原因\n琺：形聲字，「𤣩（玉）」＋「法」（聲），外來語音譯字，「琺瑯」（ㄈㄚˋ ㄌㄤˊ）是覆在金屬表面的玻璃質釉料。"},
  {id:"p093",grade:6,word:"卓越",target:"卓",zhuyin:"ㄓㄨㄛˊ",pinyin:"zhuó",wrong:[{z:"ㄓㄠ",p:"zhāo"},{z:"ㄉㄧㄠˋ",p:"diào"}],note:"「卓越」「卓見」的「卓」讀ㄓㄨㄛˊ。",deep:"1. 注音比較\n卓：ㄓㄨㄛˊ（二聲）＝卓越、卓見、卓然；ㄓㄠ＝無此音；ㄉㄧㄠˋ＝無此音（是「吊」的讀音）\n2. 國字拆解與造字原因\n卓：會意字，像人高立之形，本義是高超、直立→卓越、卓然出眾。讀ㄓㄨㄛˊ。"},
  {id:"p094",grade:6,word:"稽查",target:"稽",zhuyin:"ㄐㄧ",pinyin:"jī",wrong:[{z:"ㄑㄧˇ",p:"qǐ"},{z:"ㄐㄧˋ",p:"jì"}],note:"「稽查」「稽核」讀ㄐㄧ；「稽首」讀ㄑㄧˇ。",deep:"1. 注音比較\n稽：ㄐㄧ（一聲）＝稽查、稽核、無稽之談；ㄑㄧˇ（三聲）＝稽首（叩頭禮）；ㄐㄧˋ＝無此音（是「計」的讀音）\n2. 國字拆解與造字原因\n稽：形聲字，「禾」＋「尤」「旨」，本義是停留查考→稽查、稽核（ㄐㄧ）；古代叩頭至地停留的大禮讀ㄑㄧˇ（稽首）。"},
  {id:"p095",grade:6,word:"綜合",target:"綜",zhuyin:"ㄗㄨㄥˋ",pinyin:"zòng",wrong:[{z:"ㄗㄨㄥ",p:"zōng"},{z:"ㄘㄨㄥˊ",p:"cóng"}],note:"審訂音「綜合」的「綜」讀ㄗㄨㄥˋ。",deep:"1. 注音比較\n綜：ㄗㄨㄥˋ（四聲）＝綜合、綜覽、錯綜複雜（審訂音）；ㄗㄨㄥ＝俗讀，審訂表不採；ㄘㄨㄥˊ＝無此音\n2. 國字拆解與造字原因\n綜：形聲字，「糸」＋「宗」（聲），本義是織布機上總持經線的部件→總聚各方（綜合）。審訂音讀四聲ㄗㄨㄥˋ。"},
  {id:"p096",grade:6,word:"矜持",target:"矜",zhuyin:"ㄐㄧㄣ",pinyin:"jīn",wrong:[{z:"ㄑㄧㄣˊ",p:"qín"},{z:"ㄍㄨㄢ",p:"guān"}],note:"「矜持」「自矜」的「矜」讀ㄐㄧㄣ。",deep:"1. 注音比較\n矜：ㄐㄧㄣ（一聲）＝矜持、自矜、矜憫；ㄑㄧㄣˊ＝古音（矛柄義）；ㄍㄨㄢ＝古通「鰥」\n2. 國字拆解與造字原因\n矜：形聲字，「矛」＋「今」（聲），本義是矛柄，假借表自重、莊重→矜持；自誇→自矜。今讀ㄐㄧㄣ。"},
  {id:"p097",grade:6,word:"僥倖",target:"僥",zhuyin:"ㄐㄧㄠˇ",pinyin:"jiǎo",wrong:[{z:"ㄧㄠˊ",p:"yáo"},{z:"ㄒㄧㄠˇ",p:"xiǎo"}],note:"「僥倖」讀ㄐㄧㄠˇ ㄒㄧㄥˋ。",deep:"1. 注音比較\n僥：ㄐㄧㄠˇ（三聲）＝僥倖；ㄧㄠˊ＝古音（僬僥，傳說矮人國）；ㄒㄧㄠˇ＝無此音\n2. 國字拆解與造字原因\n僥：形聲字，「亻」＋「堯」（聲），「僥倖」（ㄐㄧㄠˇ ㄒㄧㄥˋ）指意外獲得成功或免於災禍——貪求非分的好運。"},
  {id:"p098",grade:6,word:"骨髓",target:"髓",zhuyin:"ㄙㄨㄟˇ",pinyin:"suǐ",wrong:[{z:"ㄙㄨㄟˊ",p:"suí"},{z:"ㄙㄨㄟˋ",p:"suì"}],note:"「骨髓」「精髓」的「髓」讀ㄙㄨㄟˇ。",deep:"1. 注音比較\n髓：ㄙㄨㄟˇ（三聲）＝骨髓、精髓、腦髓；ㄙㄨㄟˊ＝誤讀（受「隨」影響）；ㄙㄨㄟˋ＝無此音（是「歲」的讀音）\n2. 國字拆解與造字原因\n髓：形聲字，「骨」＋「隨（省）」（聲），骨頭中的膏狀組織→骨髓；事物的精華→精髓。讀三聲ㄙㄨㄟˇ。"},
  {id:"p099",grade:6,word:"露臉",target:"露",zhuyin:"ㄌㄡˋ",pinyin:"lòu",wrong:[{z:"ㄌㄨˋ",p:"lù"},{z:"ㄌㄡˊ",p:"lóu"}],note:"口語「露臉」「露餡」讀ㄌㄡˋ；書面「露水」「揭露」讀ㄌㄨˋ。",deep:"1. 注音比較\n露：ㄌㄡˋ（四聲）＝露臉、露餡、露一手（口語）；ㄌㄨˋ（四聲）＝露水、揭露、暴露（書面）；ㄌㄡˊ＝無此音（是「樓」的讀音）\n2. 國字拆解與造字原因\n露：「雨」＋「路」（聲），本義是露水。書面語讀ㄌㄨˋ；口語「顯現出來」讀ㄌㄡˋ（露臉、露馬腳）。記法：口語顯現ㄌㄡˋ、書面ㄌㄨˋ。"},
  {id:"p100",grade:6,word:"薄弱",target:"薄",zhuyin:"ㄅㄛˊ",pinyin:"bó",wrong:[{z:"ㄅㄠˊ",p:"báo"},{z:"ㄅㄛˋ",p:"bò"}],note:"「薄弱」「刻薄」讀ㄅㄛˊ；口語「很薄」讀ㄅㄠˊ；「薄荷」讀ㄅㄛˋ。",deep:"1. 注音比較\n薄：ㄅㄛˊ（二聲）＝薄弱、刻薄、單薄（書面）；ㄅㄠˊ（二聲）＝很薄、薄片（口語）；ㄅㄛˋ（四聲）＝薄荷\n2. 國字拆解與造字原因\n薄：形聲字，「艹」＋「溥」（聲），本義是草木叢生處，假借表厚度小。書面詞讀ㄅㄛˊ（薄弱、淡薄）；口語讀ㄅㄠˊ（紙很薄）；「薄荷」專讀ㄅㄛˋ。"},
  // ---- 國中 7-9（p101-p200）----
  {id:"p101",grade:7,word:"莘莘學子",target:"莘",zhuyin:"ㄒㄧㄣ",pinyin:"xīn",wrong:[{z:"ㄕㄣ",p:"shēn"},{z:"ㄒㄧㄥ",p:"xīng"}],note:"「莘莘學子」的「莘」讀ㄒㄧㄣ，眾多的樣子。",deep:"1. 注音比較\n莘：ㄒㄧㄣ（一聲）＝莘莘學子；ㄕㄣ（一聲）＝莘（地名、姓氏）；ㄒㄧㄥ＝無此音\n2. 國字拆解與造字原因\n莘：形聲字，「艹」＋「辛」（聲），「莘莘」形容眾多的樣子。「莘莘學子」讀ㄒㄧㄣ，注意不是ㄕㄣ。"},
  {id:"p102",grade:7,word:"肄業",target:"肄",zhuyin:"ㄧˋ",pinyin:"yì",wrong:[{z:"ㄙˋ",p:"sì"},{z:"ㄌㄧˋ",p:"lì"}],note:"「肄業」的「肄」讀ㄧˋ，修習之意，勿與「肆」混淆。",deep:"1. 注音比較\n肄：ㄧˋ（四聲）＝肄業；ㄙˋ＝無此音（是「肆」的讀音）；ㄌㄧˋ＝無此音\n2. 國字拆解與造字原因\n肄：從「聿」（筆），本義是學習、修習→肄業（在學修習尚未畢業）。與「肆」（ㄙˋ，放肆）形近，注意左半不同。"},
  {id:"p103",grade:7,word:"造詣",target:"詣",zhuyin:"ㄧˋ",pinyin:"yì",wrong:[{z:"ㄓˇ",p:"zhǐ"},{z:"ㄑㄧˇ",p:"qǐ"}],note:"「造詣」的「詣」讀ㄧˋ，學問技藝所達到的境界。",deep:"1. 注音比較\n詣：ㄧˋ（四聲）＝造詣；ㄓˇ＝無此音（是「旨」的讀音）；ㄑㄧˇ＝無此音\n2. 國字拆解與造字原因\n詣：形聲字，「言」＋「旨」（聲），本義是前往拜訪，引申為學問技藝「到達」的境界→造詣。從「旨」得聲卻讀ㄧˋ。"},
  {id:"p104",grade:7,word:"贍養",target:"贍",zhuyin:"ㄕㄢˋ",pinyin:"shàn",wrong:[{z:"ㄓㄢ",p:"zhān"},{z:"ㄉㄢ",p:"dān"}],note:"「贍養」的「贍」讀ㄕㄢˋ，供給之意。",deep:"1. 注音比較\n贍：ㄕㄢˋ（四聲）＝贍養；ㄓㄢ＝無此音（是「瞻」的讀音）；ㄉㄢ＝無此音\n2. 國字拆解與造字原因\n贍：形聲字，「貝」（財）＋「詹」（聲），供給財物→贍養（供養長輩）。與「瞻」（ㄓㄢ，瞻仰）同聲符不同音。"},
  {id:"p105",grade:7,word:"未遂",target:"遂",zhuyin:"ㄙㄨㄟˋ",pinyin:"suì",wrong:[{z:"ㄙㄨㄟˊ",p:"suí"},{z:"ㄓㄨㄟˋ",p:"zhuì"}],note:"「未遂」「遂心」的「遂」讀ㄙㄨㄟˋ；「半身不遂」讀ㄙㄨㄟˊ。",deep:"1. 注音比較\n遂：ㄙㄨㄟˋ（四聲）＝未遂、遂心、遂願；ㄙㄨㄟˊ（二聲）＝半身不遂；ㄓㄨㄟˋ＝無此音（是「贅」的讀音）\n2. 國字拆解與造字原因\n遂：形聲字，「辶」＋「㒸」（聲），本義是前進達成→順遂、未遂（沒達成）；肢體「行不通」的「半身不遂」讀ㄙㄨㄟˊ。"},
  {id:"p106",grade:7,word:"倉皇",target:"皇",zhuyin:"ㄏㄨㄤˊ",pinyin:"huáng",wrong:[{z:"ㄨㄤˊ",p:"wáng"},{z:"ㄏㄨㄤˇ",p:"huǎng"}],note:"「倉皇」讀ㄘㄤ ㄏㄨㄤˊ，匆忙慌張的樣子。",deep:"1. 注音比較\n皇：ㄏㄨㄤˊ（二聲）＝倉皇、皇帝、堂皇；ㄨㄤˊ＝無此音（是「王」的讀音）；ㄏㄨㄤˇ＝無此音（是「謊」的讀音）\n2. 國字拆解與造字原因\n皇：從「白」從「王」，本義是大、輝煌→皇帝。「倉皇」（匆忙慌張）借「皇」表音，讀ㄏㄨㄤˊ。"},
  {id:"p107",grade:7,word:"馴服",target:"馴",zhuyin:"ㄒㄩㄣˊ",pinyin:"xún",wrong:[{z:"ㄒㄩㄣˋ",p:"xùn"},{z:"ㄕㄨㄣˋ",p:"shùn"}],note:"「馴服」「溫馴」的「馴」讀ㄒㄩㄣˊ。",deep:"1. 注音比較\n馴：ㄒㄩㄣˊ（二聲）＝馴服、溫馴、馴養；ㄒㄩㄣˋ＝誤讀（受「訓」影響）；ㄕㄨㄣˋ＝無此音（是「順」的讀音）\n2. 國字拆解與造字原因\n馴：形聲字，「馬」＋「川」（聲），馬順從如川水順流→馴服、溫馴。讀二聲ㄒㄩㄣˊ。"},
  {id:"p108",grade:7,word:"胸脯",target:"脯",zhuyin:"ㄆㄨˊ",pinyin:"pú",wrong:[{z:"ㄈㄨˇ",p:"fǔ"},{z:"ㄅㄨˇ",p:"bǔ"}],note:"「胸脯」讀ㄆㄨˊ；「果脯」「肉脯」讀ㄈㄨˇ。",deep:"1. 注音比較\n脯：ㄆㄨˊ（二聲）＝胸脯；ㄈㄨˇ（三聲）＝果脯、肉脯（乾製食品）；ㄅㄨˇ＝無此音\n2. 國字拆解與造字原因\n脯：形聲字，「月（肉）」＋「甫」（聲）。指胸膛讀ㄆㄨˊ（胸脯）；指晒乾的肉果讀ㄈㄨˇ（肉脯、果脯）。一字兩音指不同東西。"},
  {id:"p109",grade:7,word:"憎恨",target:"憎",zhuyin:"ㄗㄥ",pinyin:"zēng",wrong:[{z:"ㄗㄥˋ",p:"zèng"},{z:"ㄘㄥˊ",p:"céng"}],note:"「憎恨」「愛憎」的「憎」讀ㄗㄥ，常被誤讀成ㄗㄥˋ。",deep:"1. 注音比較\n憎：ㄗㄥ（一聲）＝憎恨、愛憎、面目可憎；ㄗㄥˋ＝誤讀（受「贈」影響）；ㄘㄥˊ＝無此音（是「曾」的讀音）\n2. 國字拆解與造字原因\n憎：形聲字，「忄」＋「曾」（聲），心生厭惡→憎恨。讀一聲ㄗㄥ，別受「贈」（ㄗㄥˋ）影響。"},
  {id:"p110",grade:7,word:"陶冶",target:"冶",zhuyin:"ㄧㄝˇ",pinyin:"yě",wrong:[{z:"ㄓˋ",p:"zhì"},{z:"ㄊㄞˊ",p:"tái"}],note:"「陶冶」「冶金」的「冶」讀ㄧㄝˇ，勿與「治」混淆。",deep:"1. 注音比較\n冶：ㄧㄝˇ（三聲）＝陶冶、冶金、冶煉；ㄓˋ＝無此音（是「治」的讀音）；ㄊㄞˊ＝無此音\n2. 國字拆解與造字原因\n冶：從「冫」（冰），本義是銷熔金屬（冰融與金屬熔化意象相通）→冶金；鎔鑄性情→陶冶。與「治」（氵旁）形近音異，注意分辨。"},
  {id:"p111",grade:7,word:"氣餒",target:"餒",zhuyin:"ㄋㄟˇ",pinyin:"něi",wrong:[{z:"ㄊㄨㄛˇ",p:"tuǒ"},{z:"ㄋㄨㄛˋ",p:"nuò"}],note:"「氣餒」的「餒」讀ㄋㄟˇ，喪失勇氣。",deep:"1. 注音比較\n餒：ㄋㄟˇ（三聲）＝氣餒、勝不驕敗不餒；ㄊㄨㄛˇ＝無此音；ㄋㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n餒：形聲字，「食」＋「妥」（聲），本義是飢餓——餓了就沒力氣，引申為喪失勇氣→氣餒。讀ㄋㄟˇ。"},
  {id:"p112",grade:7,word:"堆砌",target:"砌",zhuyin:"ㄑㄧˋ",pinyin:"qì",wrong:[{z:"ㄑㄧㄝˋ",p:"qiè"},{z:"ㄒㄧˋ",p:"xì"}],note:"「堆砌」「砌牆」的「砌」讀ㄑㄧˋ。",deep:"1. 注音比較\n砌：ㄑㄧˋ（四聲）＝堆砌、砌牆、雕欄玉砌；ㄑㄧㄝˋ＝俗讀（如堆砌ㄑㄧㄝˋ），審訂表不採；ㄒㄧˋ＝無此音\n2. 國字拆解與造字原因\n砌：形聲字，「石」＋「切」（聲），用石塊層層疊築→砌牆；文章堆疊詞藻→堆砌。讀ㄑㄧˋ。"},
  {id:"p113",grade:7,word:"莞爾",target:"莞",zhuyin:"ㄨㄢˇ",pinyin:"wǎn",wrong:[{z:"ㄍㄨㄢˇ",p:"guǎn"},{z:"ㄨㄢˊ",p:"wán"}],note:"「莞爾一笑」的「莞」讀ㄨㄢˇ。",deep:"1. 注音比較\n莞：ㄨㄢˇ（三聲）＝莞爾一笑；ㄍㄨㄢˇ（三聲）＝東莞（地名）；ㄨㄢˊ＝無此音\n2. 國字拆解與造字原因\n莞：形聲字，「艹」＋「完」（聲），本義是水草蓆草。「莞爾」是微笑的樣子（《論語》「夫子莞爾而笑」），讀ㄨㄢˇ；地名「東莞」讀ㄍㄨㄢˇ。"},
  {id:"p114",grade:7,word:"憔悴",target:"悴",zhuyin:"ㄘㄨㄟˋ",pinyin:"cuì",wrong:[{z:"ㄗㄨˋ",p:"zù"},{z:"ㄙㄨㄟˋ",p:"suì"}],note:"「憔悴」讀ㄑㄧㄠˊ ㄘㄨㄟˋ。",deep:"1. 注音比較\n悴：ㄘㄨㄟˋ（四聲）＝憔悴；ㄗㄨˋ＝無此音；ㄙㄨㄟˋ＝無此音（是「碎」的讀音）\n2. 國字拆解與造字原因\n悴：形聲字，「忄」＋「卒」（聲），心力交瘁而面容枯槁→「憔悴」（ㄑㄧㄠˊ ㄘㄨㄟˋ）。"},
  {id:"p115",grade:7,word:"戛然而止",target:"戛",zhuyin:"ㄐㄧㄚˊ",pinyin:"jiá",wrong:[{z:"ㄍㄚ",p:"gā"},{z:"ㄓㄚˊ",p:"zhá"}],note:"「戛然而止」的「戛」讀ㄐㄧㄚˊ，聲音突然停止。",deep:"1. 注音比較\n戛：ㄐㄧㄚˊ（二聲）＝戛然而止；ㄍㄚ＝誤讀；ㄓㄚˊ＝無此音\n2. 國字拆解與造字原因\n戛：從「戈」，本義是長矛，敲擊聲「戛然」借其音——「戛然而止」形容聲音突然停止。讀ㄐㄧㄚˊ。"},
  {id:"p116",grade:7,word:"綺麗",target:"綺",zhuyin:"ㄑㄧˇ",pinyin:"qǐ",wrong:[{z:"ㄧˇ",p:"yǐ"},{z:"ㄑㄧˊ",p:"qí"}],note:"「綺麗」「羅綺」的「綺」讀ㄑㄧˇ。",deep:"1. 注音比較\n綺：ㄑㄧˇ（三聲）＝綺麗、羅綺、綺想；ㄧˇ＝無此音；ㄑㄧˊ＝誤讀（受「奇」影響）\n2. 國字拆解與造字原因\n綺：形聲字，「糸」＋「奇」（聲），有花紋的絲織品→華美（綺麗）。從「奇」得聲卻讀ㄑㄧˇ。"},
  {id:"p117",grade:7,word:"手帕",target:"帕",zhuyin:"ㄆㄚˋ",pinyin:"pà",wrong:[{z:"ㄆㄛˋ",p:"pò"},{z:"ㄅㄚˋ",p:"bà"}],note:"「手帕」的「帕」讀ㄆㄚˋ。",deep:"1. 注音比較\n帕：ㄆㄚˋ（四聲）＝手帕；ㄆㄛˋ＝無此音（是「魄」的讀音）；ㄅㄚˋ＝無此音（是「爸」的讀音）\n2. 國字拆解與造字原因\n帕：形聲字，「巾」＋「白」（聲），擦拭用的小方巾→手帕。讀ㄆㄚˋ。"},
  {id:"p118",grade:7,word:"要脅",target:"脅",zhuyin:"ㄒㄧㄝˊ",pinyin:"xié",wrong:[{z:"ㄒㄧㄝˋ",p:"xiè"},{z:"ㄐㄧㄝˊ",p:"jié"}],note:"「要脅」「脅迫」的「脅」讀ㄒㄧㄝˊ。",deep:"1. 注音比較\n脅：ㄒㄧㄝˊ（二聲）＝要脅、脅迫、威脅；ㄒㄧㄝˋ＝誤讀；ㄐㄧㄝˊ＝無此音\n2. 國字拆解與造字原因\n脅：從「月（肉）」、「劦」（聲），本義是腋下肋骨部位——從兩肋挾制人→威脅、脅迫。讀ㄒㄧㄝˊ。"},
  {id:"p119",grade:7,word:"猙獰",target:"獰",zhuyin:"ㄋㄧㄥˊ",pinyin:"níng",wrong:[{z:"ㄋㄧㄥˇ",p:"nǐng"},{z:"ㄋㄧㄥˋ",p:"nìng"}],note:"「猙獰」讀ㄓㄥ ㄋㄧㄥˊ。",deep:"1. 注音比較\n獰：ㄋㄧㄥˊ（二聲）＝猙獰、獰笑；ㄋㄧㄥˇ＝無此音；ㄋㄧㄥˋ＝無此音（是「濘」的讀音）\n2. 國字拆解與造字原因\n獰：形聲字，「犭」＋「寧」（聲），面目凶惡如猛獸→「猙獰」（ㄓㄥ ㄋㄧㄥˊ）。"},
  {id:"p120",grade:7,word:"手腕",target:"腕",zhuyin:"ㄨㄢˋ",pinyin:"wàn",wrong:[{z:"ㄨㄢˇ",p:"wǎn"},{z:"ㄨㄢ",p:"wān"}],note:"「手腕」「腕力」的「腕」讀ㄨㄢˋ。",deep:"1. 注音比較\n腕：ㄨㄢˋ（四聲）＝手腕、腕力、鐵腕；ㄨㄢˇ＝誤讀；ㄨㄢ＝無此音（是「彎」的讀音）\n2. 國字拆解與造字原因\n腕：形聲字，「月（肉）」＋「宛」（聲），手掌與前臂相接的部位→手腕；引申為手段（鐵腕）。讀ㄨㄢˋ。"},
  {id:"p121",grade:8,word:"膾炙人口",target:"膾",zhuyin:"ㄎㄨㄞˋ",pinyin:"kuài",wrong:[{z:"ㄏㄨㄟˋ",p:"huì"},{z:"ㄎㄨㄛˋ",p:"kuò"}],note:"「膾」讀ㄎㄨㄞˋ，細切的肉。",deep:"1. 注音比較\n膾：ㄎㄨㄞˋ（四聲）＝膾炙人口；ㄏㄨㄟˋ＝誤讀（受「會」影響）；ㄎㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n膾：形聲字，「月（肉）」＋「會」（聲），細切的魚、肉片——古人視為美味。「膾炙人口」的「膾」讀ㄎㄨㄞˋ，與「快」同音。"},
  {id:"p122",grade:8,word:"矯揉造作",target:"矯",zhuyin:"ㄐㄧㄠˇ",pinyin:"jiǎo",wrong:[{z:"ㄑㄧㄠˊ",p:"qiáo"},{z:"ㄐㄧㄠ",p:"jiāo"}],note:"「矯揉造作」「矯正」的「矯」讀ㄐㄧㄠˇ。",deep:"1. 注音比較\n矯：ㄐㄧㄠˇ（三聲）＝矯正、矯揉造作、矯健；ㄑㄧㄠˊ＝無此音（是「僑」的讀音）；ㄐㄧㄠ＝無此音（是「驕」的讀音）\n2. 國字拆解與造字原因\n矯：形聲字，「矢」（箭）＋「喬」（聲），本義是把箭桿弄直→矯正；故意做作→矯揉造作。讀ㄐㄧㄠˇ。"},
  {id:"p123",grade:8,word:"瞠目結舌",target:"瞠",zhuyin:"ㄔㄥ",pinyin:"chēng",wrong:[{z:"ㄊㄤˊ",p:"táng"},{z:"ㄓㄥ",p:"zhēng"}],note:"「瞠目結舌」的「瞠」讀ㄔㄥ，瞪眼直視。",deep:"1. 注音比較\n瞠：ㄔㄥ（一聲）＝瞠目結舌、瞠乎其後；ㄊㄤˊ＝誤讀（受「堂」影響）；ㄓㄥ＝無此音\n2. 國字拆解與造字原因\n瞠：形聲字，「目」＋「堂」（聲），瞪大眼睛直視→瞠目結舌。從「堂」得聲卻讀ㄔㄥ，常考誤讀字。"},
  {id:"p124",grade:8,word:"傀儡",target:"儡",zhuyin:"ㄌㄟˇ",pinyin:"lěi",wrong:[{z:"ㄌㄟˊ",p:"léi"},{z:"ㄌㄟˋ",p:"lèi"}],note:"「傀儡」讀ㄎㄨㄟˇ ㄌㄟˇ。",deep:"1. 注音比較\n儡：ㄌㄟˇ（三聲）＝傀儡；ㄌㄟˊ＝無此音（是「雷」的讀音）；ㄌㄟˋ＝無此音（是「淚」的讀音）\n2. 國字拆解與造字原因\n儡：形聲字，「亻」＋「畾」（聲），「傀儡」（ㄎㄨㄟˇ ㄌㄟˇ）是提線木偶，引申為受人操縱的人。"},
  {id:"p125",grade:8,word:"骷髏",target:"髏",zhuyin:"ㄌㄡˊ",pinyin:"lóu",wrong:[{z:"ㄌㄡˇ",p:"lǒu"},{z:"ㄌㄨˊ",p:"lú"}],note:"「骷髏」讀ㄎㄨ ㄌㄡˊ。",deep:"1. 注音比較\n髏：ㄌㄡˊ（二聲）＝骷髏；ㄌㄡˇ＝無此音；ㄌㄨˊ＝無此音（是「顱」的讀音）\n2. 國字拆解與造字原因\n髏：形聲字，「骨」＋「婁」（聲），「骷髏」（ㄎㄨ ㄌㄡˊ）是乾枯的死人頭骨或全副骨骸。"},
  {id:"p126",grade:8,word:"贖罪",target:"贖",zhuyin:"ㄕㄨˊ",pinyin:"shú",wrong:[{z:"ㄉㄨˊ",p:"dú"},{z:"ㄕㄨˇ",p:"shǔ"}],note:"「贖罪」「贖回」的「贖」讀ㄕㄨˊ。",deep:"1. 注音比較\n贖：ㄕㄨˊ（二聲）＝贖罪、贖回、贖金；ㄉㄨˊ＝無此音（是「讀」的讀音）；ㄕㄨˇ＝無此音（是「屬」的舊讀）\n2. 國字拆解與造字原因\n贖：形聲字，「貝」（財）＋「賣」（聲），用財物換回人或物→贖回、贖罪（用行動抵過）。讀ㄕㄨˊ。"},
  {id:"p127",grade:8,word:"箴言",target:"箴",zhuyin:"ㄓㄣ",pinyin:"zhēn",wrong:[{z:"ㄒㄧㄢˊ",p:"xián"},{z:"ㄐㄧㄢ",p:"jiān"}],note:"「箴言」的「箴」讀ㄓㄣ，規勸告誡的話。",deep:"1. 注音比較\n箴：ㄓㄣ（一聲）＝箴言、箴規；ㄒㄧㄢˊ＝無此音（是「鹹」的讀音）；ㄐㄧㄢ＝無此音\n2. 國字拆解與造字原因\n箴：形聲字，「竹」＋「咸」（聲），本義是竹製的針——針刺引申為規勸告誡→箴言。與「針」同源，讀ㄓㄣ。"},
  {id:"p128",grade:8,word:"對峙",target:"峙",zhuyin:"ㄓˋ",pinyin:"zhì",wrong:[{z:"ㄕˋ",p:"shì"},{z:"ㄙˋ",p:"sì"}],note:"「對峙」的「峙」讀ㄓˋ，相對而立。",deep:"1. 注音比較\n峙：ㄓˋ（四聲）＝對峙、聳峙；ㄕˋ＝無此音（是「侍」的讀音）；ㄙˋ＝無此音（是「寺」的讀音）\n2. 國字拆解與造字原因\n峙：形聲字，「山」＋「寺」（聲），山高聳立→聳峙；兩方像山一樣相對而立→對峙。從「寺」得聲卻讀ㄓˋ。"},
  {id:"p129",grade:8,word:"粗獷",target:"獷",zhuyin:"ㄍㄨㄤˇ",pinyin:"guǎng",wrong:[{z:"ㄎㄨㄤˋ",p:"kuàng"},{z:"ㄍㄨㄤ",p:"guāng"}],note:"「粗獷」的「獷」讀ㄍㄨㄤˇ，常被誤讀成ㄎㄨㄤˋ。",deep:"1. 注音比較\n獷：ㄍㄨㄤˇ（三聲）＝粗獷；ㄎㄨㄤˋ＝誤讀（受「礦」影響）；ㄍㄨㄤ＝無此音（是「光」的讀音）\n2. 國字拆解與造字原因\n獷：形聲字，「犭」＋「廣」（聲），本義是兇悍的犬，引申為粗野豪放→粗獷。讀ㄍㄨㄤˇ，常被誤讀成ㄎㄨㄤˋ。"},
  {id:"p130",grade:8,word:"糟蹋",target:"蹋",zhuyin:"ㄊㄚˋ",pinyin:"tà",wrong:[{z:"ㄊㄚ",p:"tā"},{z:"ㄉㄚˋ",p:"dà"}],note:"「糟蹋」的「蹋」讀ㄊㄚˋ。",deep:"1. 注音比較\n蹋：ㄊㄚˋ（四聲）＝糟蹋；ㄊㄚ＝無此音（是「塌」的讀音）；ㄉㄚˋ＝無此音\n2. 國字拆解與造字原因\n蹋：形聲字，「足」＋「}（聲），用腳踩→「糟蹋」本指踐踏，引申為浪費、不愛惜。讀ㄊㄚˋ。"},
  {id:"p131",grade:8,word:"埋怨",target:"埋",zhuyin:"ㄇㄢˊ",pinyin:"mán",wrong:[{z:"ㄇㄞˊ",p:"mái"},{z:"ㄇㄞˋ",p:"mài"}],note:"「埋怨」讀ㄇㄢˊ；「埋葬」「掩埋」讀ㄇㄞˊ。",deep:"1. 注音比較\n埋：ㄇㄢˊ（二聲）＝埋怨；ㄇㄞˊ（二聲）＝埋葬、掩埋、埋伏；ㄇㄞˋ＝無此音（是「賣」的讀音）\n2. 國字拆解與造字原因\n埋：「土」＋「里」（聲），把東西藏進土裡（ㄇㄞˊ）；心中怨氣悶著又發出來→「埋怨」（ㄇㄢˊ）。記法：只有「埋怨」讀ㄇㄢˊ。"},
  {id:"p132",grade:8,word:"造船廠",target:"廠",zhuyin:"ㄔㄤˇ",pinyin:"chǎng",wrong:[{z:"ㄔㄤˊ",p:"cháng"},{z:"ㄕㄤˇ",p:"shǎng"}],note:"「工廠」「廠房」的「廠」讀ㄔㄤˇ。",deep:"1. 注音比較\n廠：ㄔㄤˇ（三聲）＝工廠、廠房、造船廠；ㄔㄤˊ＝誤讀（受「場」影響）；ㄕㄤˇ＝無此音（是「賞」的讀音）\n2. 國字拆解與造字原因\n廠：從「广」（依山崖建的房），無牆或寬敞的作業屋舍→工廠。讀三聲ㄔㄤˇ。"},
  {id:"p133",grade:8,word:"堡壘",target:"壘",zhuyin:"ㄌㄟˇ",pinyin:"lěi",wrong:[{z:"ㄌㄟˋ",p:"lèi"},{z:"ㄌㄩˇ",p:"lǚ"}],note:"「堡壘」「壁壘」的「壘」讀ㄌㄟˇ。",deep:"1. 注音比較\n壘：ㄌㄟˇ（三聲）＝堡壘、壁壘、兩軍對壘；ㄌㄟˋ＝誤讀（受「累」影響）；ㄌㄩˇ＝無此音（是「旅」的讀音）\n2. 國字拆解與造字原因\n壘：形聲字，「畾」（聲）＋「土」，堆土築成的軍事工事→堡壘、棒球的壘包。讀ㄌㄟˇ。"},
  {id:"p134",grade:8,word:"諂媚",target:"諂",zhuyin:"ㄔㄢˇ",pinyin:"chǎn",wrong:[{z:"ㄒㄧㄢˋ",p:"xiàn"},{z:"ㄧㄢˋ",p:"yàn"}],note:"「諂媚」的「諂」讀ㄔㄢˇ，奉承巴結。",deep:"1. 注音比較\n諂：ㄔㄢˇ（三聲）＝諂媚、諂笑；ㄒㄧㄢˋ＝誤讀（受「陷」影響）；ㄧㄢˋ＝無此音\n2. 國字拆解與造字原因\n諂：形聲字，「言」＋「臽」（聲），用甜言蜜語奉承巴結→諂媚。讀ㄔㄢˇ，與「產」同音。"},
  {id:"p135",grade:8,word:"贊助",target:"贊",zhuyin:"ㄗㄢˋ",pinyin:"zàn",wrong:[{z:"ㄗㄢ",p:"zān"},{z:"ㄘㄢˊ",p:"cán"}],note:"「贊助」「贊成」的「贊」讀ㄗㄢˋ。",deep:"1. 注音比較\n贊：ㄗㄢˋ（四聲）＝贊助、贊成、贊同；ㄗㄢ＝無此音（是「簪」的讀音）；ㄘㄢˊ＝無此音（是「殘」的讀音）\n2. 國字拆解與造字原因\n贊：從「貝」（財物），本義是進見時獻上財禮→輔助（贊助）、同意（贊成）。讀ㄗㄢˋ。"},
  {id:"p136",grade:8,word:"陷阱",target:"阱",zhuyin:"ㄐㄧㄥˇ",pinyin:"jǐng",wrong:[{z:"ㄐㄧㄥˋ",p:"jìng"},{z:"ㄒㄧㄥˊ",p:"xíng"}],note:"「陷阱」的「阱」讀ㄐㄧㄥˇ。",deep:"1. 注音比較\n阱：ㄐㄧㄥˇ（三聲）＝陷阱；ㄐㄧㄥˋ＝誤讀；ㄒㄧㄥˊ＝無此音（是「刑」的讀音）\n2. 國字拆解與造字原因\n阱：形聲字，「阝（阜）」＋「井」（聲），捕獸的坑洞——像口井一樣的坑→陷阱。與「井」同讀三聲ㄐㄧㄥˇ。"},
  {id:"p137",grade:8,word:"竣工",target:"竣",zhuyin:"ㄐㄩㄣˋ",pinyin:"jùn",wrong:[{z:"ㄙㄨㄣ",p:"sūn"},{z:"ㄑㄩㄣ",p:"qūn"}],note:"「竣工」的「竣」讀ㄐㄩㄣˋ，完成之意。",deep:"1. 注音比較\n竣：ㄐㄩㄣˋ（四聲）＝竣工、完竣；ㄙㄨㄣ＝無此音；ㄑㄩㄣ＝無此音\n2. 國字拆解與造字原因\n竣：形聲字，「立」＋「夋」（聲），事情做完、停立→竣工（工程完成）。與「峻」同音ㄐㄩㄣˋ。"},
  {id:"p138",grade:8,word:"魯莽",target:"莽",zhuyin:"ㄇㄤˇ",pinyin:"mǎng",wrong:[{z:"ㄇㄤˊ",p:"máng"},{z:"ㄨㄤˇ",p:"wǎng"}],note:"「魯莽」「草莽」的「莽」讀ㄇㄤˇ。",deep:"1. 注音比較\n莽：ㄇㄤˇ（三聲）＝魯莽、草莽、莽撞；ㄇㄤˊ＝誤讀（受「忙」影響）；ㄨㄤˇ＝無此音\n2. 國字拆解與造字原因\n莽：會意字，「犬」在草叢（茻）中，本義是草深廣的樣子→草莽；行事像闖進草叢般冒失→魯莽。讀ㄇㄤˇ。"},
  {id:"p139",grade:8,word:"畏葸",target:"葸",zhuyin:"ㄒㄧˇ",pinyin:"xǐ",wrong:[{z:"ㄙ",p:"sī"},{z:"ㄕㄞ",p:"shāi"}],note:"「畏葸不前」的「葸」讀ㄒㄧˇ，畏懼的樣子。",deep:"1. 注音比較\n葸：ㄒㄧˇ（三聲）＝畏葸不前；ㄙ＝無此音（是「思」的讀音）；ㄕㄞ＝無此音\n2. 國字拆解與造字原因\n葸：形聲字，「艹」＋「思」（聲），畏懼膽怯的樣子→畏葸不前（害怕而不敢前進）。讀ㄒㄧˇ。"},
  {id:"p140",grade:8,word:"星宿",target:"宿",zhuyin:"ㄒㄧㄡˋ",pinyin:"xiù",wrong:[{z:"ㄙㄨˋ",p:"sù"},{z:"ㄒㄧㄡˇ",p:"xiǔ"}],note:"「星宿」讀ㄒㄧㄡˋ；「住宿」讀ㄙㄨˋ；「一宿」讀ㄒㄧㄡˇ。",deep:"1. 注音比較\n宿：ㄒㄧㄡˋ（四聲）＝星宿；ㄙㄨˋ（四聲）＝住宿、宿舍、宿願；ㄒㄧㄡˇ（三聲）＝一宿、整宿\n2. 國字拆解與造字原因\n宿：會意字，人在屋內蓆上過夜，本義是過夜（ㄙㄨˋ）；星辰的「住所」——星座讀ㄒㄧㄡˋ（星宿）；計算夜數讀ㄒㄧㄡˇ（住了一宿）。一字三音常考。"},
  {id:"p141",grade:9,word:"呱呱墜地",target:"呱",zhuyin:"ㄍㄨ",pinyin:"gū",wrong:[{z:"ㄍㄨㄚ",p:"guā"},{z:"ㄨㄚ",p:"wā"}],note:"「呱呱墜地」的「呱」讀ㄍㄨ，嬰兒哭聲。",deep:"1. 注音比較\n呱：ㄍㄨ（一聲）＝呱呱墜地；ㄍㄨㄚ（一聲）＝呱呱叫（鴨鳴、稱讚）；ㄨㄚ＝無此音（是「蛙」的讀音）\n2. 國字拆解與造字原因\n呱：形聲字，「口」＋「瓜」（聲），擬聲字。嬰兒的哭聲讀ㄍㄨ（呱呱墜地）；鴨叫或「頂呱呱」讀ㄍㄨㄚ。"},
  {id:"p142",grade:9,word:"暴虎馮河",target:"馮",zhuyin:"ㄆㄧㄥˊ",pinyin:"píng",wrong:[{z:"ㄈㄥˊ",p:"féng"},{z:"ㄆㄥˊ",p:"péng"}],note:"「暴虎馮河」的「馮」讀ㄆㄧㄥˊ，徒步渡河；姓氏讀ㄈㄥˊ。",deep:"1. 注音比較\n馮：ㄆㄧㄥˊ（二聲）＝暴虎馮河（徒步渡河）；ㄈㄥˊ（二聲）＝姓馮；ㄆㄥˊ＝無此音\n2. 國字拆解與造字原因\n馮：從「馬」、「冫」（聲），本義是馬行疾速。「暴虎馮河」（空手打虎、徒步渡河）的「馮」通「憑」，讀ㄆㄧㄥˊ；姓氏讀ㄈㄥˊ。"},
  {id:"p143",grade:9,word:"色厲內荏",target:"荏",zhuyin:"ㄖㄣˇ",pinyin:"rěn",wrong:[{z:"ㄖㄣˋ",p:"rèn"},{z:"ㄋㄧㄢˇ",p:"niǎn"}],note:"「色厲內荏」的「荏」讀ㄖㄣˇ，軟弱之意。",deep:"1. 注音比較\n荏：ㄖㄣˇ（三聲）＝色厲內荏、光陰荏苒；ㄖㄣˋ＝誤讀（受「任」影響）；ㄋㄧㄢˇ＝無此音\n2. 國字拆解與造字原因\n荏：形聲字，「艹」＋「任」（聲），本義是白蘇（草本植物），莖葉柔弱→軟弱（色厲內荏＝外表強硬內心軟弱）。讀ㄖㄣˇ。"},
  {id:"p144",grade:9,word:"心廣體胖",target:"胖",zhuyin:"ㄆㄢˊ",pinyin:"pán",wrong:[{z:"ㄆㄤˋ",p:"pàng"},{z:"ㄅㄢˋ",p:"bàn"}],note:"「心廣體胖」的「胖」讀ㄆㄢˊ，安舒之意。",deep:"1. 注音比較\n胖：ㄆㄢˊ（二聲）＝心廣體胖（安舒舒坦）；ㄆㄤˋ（四聲）＝肥胖、胖子；ㄅㄢˋ＝無此音\n2. 國字拆解與造字原因\n胖：形聲字，「月（肉）」＋「半」（聲），本義是祭祀用的半體牲肉。「心廣體胖」出自《大學》，指心胸寬廣則身體安舒，讀ㄆㄢˊ；肥胖義讀ㄆㄤˋ。"},
  {id:"p145",grade:9,word:"否極泰來",target:"否",zhuyin:"ㄆㄧˇ",pinyin:"pǐ",wrong:[{z:"ㄈㄡˇ",p:"fǒu"},{z:"ㄆㄧˋ",p:"pì"}],note:"「否極泰來」「臧否」的「否」讀ㄆㄧˇ；「是否」讀ㄈㄡˇ。",deep:"1. 注音比較\n否：ㄆㄧˇ（三聲）＝否極泰來、臧否人物；ㄈㄡˇ（三聲）＝是否、否認、否決；ㄆㄧˋ＝無此音（是「僻」的讀音）\n2. 國字拆解與造字原因\n否：從「口」從「不」，本義是不然（ㄈㄡˇ）。《易經》的否卦（閉塞不通的壞運）讀ㄆㄧˇ——「否極泰來」＝壞運到頭好運來；評論好壞「臧否」也讀ㄆㄧˇ。"},
  {id:"p146",grade:9,word:"一曝十寒",target:"曝",zhuyin:"ㄆㄨˋ",pinyin:"pù",wrong:[{z:"ㄅㄠˋ",p:"bào"},{z:"ㄆㄨ",p:"pū"}],note:"「一曝十寒」「曝曬」的「曝」讀ㄆㄨˋ。",deep:"1. 注音比較\n曝：ㄆㄨˋ（四聲）＝一曝十寒、曝曬、曝光；ㄅㄠˋ＝俗讀，審訂表不採；ㄆㄨ＝無此音\n2. 國字拆解與造字原因\n曝：「日」＋「暴」（聲），太陽下晒。「一曝十寒」出自《孟子》，晒一天凍十天，讀ㄆㄨˋ。"},
  {id:"p147",grade:9,word:"針砭",target:"砭",zhuyin:"ㄅㄧㄢ",pinyin:"biān",wrong:[{z:"ㄈㄚˊ",p:"fá"},{z:"ㄅㄧㄢˇ",p:"biǎn"}],note:"「針砭時弊」的「砭」讀ㄅㄧㄢ，古代石針。",deep:"1. 注音比較\n砭：ㄅㄧㄢ（一聲）＝針砭時弊、砭骨；ㄈㄚˊ＝無此音（是「乏」的讀音）；ㄅㄧㄢˇ＝誤讀（受「貶」影響）\n2. 國字拆解與造字原因\n砭：形聲字，「石」＋「乏」（聲），古代治病的石針→用言論刺醒世人（針砭時弊）。讀一聲ㄅㄧㄢ。"},
  {id:"p148",grade:9,word:"倥傯",target:"傯",zhuyin:"ㄗㄨㄥˇ",pinyin:"zǒng",wrong:[{z:"ㄘㄨㄥ",p:"cōng"},{z:"ㄓㄨㄥˇ",p:"zhǒng"}],note:"「戎馬倥傯」讀ㄎㄨㄥˇ ㄗㄨㄥˇ，匆忙迫促。",deep:"1. 注音比較\n傯：ㄗㄨㄥˇ（三聲）＝戎馬倥傯；ㄘㄨㄥ＝無此音（是「匆」的讀音）；ㄓㄨㄥˇ＝無此音\n2. 國字拆解與造字原因\n傯：形聲字，「亻」＋「總」（聲），「倥傯」（ㄎㄨㄥˇ ㄗㄨㄥˇ）是連綿詞：事務匆迫繁忙——「戎馬倥傯」形容軍務繁忙。"},
  {id:"p149",grade:9,word:"鞭笞",target:"笞",zhuyin:"ㄔ",pinyin:"chī",wrong:[{z:"ㄊㄞˊ",p:"tái"},{z:"ㄓˋ",p:"zhì"}],note:"「鞭笞」的「笞」讀ㄔ，用竹板抽打。",deep:"1. 注音比較\n笞：ㄔ（一聲）＝鞭笞、笞刑；ㄊㄞˊ＝無此音（是「臺」的讀音）；ㄓˋ＝無此音\n2. 國字拆解與造字原因\n笞：形聲字，「竹」＋「台」（聲），用竹板抽打→鞭笞、笞刑（古代五刑之一）。讀ㄔ。"},
  {id:"p150",grade:9,word:"晌午",target:"晌",zhuyin:"ㄕㄤˇ",pinyin:"shǎng",wrong:[{z:"ㄒㄧㄤˇ",p:"xiǎng"},{z:"ㄕㄤˋ",p:"shàng"}],note:"「晌午」的「晌」讀ㄕㄤˇ，正午時分。",deep:"1. 注音比較\n晌：ㄕㄤˇ（三聲）＝晌午、半晌；ㄒㄧㄤˇ＝無此音（是「響」的讀音）；ㄕㄤˋ＝無此音（是「上」的讀音）\n2. 國字拆解與造字原因\n晌：形聲字，「日」＋「向」（聲），白天的一段時間→晌午（正午）、半晌（好一會兒）。讀ㄕㄤˇ。"},
  {id:"p151",grade:9,word:"憤懣",target:"懣",zhuyin:"ㄇㄣˋ",pinyin:"mèn",wrong:[{z:"ㄇㄢˇ",p:"mǎn"},{z:"ㄇㄢˊ",p:"mán"}],note:"「憤懣」的「懣」讀ㄇㄣˋ，煩悶怨怒。",deep:"1. 注音比較\n懣：ㄇㄣˋ（四聲）＝憤懣；ㄇㄢˇ＝誤讀（受「滿」影響）；ㄇㄢˊ＝無此音（是「瞞」的讀音）\n2. 國字拆解與造字原因\n懣：形聲字，「心」＋「滿」（聲），心中脹滿煩怨→憤懣（憤怒鬱悶）。讀ㄇㄣˋ，與「悶」同音。"},
  {id:"p152",grade:9,word:"惺忪",target:"忪",zhuyin:"ㄓㄨㄥ",pinyin:"zhōng",wrong:[{z:"ㄙㄨㄥ",p:"sōng"},{z:"ㄍㄨㄥ",p:"gōng"}],note:"「睡眼惺忪」的「忪」讀ㄓㄨㄥ。",deep:"1. 注音比較\n忪：ㄓㄨㄥ（一聲）＝睡眼惺忪；ㄙㄨㄥ＝俗讀，審訂表不採；ㄍㄨㄥ＝無此音\n2. 國字拆解與造字原因\n忪：形聲字，「忄」＋「公」（聲），「惺忪」形容剛睡醒眼神迷糊。審訂音「忪」讀ㄓㄨㄥ。"},
  {id:"p153",grade:9,word:"蹣跚",target:"蹣",zhuyin:"ㄆㄢˊ",pinyin:"pán",wrong:[{z:"ㄇㄢˊ",p:"mán"},{z:"ㄅㄢˋ",p:"bàn"}],note:"「蹣跚」讀ㄆㄢˊ ㄕㄢ，步伐不穩的樣子。",deep:"1. 注音比較\n蹣：ㄆㄢˊ（二聲）＝蹣跚；ㄇㄢˊ＝誤讀（受「瞞」影響）；ㄅㄢˋ＝無此音\n2. 國字拆解與造字原因\n蹣：形聲字，「足」＋「㒼」（聲），「蹣跚」（ㄆㄢˊ ㄕㄢ）是連綿詞：走路搖晃不穩的樣子。"},
  {id:"p154",grade:9,word:"躊躇",target:"躇",zhuyin:"ㄔㄨˊ",pinyin:"chú",wrong:[{z:"ㄓㄨˊ",p:"zhú"},{z:"ㄔㄨˋ",p:"chù"}],note:"「躊躇」讀ㄔㄡˊ ㄔㄨˊ，猶豫不決。",deep:"1. 注音比較\n躇：ㄔㄨˊ（二聲）＝躊躇；ㄓㄨˊ＝無此音（是「竹」的讀音）；ㄔㄨˋ＝無此音（「躊躇滿志」亦讀ㄔㄨˊ）\n2. 國字拆解與造字原因\n躇：形聲字，「足」＋「著」（聲），「躊躇」（ㄔㄡˊ ㄔㄨˊ）是連綿詞：腳步徘徊、猶豫不前。"},
  {id:"p155",grade:9,word:"饕餮",target:"餮",zhuyin:"ㄊㄧㄝˋ",pinyin:"tiè",wrong:[{z:"ㄊㄧㄢ",p:"tiān"},{z:"ㄉㄧㄝˊ",p:"dié"}],note:"「饕餮」讀ㄊㄠ ㄊㄧㄝˋ，傳說中貪食的惡獸。",deep:"1. 注音比較\n餮：ㄊㄧㄝˋ（四聲）＝饕餮；ㄊㄧㄢ＝無此音（是「天」的讀音）；ㄉㄧㄝˊ＝無此音\n2. 國字拆解與造字原因\n餮：從「食」，「饕餮」（ㄊㄠ ㄊㄧㄝˋ）是傳說中貪吃的凶獸，商周鼎彝常鑄其紋→比喻貪吃或貪婪的人（饕客的「饕」由此來）。"},
  {id:"p156",grade:9,word:"贛江",target:"贛",zhuyin:"ㄍㄢˋ",pinyin:"gàn",wrong:[{z:"ㄓㄤˋ",p:"zhàng"},{z:"ㄍㄨㄥˋ",p:"gòng"}],note:"「贛」讀ㄍㄢˋ，江西省的簡稱。",deep:"1. 注音比較\n贛：ㄍㄢˋ（四聲）＝贛江、贛（江西簡稱）；ㄓㄤˋ＝無此音；ㄍㄨㄥˋ＝無此音（是「貢」的讀音）\n2. 國字拆解與造字原因\n贛：從「貝」，本義是賜給。江西的贛江、江西省簡稱「贛」讀ㄍㄢˋ。"},
  {id:"p157",grade:9,word:"皈依",target:"皈",zhuyin:"ㄍㄨㄟ",pinyin:"guī",wrong:[{z:"ㄈㄢˇ",p:"fǎn"},{z:"ㄅㄢ",p:"bān"}],note:"「皈依」的「皈」讀ㄍㄨㄟ，歸信宗教。",deep:"1. 注音比較\n皈：ㄍㄨㄟ（一聲）＝皈依；ㄈㄢˇ＝無此音（是「反」的讀音）；ㄅㄢ＝無此音\n2. 國字拆解與造字原因\n皈：從「白」從「反」，是「歸」的俗字分化——「皈依」即歸投依靠（信仰宗教）。與「歸」同音ㄍㄨㄟ。"},
  {id:"p158",grade:9,word:"整飭",target:"飭",zhuyin:"ㄔˋ",pinyin:"chì",wrong:[{z:"ㄕˋ",p:"shì"},{z:"ㄙˋ",p:"sì"}],note:"「整飭」的「飭」讀ㄔˋ，整頓之意，勿與「飾」混淆。",deep:"1. 注音比較\n飭：ㄔˋ（四聲）＝整飭、飭令；ㄕˋ＝無此音（是「飾」的讀音）；ㄙˋ＝無此音\n2. 國字拆解與造字原因\n飭：從「人」「力」與「食（省）」，本義是整治、使謹嚴→整飭（整頓）、申飭（告誡）。與「飾」（ㄕˋ，裝飾）形近音異，常考。"},
  {id:"p159",grade:9,word:"熨貼",target:"熨",zhuyin:"ㄩˋ",pinyin:"yù",wrong:[{z:"ㄩㄣˋ",p:"yùn"},{z:"ㄨㄟˋ",p:"wèi"}],note:"「熨貼」（妥適）讀ㄩˋ；「熨斗」讀ㄩㄣˋ。",deep:"1. 注音比較\n熨：ㄩˋ（四聲）＝熨貼（妥適舒坦）；ㄩㄣˋ（四聲）＝熨斗、熨衣服；ㄨㄟˋ＝無此音\n2. 國字拆解與造字原因\n熨：從「火」，用加熱的金屬器把衣物壓平。燙衣讀ㄩㄣˋ（熨斗）；「熨貼」（心裡舒坦、用字妥當）讀ㄩˋ。"},
  {id:"p160",grade:9,word:"氤氳",target:"氳",zhuyin:"ㄩㄣ",pinyin:"yūn",wrong:[{z:"ㄨㄣ",p:"wēn"},{z:"ㄩㄣˊ",p:"yún"}],note:"「氤氳」讀ㄧㄣ ㄩㄣ，煙氣瀰漫的樣子。",deep:"1. 注音比較\n氳：ㄩㄣ（一聲）＝氤氳；ㄨㄣ＝無此音（是「溫」的讀音）；ㄩㄣˊ＝誤讀（受「雲」影響）\n2. 國字拆解與造字原因\n氳：形聲字，「气」＋「昷」（聲），「氤氳」（ㄧㄣ ㄩㄣ）是連綿詞：煙雲瀰漫的樣子。"},
  {id:"p161",grade:9,word:"拈花惹草",target:"拈",zhuyin:"ㄋㄧㄢˊ",pinyin:"nián",wrong:[{z:"ㄓㄢ",p:"zhān"},{z:"ㄋㄧㄢˇ",p:"niǎn"}],note:"「拈」讀ㄋㄧㄢˊ，用指尖夾取。",deep:"1. 注音比較\n拈：ㄋㄧㄢˊ（二聲）＝拈花惹草、信手拈來；ㄓㄢ＝無此音（是「沾」的讀音）；ㄋㄧㄢˇ＝誤讀（受「捻」影響）\n2. 國字拆解與造字原因\n拈：形聲字，「扌」＋「占」（聲），用手指輕輕夾取→信手拈來。讀ㄋㄧㄢˊ，與「捻」（ㄋㄧㄢˇ，搓）不同。"},
  {id:"p162",grade:9,word:"根深柢固",target:"柢",zhuyin:"ㄉㄧˇ",pinyin:"dǐ",wrong:[{z:"ㄓˇ",p:"zhǐ"},{z:"ㄉㄧˋ",p:"dì"}],note:"「根深柢固」的「柢」讀ㄉㄧˇ，樹根。",deep:"1. 注音比較\n柢：ㄉㄧˇ（三聲）＝根深柢固；ㄓˇ＝無此音；ㄉㄧˋ＝誤讀（受「帝」影響）\n2. 國字拆解與造字原因\n柢：形聲字，「木」＋「氐」（聲），樹木的主根→根深柢固（根基深固）。讀ㄉㄧˇ，與「底」同音。"},
  {id:"p163",grade:9,word:"傴僂",target:"僂",zhuyin:"ㄌㄡˊ",pinyin:"lóu",wrong:[{z:"ㄌㄩˇ",p:"lǚ"},{z:"ㄌㄡˋ",p:"lòu"}],note:"「傴僂」讀ㄩˇ ㄌㄡˊ，駝背彎腰。",deep:"1. 注音比較\n僂：ㄌㄡˊ（二聲）＝傴僂（ㄩˇ ㄌㄡˊ）；ㄌㄩˇ＝「佝僂病」另讀；ㄌㄡˋ＝無此音（是「陋」的讀音）\n2. 國字拆解與造字原因\n僂：形聲字，「亻」＋「婁」（聲），背脊彎曲→傴僂（駝背）。讀ㄌㄡˊ。"},
  {id:"p164",grade:9,word:"骨鯁在喉",target:"鯁",zhuyin:"ㄍㄥˇ",pinyin:"gěng",wrong:[{z:"ㄍㄥ",p:"gēng"},{z:"ㄏㄡˊ",p:"hóu"}],note:"「骨鯁在喉」的「鯁」讀ㄍㄥˇ，魚刺卡喉。",deep:"1. 注音比較\n鯁：ㄍㄥˇ（三聲）＝骨鯁在喉、骨鯁之臣；ㄍㄥ＝誤讀；ㄏㄡˊ＝無此音（是「喉」的讀音）\n2. 國字拆解與造字原因\n鯁：形聲字，「魚」＋「更」（聲），魚骨、魚刺→骨鯁在喉（有話不吐不快）；魚骨正直不彎→正直敢言（骨鯁之臣）。讀ㄍㄥˇ。"},
  {id:"p165",grade:9,word:"僭越",target:"僭",zhuyin:"ㄐㄧㄢˋ",pinyin:"jiàn",wrong:[{z:"ㄑㄧㄢˊ",p:"qián"},{z:"ㄗㄢˋ",p:"zàn"}],note:"「僭越」的「僭」讀ㄐㄧㄢˋ，超越本分。",deep:"1. 注音比較\n僭：ㄐㄧㄢˋ（四聲）＝僭越、僭稱；ㄑㄧㄢˊ＝無此音（是「潛」的讀音）；ㄗㄢˋ＝無此音（是「贊」的讀音）\n2. 國字拆解與造字原因\n僭：形聲字，「亻」＋「朁」（聲），超越自己的身分冒用上位者的名義職權→僭越。讀ㄐㄧㄢˋ。"},
  {id:"p166",grade:10,word:"呶呶不休",target:"呶",zhuyin:"ㄋㄠˊ",pinyin:"náo",wrong:[{z:"ㄋㄨˊ",p:"nú"},{z:"ㄉㄨ",p:"dū"}],note:"「呶呶不休」的「呶」讀ㄋㄠˊ，喋喋不休。",deep:"1. 注音比較\n呶：ㄋㄠˊ（二聲）＝呶呶不休；ㄋㄨˊ＝無此音（是「奴」的讀音）；ㄉㄨ＝無此音\n2. 國字拆解與造字原因\n呶：形聲字，「口」＋「奴」（聲），喧鬧多言→呶呶不休（說個不停）。讀ㄋㄠˊ。"},
  {id:"p167",grade:10,word:"齟齬",target:"齬",zhuyin:"ㄩˇ",pinyin:"yǔ",wrong:[{z:"ㄨˇ",p:"wǔ"},{z:"ㄩˊ",p:"yú"}],note:"「齟齬」讀ㄐㄩˇ ㄩˇ，意見不合。",deep:"1. 注音比較\n齬：ㄩˇ（三聲）＝齟齬；ㄨˇ＝無此音（是「五」的讀音）；ㄩˊ＝誤讀（受「吾」影響）\n2. 國字拆解與造字原因\n齬：形聲字，「齒」＋「吾」（聲），「齟齬」（ㄐㄩˇ ㄩˇ）本指上下牙齒對不齊→意見不合、不融洽。"},
  {id:"p168",grade:10,word:"抵牾",target:"牾",zhuyin:"ㄨˇ",pinyin:"wǔ",wrong:[{z:"ㄨˊ",p:"wú"},{z:"ㄧㄡˇ",p:"yǒu"}],note:"「抵牾」的「牾」讀ㄨˇ，牴觸矛盾。",deep:"1. 注音比較\n牾：ㄨˇ（三聲）＝抵牾；ㄨˊ＝誤讀（受「吾」影響）；ㄧㄡˇ＝無此音\n2. 國字拆解與造字原因\n牾：形聲字，「牛」＋「吾」（聲），本義是逆、相牴觸→抵牾（互相矛盾）。讀ㄨˇ。"},
  {id:"p169",grade:10,word:"倨傲",target:"倨",zhuyin:"ㄐㄩˋ",pinyin:"jù",wrong:[{z:"ㄐㄩ",p:"jū"},{z:"ㄍㄨˋ",p:"gù"}],note:"「前倨後恭」的「倨」讀ㄐㄩˋ，傲慢。",deep:"1. 注音比較\n倨：ㄐㄩˋ（四聲）＝前倨後恭、倨傲；ㄐㄩ＝誤讀（受「居」影響）；ㄍㄨˋ＝無此音\n2. 國字拆解與造字原因\n倨：形聲字，「亻」＋「居」（聲），態度傲慢→倨傲；「前倨後恭」指先傲慢後恭敬。讀ㄐㄩˋ。"},
  {id:"p170",grade:10,word:"睥睨",target:"睨",zhuyin:"ㄋㄧˋ",pinyin:"nì",wrong:[{z:"ㄧˊ",p:"yí"},{z:"ㄋㄧˊ",p:"ní"}],note:"「睥睨」讀ㄅㄧˋ ㄋㄧˋ，斜眼傲視。",deep:"1. 注音比較\n睨：ㄋㄧˋ（四聲）＝睥睨、睨視；ㄧˊ＝無此音；ㄋㄧˊ＝誤讀（受「泥」影響）\n2. 國字拆解與造字原因\n睨：形聲字，「目」＋「兒」（聲），斜著眼看→睥睨（ㄅㄧˋ ㄋㄧˋ，斜眼傲視一切）。讀ㄋㄧˋ。"},
  {id:"p171",grade:10,word:"訾議",target:"訾",zhuyin:"ㄗˇ",pinyin:"zǐ",wrong:[{z:"ㄘˊ",p:"cí"},{z:"ㄗ",p:"zī"}],note:"「無可訾議」的「訾」讀ㄗˇ，詆毀批評。",deep:"1. 注音比較\n訾：ㄗˇ（三聲）＝訾議、無可訾議；ㄘˊ＝無此音（是「詞」的讀音）；ㄗ＝姓氏讀音\n2. 國字拆解與造字原因\n訾：形聲字，「言」＋「此」（聲），用言語詆毀批評→訾議（非議）。讀ㄗˇ。"},
  {id:"p172",grade:10,word:"謾罵",target:"謾",zhuyin:"ㄇㄢˋ",pinyin:"màn",wrong:[{z:"ㄇㄢˊ",p:"mán"},{z:"ㄨㄢˋ",p:"wàn"}],note:"「謾罵」的「謾」讀ㄇㄢˋ；「欺謾」讀ㄇㄢˊ。",deep:"1. 注音比較\n謾：ㄇㄢˋ（四聲）＝謾罵；ㄇㄢˊ（二聲）＝欺謾（欺騙）；ㄨㄢˋ＝無此音\n2. 國字拆解與造字原因\n謾：形聲字，「言」＋「曼」（聲）。輕慢無禮地罵讀ㄇㄢˋ（謾罵）；欺瞞義讀ㄇㄢˊ。記法：罵人ㄇㄢˋ、欺騙ㄇㄢˊ。"},
  {id:"p173",grade:10,word:"羞赧",target:"赧",zhuyin:"ㄋㄢˇ",pinyin:"nǎn",wrong:[{z:"ㄋㄢˊ",p:"nán"},{z:"ㄏㄢˇ",p:"hǎn"}],note:"「羞赧」的「赧」讀ㄋㄢˇ，因害羞而臉紅。",deep:"1. 注音比較\n赧：ㄋㄢˇ（三聲）＝羞赧、赧然；ㄋㄢˊ＝誤讀（受「難」影響）；ㄏㄢˇ＝無此音\n2. 國字拆解與造字原因\n赧：從「赤」（紅）從「𠬝」，因羞愧而臉紅→羞赧。從「赤」表意，讀ㄋㄢˇ。"},
  {id:"p174",grade:10,word:"造次",target:"造",zhuyin:"ㄗㄠˋ",pinyin:"zào",wrong:[{z:"ㄘㄠˋ",p:"cào"},{z:"ㄗㄠˇ",p:"zǎo"}],note:"「造次」讀ㄗㄠˋ ㄘˋ，魯莽輕率。",deep:"1. 注音比較\n造：ㄗㄠˋ（四聲）＝造次（魯莽）、建造；ㄘㄠˋ＝無此音；ㄗㄠˇ＝無此音（是「早」的讀音）\n2. 國字拆解與造字原因\n造：形聲字，「辶」＋「告」（聲），本義是到達→建造。「造次」（倉促、魯莽）出自《論語》「造次必於是」，讀ㄗㄠˋ ㄘˋ。"},
  {id:"p175",grade:10,word:"倏忽",target:"倏",zhuyin:"ㄕㄨˋ",pinyin:"shù",wrong:[{z:"ㄊㄧㄠˊ",p:"tiáo"},{z:"ㄕㄨ",p:"shū"}],note:"「倏忽」的「倏」讀ㄕㄨˋ，極快地。",deep:"1. 注音比較\n倏：ㄕㄨˋ（四聲）＝倏忽、倏地；ㄊㄧㄠˊ＝無此音（是「條」的讀音）；ㄕㄨ＝誤讀\n2. 國字拆解與造字原因\n倏：從「犬」，本義是狗快速奔跑→迅速（倏忽＝一眨眼）。讀ㄕㄨˋ，與「條」形近，注意分辨。"},
  {id:"p176",grade:10,word:"間不容髮",target:"間",zhuyin:"ㄐㄧㄢˋ",pinyin:"jiàn",wrong:[{z:"ㄐㄧㄢ",p:"jiān"},{z:"ㄒㄧㄢˊ",p:"xián"}],note:"「間不容髮」的「間」讀ㄐㄧㄢˋ，空隙之意。",deep:"1. 注音比較\n間：ㄐㄧㄢˋ（四聲）＝間不容髮、間隔、離間；ㄐㄧㄢ（一聲）＝中間、時間；ㄒㄧㄢˊ＝無此音（「閒」的讀音）\n2. 國字拆解與造字原因\n間：門縫中見月光，本義是縫隙。「間不容髮」＝縫隙容不下一根頭髮（危急），「間」取縫隙義讀ㄐㄧㄢˋ。"},
  {id:"p177",grade:10,word:"愀然",target:"愀",zhuyin:"ㄑㄧㄠˇ",pinyin:"qiǎo",wrong:[{z:"ㄐㄧㄡ",p:"jiū"},{z:"ㄑㄧㄡ",p:"qiū"}],note:"「愀然變色」的「愀」讀ㄑㄧㄠˇ，神色驟變。",deep:"1. 注音比較\n愀：ㄑㄧㄠˇ（三聲）＝愀然變色；ㄐㄧㄡ＝無此音；ㄑㄧㄡ＝無此音（是「秋」的讀音）\n2. 國字拆解與造字原因\n愀：形聲字，「忄」＋「秋」（聲），神色驟然轉為嚴肅憂戚→愀然。讀ㄑㄧㄠˇ。"},
  {id:"p178",grade:10,word:"稗官野史",target:"稗",zhuyin:"ㄅㄞˋ",pinyin:"bài",wrong:[{z:"ㄅㄟ",p:"bēi"},{z:"ㄆㄞˊ",p:"pái"}],note:"「稗官野史」的「稗」讀ㄅㄞˋ。",deep:"1. 注音比較\n稗：ㄅㄞˋ（四聲）＝稗官野史、稗子；ㄅㄟ＝誤讀（受「卑」影響）；ㄆㄞˊ＝無此音\n2. 國字拆解與造字原因\n稗：形聲字，「禾」＋「卑」（聲），田裡像稻的雜草——卑微的禾→瑣碎非正統（稗官野史＝民間瑣聞）。讀ㄅㄞˋ。"},
  {id:"p179",grade:10,word:"畚箕",target:"畚",zhuyin:"ㄅㄣˇ",pinyin:"běn",wrong:[{z:"ㄈㄣˋ",p:"fèn"},{z:"ㄅㄣˋ",p:"bèn"}],note:"「畚箕」讀ㄅㄣˇ ㄐㄧ。",deep:"1. 注音比較\n畚：ㄅㄣˇ（三聲）＝畚箕；ㄈㄣˋ＝無此音（是「糞」的讀音）；ㄅㄣˋ＝無此音（是「笨」的讀音）\n2. 國字拆解與造字原因\n畚：從「田」，盛土石垃圾的器具→畚箕（ㄅㄣˇ ㄐㄧ）。讀ㄅㄣˇ，與「本」同音。"},
  {id:"p180",grade:10,word:"蒞臨",target:"蒞",zhuyin:"ㄌㄧˋ",pinyin:"lì",wrong:[{z:"ㄨㄟˋ",p:"wèi"},{z:"ㄌㄨㄟˋ",p:"luì"}],note:"「蒞臨」的「蒞」讀ㄌㄧˋ，到來之意。",deep:"1. 注音比較\n蒞：ㄌㄧˋ（四聲）＝蒞臨、蒞會；ㄨㄟˋ＝無此音（是「位」的讀音）；ㄌㄨㄟˋ＝無此音\n2. 國字拆解與造字原因\n蒞：形聲字，「艹」＋「涖（省）」，親自到來→蒞臨指導。讀ㄌㄧˋ，與「立」同音。"},
  {id:"p181",grade:10,word:"骨骸",target:"骸",zhuyin:"ㄏㄞˊ",pinyin:"hái",wrong:[{z:"ㄍㄞ",p:"gāi"},{z:"ㄏㄜˊ",p:"hé"}],note:"「骸骨」「遺骸」的「骸」讀ㄏㄞˊ。",deep:"1. 注音比較\n骸：ㄏㄞˊ（二聲）＝骸骨、遺骸、殘骸；ㄍㄞ＝無此音（是「該」的讀音）；ㄏㄜˊ＝無此音\n2. 國字拆解與造字原因\n骸：形聲字，「骨」＋「亥」（聲），本義是脛骨，泛指骨骸→遺骸、殘骸。讀ㄏㄞˊ，與「孩」同音。"},
  {id:"p182",grade:10,word:"踉蹌",target:"蹌",zhuyin:"ㄑㄧㄤˋ",pinyin:"qiàng",wrong:[{z:"ㄑㄧㄤ",p:"qiāng"},{z:"ㄘㄤ",p:"cāng"}],note:"「踉蹌」讀ㄌㄧㄤˋ ㄑㄧㄤˋ，走路不穩。",deep:"1. 注音比較\n蹌：ㄑㄧㄤˋ（四聲）＝踉蹌；ㄑㄧㄤ＝誤讀；ㄘㄤ＝無此音（是「倉」的讀音）\n2. 國字拆解與造字原因\n蹌：形聲字，「足」＋「倉」（聲），「踉蹌」（ㄌㄧㄤˋ ㄑㄧㄤˋ）形容腳步歪斜不穩。"},
  {id:"p183",grade:10,word:"糾葛",target:"葛",zhuyin:"ㄍㄜˊ",pinyin:"gé",wrong:[{z:"ㄍㄜˇ",p:"gě"},{z:"ㄏㄜˊ",p:"hé"}],note:"「糾葛」「瓜葛」的「葛」讀ㄍㄜˊ；姓氏讀ㄍㄜˇ。",deep:"1. 注音比較\n葛：ㄍㄜˊ（二聲）＝糾葛、瓜葛、葛藤；ㄍㄜˇ（三聲）＝姓氏（諸葛）；ㄏㄜˊ＝無此音\n2. 國字拆解與造字原因\n葛：形聲字，「艹」＋「曷」（聲），藤本植物，莖皮可織布——藤蔓纏繞→糾葛、瓜葛（牽連）。植物與牽連義讀ㄍㄜˊ；姓氏讀ㄍㄜˇ。"},
  {id:"p184",grade:10,word:"蓊鬱",target:"蓊",zhuyin:"ㄨㄥˇ",pinyin:"wěng",wrong:[{z:"ㄨㄥ",p:"wēng"},{z:"ㄇㄥˊ",p:"méng"}],note:"「蓊鬱」的「蓊」讀ㄨㄥˇ，草木茂盛。",deep:"1. 注音比較\n蓊：ㄨㄥˇ（三聲）＝蓊鬱、蓊蓊鬱鬱；ㄨㄥ＝誤讀；ㄇㄥˊ＝無此音\n2. 國字拆解與造字原因\n蓊：形聲字，「艹」＋「翁」（聲），草木茂盛的樣子→蓊鬱。讀ㄨㄥˇ。"},
  {id:"p185",grade:10,word:"倭寇",target:"倭",zhuyin:"ㄨㄛ",pinyin:"wō",wrong:[{z:"ㄨㄟ",p:"wēi"},{z:"ㄨㄛˇ",p:"wǒ"}],note:"「倭寇」的「倭」讀ㄨㄛ。",deep:"1. 注音比較\n倭：ㄨㄛ（一聲）＝倭寇；ㄨㄟ＝古音（倭遲）；ㄨㄛˇ＝誤讀\n2. 國字拆解與造字原因\n倭：形聲字，「亻」＋「委」（聲），古代對日本的稱呼→倭寇（明代侵擾沿海的日本海盜）。讀ㄨㄛ。"},
  {id:"p186",grade:11,word:"莞爾而笑",target:"爾",zhuyin:"ㄦˇ",pinyin:"ěr",wrong:[{z:"ㄦˊ",p:"ér"},{z:"ㄋㄧˇ",p:"nǐ"}],note:"「莞爾」讀ㄨㄢˇ ㄦˇ，微笑的樣子。",deep:"1. 注音比較\n爾：ㄦˇ（三聲）＝莞爾、偶爾、爾後；ㄦˊ＝無此音（是「而」的讀音）；ㄋㄧˇ＝無此音（是「你」的讀音）\n2. 國字拆解與造字原因\n爾：象形字，本義是織布的筘，假借為「你、那、如此」→「莞爾」（ㄨㄢˇ ㄦˇ）是微笑的樣子（《論語》「夫子莞爾而笑」）。"},
  {id:"p187",grade:11,word:"蜷曲",target:"蜷",zhuyin:"ㄑㄩㄢˊ",pinyin:"quán",wrong:[{z:"ㄐㄩㄢˇ",p:"juǎn"},{z:"ㄑㄩㄢ",p:"quān"}],note:"「蜷曲」「蜷伏」的「蜷」讀ㄑㄩㄢˊ。",deep:"1. 注音比較\n蜷：ㄑㄩㄢˊ（二聲）＝蜷曲、蜷伏、蜷縮；ㄐㄩㄢˇ＝無此音（是「捲」的讀音）；ㄑㄩㄢ＝誤讀\n2. 國字拆解與造字原因\n蜷：形聲字，「虫」＋「卷」（聲），蟲類身體彎曲成團→蜷曲、蜷縮。讀ㄑㄩㄢˊ，與「拳」同音（縮成一拳）。"},
  {id:"p188",grade:11,word:"殷紅",target:"殷",zhuyin:"ㄧㄢ",pinyin:"yān",wrong:[{z:"ㄧㄣ",p:"yīn"},{z:"ㄧㄢˇ",p:"yǎn"}],note:"「殷紅」（深紅色）讀ㄧㄢ；「殷勤」「殷商」讀ㄧㄣ。",deep:"1. 注音比較\n殷：ㄧㄢ（一聲）＝殷紅（深紅帶黑）；ㄧㄣ（一聲）＝殷勤、殷實、殷商；ㄧㄢˇ＝無此音\n2. 國字拆解與造字原因\n殷：本義是盛大（ㄧㄣ）；形容深紅色時讀ㄧㄢ（殷紅的血跡）。記法：顏色讀ㄧㄢ，其餘讀ㄧㄣ。"},
  {id:"p189",grade:11,word:"戲謔",target:"謔",zhuyin:"ㄋㄩㄝˋ",pinyin:"nüè",wrong:[{z:"ㄒㄩㄝˋ",p:"xuè"},{z:"ㄩㄝˋ",p:"yuè"}],note:"「戲謔」的「謔」讀ㄋㄩㄝˋ，開玩笑。",deep:"1. 注音比較\n謔：ㄋㄩㄝˋ（四聲）＝戲謔、謔而不虐（審訂音）；ㄒㄩㄝˋ＝俗讀，審訂表不採；ㄩㄝˋ＝無此音\n2. 國字拆解與造字原因\n謔：形聲字，「言」＋「虐」（聲），用言語開玩笑→戲謔。審訂音讀ㄋㄩㄝˋ。"},
  {id:"p190",grade:11,word:"炮製",target:"炮",zhuyin:"ㄆㄠˊ",pinyin:"páo",wrong:[{z:"ㄆㄠˋ",p:"pào"},{z:"ㄅㄠ",p:"bāo"}],note:"「如法炮製」的「炮」讀ㄆㄠˊ；「炮火」讀ㄆㄠˋ。",deep:"1. 注音比較\n炮：ㄆㄠˊ（二聲）＝如法炮製、炮製（中藥加工）；ㄆㄠˋ（四聲）＝炮火、大炮；ㄅㄠ（一聲）＝炮羊肉（快炒）\n2. 國字拆解與造字原因\n炮：形聲字，「火」＋「包」（聲），本義是裹物而燒。中藥的火製加工讀ㄆㄠˊ（炮製）→「如法炮製」＝照同樣方法辦理；武器讀ㄆㄠˋ。"},
  {id:"p191",grade:11,word:"揣度",target:"度",zhuyin:"ㄉㄨㄛˋ",pinyin:"duò",wrong:[{z:"ㄉㄨˋ",p:"dù"},{z:"ㄊㄨㄛˊ",p:"tuó"}],note:"「揣度」「忖度」（推測）讀ㄉㄨㄛˋ；「程度」讀ㄉㄨˋ。",deep:"1. 注音比較\n度：ㄉㄨㄛˋ（四聲）＝揣度、忖度、審時度勢（推測）；ㄉㄨˋ（四聲）＝程度、制度、度過；ㄊㄨㄛˊ＝無此音\n2. 國字拆解與造字原因\n度：本義是計量長短的標準（ㄉㄨˋ）；用心推算估量（動詞）讀ㄉㄨㄛˋ（揣度、以己度人）。記法：名詞ㄉㄨˋ、猜測ㄉㄨㄛˋ。"},
  {id:"p192",grade:11,word:"創傷",target:"創",zhuyin:"ㄔㄨㄤ",pinyin:"chuāng",wrong:[{z:"ㄔㄨㄤˋ",p:"chuàng"},{z:"ㄘㄤ",p:"cāng"}],note:"「創傷」「創口」讀ㄔㄨㄤ；「創造」「創立」讀ㄔㄨㄤˋ。",deep:"1. 注音比較\n創：ㄔㄨㄤ（一聲）＝創傷、創口、重創；ㄔㄨㄤˋ（四聲）＝創造、創立、開創；ㄘㄤ＝無此音\n2. 國字拆解與造字原因\n創：從「刀」，本義是刀傷→傷口（創傷）讀ㄔㄨㄤ；開始做、首創讀ㄔㄨㄤˋ。記法：傷口一聲、開創四聲。"},
  {id:"p193",grade:11,word:"間諜",target:"諜",zhuyin:"ㄉㄧㄝˊ",pinyin:"dié",wrong:[{z:"ㄧㄝˋ",p:"yè"},{z:"ㄊㄧㄝˇ",p:"tiě"}],note:"「間諜」的「諜」讀ㄉㄧㄝˊ。",deep:"1. 注音比較\n諜：ㄉㄧㄝˊ（二聲）＝間諜、諜報；ㄧㄝˋ＝無此音；ㄊㄧㄝˇ＝無此音\n2. 國字拆解與造字原因\n諜：形聲字，「言」＋「枼」（聲），刺探消息回報→間諜、諜報。讀ㄉㄧㄝˊ，與「蝶」同音。"},
  {id:"p194",grade:11,word:"魑魅魍魎",target:"魑",zhuyin:"ㄔ",pinyin:"chī",wrong:[{z:"ㄌㄧˊ",p:"lí"},{z:"ㄨㄤˇ",p:"wǎng"}],note:"「魑魅魍魎」讀ㄔ ㄇㄟˋ ㄨㄤˇ ㄌㄧㄤˇ，泛指鬼怪。",deep:"1. 注音比較\n魑：ㄔ（一聲）＝魑魅魍魎；ㄌㄧˊ＝誤讀（受「離」影響）；ㄨㄤˇ＝無此音（是「魍」的讀音）\n2. 國字拆解與造字原因\n魑：從「鬼」，「魑魅魍魎」（ㄔ ㄇㄟˋ ㄨㄤˇ ㄌㄧㄤˇ）是山林精怪的總稱→泛指各種壞人（如：掃蕩魑魅魍魎）。"},
  {id:"p195",grade:11,word:"耄耋",target:"耋",zhuyin:"ㄉㄧㄝˊ",pinyin:"dié",wrong:[{z:"ㄓˋ",p:"zhì"},{z:"ㄌㄠˋ",p:"lào"}],note:"「耄耋」讀ㄇㄠˋ ㄉㄧㄝˊ，指八九十歲高齡。",deep:"1. 注音比較\n耋：ㄉㄧㄝˊ（二聲）＝耄耋之年；ㄓˋ＝無此音；ㄌㄠˋ＝無此音\n2. 國字拆解與造字原因\n耋：從「老（省）」、「至」（聲），七八十歲的高齡——「耄耋」（ㄇㄠˋ ㄉㄧㄝˊ）指八九十歲長者。"},
  {id:"p196",grade:11,word:"鱖魚",target:"鱖",zhuyin:"ㄍㄨㄟˋ",pinyin:"guì",wrong:[{z:"ㄐㄩㄝˊ",p:"jué"},{z:"ㄎㄨㄟˋ",p:"kuì"}],note:"「桃花流水鱖魚肥」的「鱖」讀ㄍㄨㄟˋ。",deep:"1. 注音比較\n鱖：ㄍㄨㄟˋ（四聲）＝鱖魚；ㄐㄩㄝˊ＝誤讀；ㄎㄨㄟˋ＝無此音\n2. 國字拆解與造字原因\n鱖：形聲字，「魚」＋「厥」（聲），淡水食用魚。張志和〈漁歌子〉「桃花流水鱖魚肥」的「鱖」讀ㄍㄨㄟˋ，與「桂」同音。"},
  {id:"p197",grade:11,word:"參乘",target:"乘",zhuyin:"ㄕㄥˋ",pinyin:"shèng",wrong:[{z:"ㄔㄥˊ",p:"chéng"},{z:"ㄕㄥ",p:"shēng"}],note:"古文「參乘」「萬乘之國」的「乘」讀ㄕㄥˋ；「乘車」讀ㄔㄥˊ。",deep:"1. 注音比較\n乘：ㄕㄥˋ（四聲）＝參乘、萬乘之國、史乘；ㄔㄥˊ（二聲）＝乘車、乘機；ㄕㄥ＝無此音\n2. 國字拆解與造字原因\n乘：人登木之形。文言的兵車單位（一車四馬為一乘）、陪乘者（參乘）、史書（史乘）讀ㄕㄥˋ；動詞搭乘讀ㄔㄥˊ。"},
  {id:"p198",grade:11,word:"臧否人物",target:"否",zhuyin:"ㄆㄧˇ",pinyin:"pǐ",wrong:[{z:"ㄈㄡˇ",p:"fǒu"},{z:"ㄅㄧˇ",p:"bǐ"}],note:"「臧否」讀ㄗㄤ ㄆㄧˇ，褒貶評論。",deep:"1. 注音比較\n否：ㄆㄧˇ（三聲）＝臧否人物、否極泰來；ㄈㄡˇ（三聲）＝是否、否定；ㄅㄧˇ＝無此音（是「鄙」的讀音）\n2. 國字拆解與造字原因\n否：從「不」從「口」。「臧否」（ㄗㄤ ㄆㄧˇ）＝褒貶善惡（〈出師表〉「陟罰臧否」），「否」取「惡、壞」義讀ㄆㄧˇ。"},
  {id:"p199",grade:11,word:"暴戾",target:"戾",zhuyin:"ㄌㄧˋ",pinyin:"lì",wrong:[{z:"ㄏㄨˋ",p:"hù"},{z:"ㄌㄟˋ",p:"lèi"}],note:"「暴戾」的「戾」讀ㄌㄧˋ，凶暴乖張。",deep:"1. 注音比較\n戾：ㄌㄧˋ（四聲）＝暴戾、乖戾、罪戾；ㄏㄨˋ＝無此音（是「戶」的讀音）；ㄌㄟˋ＝無此音（是「淚」的讀音）\n2. 國字拆解與造字原因\n戾：會意字，「戶」＋「犬」，狗從門下擠出，身體彎曲，本義是彎曲→乖張兇暴（暴戾之氣）。讀ㄌㄧˋ。"},
  {id:"p200",grade:11,word:"鞭撻",target:"撻",zhuyin:"ㄊㄚˋ",pinyin:"tà",wrong:[{z:"ㄉㄚˊ",p:"dá"},{z:"ㄊㄚ",p:"tā"}],note:"「鞭撻」的「撻」讀ㄊㄚˋ。",deep:"1. 注音比較\n撻：ㄊㄚˋ（四聲）＝鞭撻、撻伐；ㄉㄚˊ＝無此音（是「達」的讀音）；ㄊㄚ＝無此音（是「他」的讀音）\n2. 國字拆解與造字原因\n撻：形聲字，「扌」＋「達」（聲），用鞭棍抽打→鞭撻；出兵征討（大張撻伐）。讀ㄊㄚˋ。"},
  // ---- 高中 10-12 進階（p201-p300 後段）----
  {id:"p201",grade:10,word:"覬覦",target:"覦",zhuyin:"ㄩˊ",pinyin:"yú",wrong:[{z:"ㄩˋ",p:"yù"},{z:"ㄧˊ",p:"yí"}],note:"「覬覦」讀ㄐㄧˋ ㄩˊ，非分的希望或企圖。",deep:"1. 注音比較\n覦：ㄩˊ（二聲）＝覬覦；ㄩˋ＝誤讀；ㄧˊ＝無此音\n2. 國字拆解與造字原因\n覦：形聲字，「見」＋「俞」（聲），「覬覦」（ㄐㄧˋ ㄩˊ）＝非分的企圖，眼睛盯著不該得的東西。"},
  {id:"p202",grade:10,word:"褪色",target:"褪",zhuyin:"ㄊㄨㄣˋ",pinyin:"tùn",wrong:[{z:"ㄊㄨㄟˋ",p:"tuì"},{z:"ㄊㄨㄣˊ",p:"tún"}],note:"審訂音「褪色」的「褪」讀ㄊㄨㄣˋ。",deep:"1. 注音比較\n褪：ㄊㄨㄣˋ（四聲）＝褪色、褪去（審訂音）；ㄊㄨㄟˋ＝俗讀，審訂表不採；ㄊㄨㄣˊ＝無此音\n2. 國字拆解與造字原因\n褪：形聲字，「衤」＋「退」（聲），衣物顏色消退、脫下→褪色、褪去。審訂音讀ㄊㄨㄣˋ。"},
  {id:"p203",grade:10,word:"癱瘓",target:"瘓",zhuyin:"ㄏㄨㄢˋ",pinyin:"huàn",wrong:[{z:"ㄏㄨㄢ",p:"huān"},{z:"ㄨㄢˋ",p:"wàn"}],note:"「癱瘓」讀ㄊㄢ ㄏㄨㄢˋ。",deep:"1. 注音比較\n瘓：ㄏㄨㄢˋ（四聲）＝癱瘓；ㄏㄨㄢ＝無此音；ㄨㄢˋ＝無此音\n2. 國字拆解與造字原因\n瘓：形聲字，「疒」＋「奐」（聲），「癱瘓」（ㄊㄢ ㄏㄨㄢˋ）＝肢體失去運動能力；引申為機能停擺（交通癱瘓）。"},
  {id:"p204",grade:10,word:"叱吒風雲",target:"吒",zhuyin:"ㄓㄚˋ",pinyin:"zhà",wrong:[{z:"ㄔㄚˋ",p:"chà"},{z:"ㄊㄨㄛ",p:"tuō"}],note:"「叱吒風雲」讀ㄔˋ ㄓㄚˋ，怒喝聲威震風雲。",deep:"1. 注音比較\n吒：ㄓㄚˋ（四聲）＝叱吒風雲；ㄔㄚˋ＝誤讀；ㄊㄨㄛ＝無此音\n2. 國字拆解與造字原因\n吒：形聲字，「口」＋「乇」（聲），怒喝聲——「叱吒風雲」（ㄔˋ ㄓㄚˋ）形容聲威極大。讀ㄓㄚˋ。"},
  {id:"p205",grade:10,word:"舐犢情深",target:"舐",zhuyin:"ㄕˋ",pinyin:"shì",wrong:[{z:"ㄉㄧˇ",p:"dǐ"},{z:"ㄊㄧㄢˇ",p:"tiǎn"}],note:"「舐犢情深」的「舐」讀ㄕˋ，舔的意思。",deep:"1. 注音比較\n舐：ㄕˋ（四聲）＝舐犢情深、老牛舐犢；ㄉㄧˇ＝無此音；ㄊㄧㄢˇ＝無此音（是「舔」的讀音）\n2. 國字拆解與造字原因\n舐：從「舌」，用舌頭舔→老牛舐犢（母牛舔小牛），比喻父母疼愛子女。讀ㄕˋ。"},
  {id:"p206",grade:10,word:"復辟",target:"辟",zhuyin:"ㄅㄧˋ",pinyin:"bì",wrong:[{z:"ㄆㄧˋ",p:"pì"},{z:"ㄅㄟˋ",p:"bèi"}],note:"「復辟」的「辟」讀ㄅㄧˋ，君主之位；「開闢」的「闢」讀ㄆㄧˋ。",deep:"1. 注音比較\n辟：ㄅㄧˋ（四聲）＝復辟、辟邪（君位、驅除）；ㄆㄧˋ（四聲）＝辟謠（通「闢」）、辟穀；ㄅㄟˋ＝無此音\n2. 國字拆解與造字原因\n辟：會意字，從「卩」（人）從「辛」（刑具），本義是法度、君主→復辟（恢復君位）讀ㄅㄧˋ；通「闢」（開）讀ㄆㄧˋ。"},
  {id:"p207",grade:10,word:"駭人聽聞",target:"駭",zhuyin:"ㄏㄞˋ",pinyin:"hài",wrong:[{z:"ㄍㄞ",p:"gāi"},{z:"ㄏㄞˊ",p:"hái"}],note:"「駭人聽聞」的「駭」讀ㄏㄞˋ，驚嚇。",deep:"1. 注音比較\n駭：ㄏㄞˋ（四聲）＝駭人聽聞、驚駭；ㄍㄞ＝無此音；ㄏㄞˊ＝無此音（是「骸」的讀音）\n2. 國字拆解與造字原因\n駭：形聲字，「馬」＋「亥」（聲），本義是馬受驚→驚嚇（驚駭、駭人聽聞）。讀ㄏㄞˋ。"},
  {id:"p208",grade:10,word:"蒙蔽",target:"蒙",zhuyin:"ㄇㄥˊ",pinyin:"méng",wrong:[{z:"ㄇㄥˇ",p:"měng"},{z:"ㄇㄥˋ",p:"mèng"}],note:"「蒙蔽」「啟蒙」讀ㄇㄥˊ；「蒙古」讀ㄇㄥˇ。",deep:"1. 注音比較\n蒙：ㄇㄥˊ（二聲）＝蒙蔽、啟蒙、承蒙；ㄇㄥˇ（三聲）＝蒙古；ㄇㄥˋ＝無此音（是「夢」的讀音）\n2. 國字拆解與造字原因\n蒙：形聲字，「艹」＋「冡」（聲），本義是遮覆→蒙蔽（被遮住）、啟蒙（揭開蒙昧）。一般讀ㄇㄥˊ；「蒙古」讀ㄇㄥˇ。"},
  {id:"p209",grade:10,word:"荷槍實彈",target:"荷",zhuyin:"ㄏㄜˋ",pinyin:"hè",wrong:[{z:"ㄏㄜˊ",p:"hé"},{z:"ㄎㄜ",p:"kē"}],note:"「荷槍」「負荷」的「荷」讀ㄏㄜˋ；「荷花」讀ㄏㄜˊ。",deep:"1. 注音比較\n荷：ㄏㄜˋ（四聲）＝荷槍實彈、負荷、荷重；ㄏㄜˊ（二聲）＝荷花、荷葉；ㄎㄜ＝無此音\n2. 國字拆解與造字原因\n荷：形聲字，「艹」＋「何」（聲），本義是蓮（ㄏㄜˊ）；「何」的本義是人扛物，故「扛、承擔」義讀ㄏㄜˋ（負荷、荷槍）。記法：植物二聲、扛擔四聲。"},
  {id:"p210",grade:10,word:"泥淖",target:"淖",zhuyin:"ㄋㄠˋ",pinyin:"nào",wrong:[{z:"ㄓㄠˇ",p:"zhǎo"},{z:"ㄔㄨㄛˋ",p:"chuò"}],note:"「泥淖」的「淖」讀ㄋㄠˋ，爛泥。",deep:"1. 注音比較\n淖：ㄋㄠˋ（四聲）＝泥淖；ㄓㄠˇ＝無此音（是「沼」的讀音）；ㄔㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n淖：形聲字，「氵」＋「卓」（聲），爛泥→泥淖（陷入泥淖＝陷入困境）。讀ㄋㄠˋ，與「鬧」同音。"},
  {id:"p211",grade:10,word:"霎時",target:"霎",zhuyin:"ㄕㄚˋ",pinyin:"shà",wrong:[{z:"ㄕㄚ",p:"shā"},{z:"ㄒㄧㄚˋ",p:"xià"}],note:"「霎時」的「霎」讀ㄕㄚˋ，極短的時間。",deep:"1. 注音比較\n霎：ㄕㄚˋ（四聲）＝霎時、一霎；ㄕㄚ＝誤讀；ㄒㄧㄚˋ＝無此音\n2. 國字拆解與造字原因\n霎：形聲字，「雨」＋「妾」（聲），本義是小雨——雨點一瞬即逝→極短時間（霎時）。讀ㄕㄚˋ。"},
  {id:"p212",grade:10,word:"歃血為盟",target:"歃",zhuyin:"ㄕㄚˋ",pinyin:"shà",wrong:[{z:"ㄔㄚ",p:"chā"},{z:"ㄒㄧㄚˊ",p:"xiá"}],note:"「歃血為盟」的「歃」讀ㄕㄚˋ，以口微吸。",deep:"1. 注音比較\n歃：ㄕㄚˋ（四聲）＝歃血為盟；ㄔㄚ＝無此音（是「插」的讀音）；ㄒㄧㄚˊ＝無此音\n2. 國字拆解與造字原因\n歃：從「欠」（張口），用口微吸→歃血為盟（古代盟誓時口含牲血表誠信）。讀ㄕㄚˋ。"},
  {id:"p213",grade:10,word:"鎩羽而歸",target:"鎩",zhuyin:"ㄕㄚ",pinyin:"shā",wrong:[{z:"ㄕㄚˋ",p:"shà"},{z:"ㄕㄨㄞ",p:"shuāi"}],note:"「鎩羽而歸」的「鎩」讀ㄕㄚ，羽毛摧落，比喻失敗。",deep:"1. 注音比較\n鎩：ㄕㄚ（一聲）＝鎩羽而歸；ㄕㄚˋ＝誤讀；ㄕㄨㄞ＝無此音（是「摔」的讀音）\n2. 國字拆解與造字原因\n鎩：形聲字，「金」＋「殺」（聲），本義是長矛，引申為摧殘——鳥羽被摧落→鎩羽而歸（失敗而回）。讀ㄕㄚ。"},
  {id:"p214",grade:10,word:"贏得青睞",target:"睞",zhuyin:"ㄌㄞˋ",pinyin:"lài",wrong:[{z:"ㄌㄞˊ",p:"lái"},{z:"ㄌㄢˊ",p:"lán"}],note:"「青睞」的「睞」讀ㄌㄞˋ，顧盼。",deep:"1. 注音比較\n睞：ㄌㄞˋ（四聲）＝青睞、明眸善睞；ㄌㄞˊ＝誤讀（受「來」影響）；ㄌㄢˊ＝無此音\n2. 國字拆解與造字原因\n睞：形聲字，「目」＋「來」（聲），本義是瞳孔不正，引申為顧盼——「青睞」（青眼相看）＝賞識。讀ㄌㄞˋ。"},
  {id:"p215",grade:10,word:"揠苗助長",target:"揠",zhuyin:"ㄧㄚˋ",pinyin:"yà",wrong:[{z:"ㄧㄢˋ",p:"yàn"},{z:"ㄧㄝˋ",p:"yè"}],note:"「揠苗助長」的「揠」讀ㄧㄚˋ，拔起。",deep:"1. 注音比較\n揠：ㄧㄚˋ（四聲）＝揠苗助長；ㄧㄢˋ＝誤讀；ㄧㄝˋ＝無此音\n2. 國字拆解與造字原因\n揠：形聲字，「扌」＋「匽」（聲），拔起→揠苗助長（把苗拔高）。讀ㄧㄚˋ，與「亞」的俗讀同音。"},
  {id:"p216",grade:11,word:"拾級而上",target:"拾",zhuyin:"ㄕㄜˋ",pinyin:"shè",wrong:[{z:"ㄕˊ",p:"shí"},{z:"ㄕㄜˇ",p:"shě"}],note:"「拾級而上」的「拾」讀ㄕㄜˋ，逐階登上；「拾起」讀ㄕˊ。",deep:"1. 注音比較\n拾：ㄕㄜˋ（四聲）＝拾級而上（逐階登上）；ㄕˊ（二聲）＝拾起、拾金不昧、收拾；ㄕㄜˇ＝無此音\n2. 國字拆解與造字原因\n拾：形聲字，「扌」＋「合」（聲），本義是撿取（ㄕˊ）；「拾級」（一階一階踏上）是特殊文言讀音ㄕㄜˋ。"},
  {id:"p217",grade:11,word:"身陷囹圄",target:"圄",zhuyin:"ㄩˇ",pinyin:"yǔ",wrong:[{z:"ㄨˊ",p:"wú"},{z:"ㄩˊ",p:"yú"}],note:"「囹圄」讀ㄌㄧㄥˊ ㄩˇ，監獄。",deep:"1. 注音比較\n圄：ㄩˇ（三聲）＝身陷囹圄；ㄨˊ＝無此音（是「吾」的讀音）；ㄩˊ＝誤讀\n2. 國字拆解與造字原因\n圄：「囗」（圍）＋「吾」（聲），「囹圄」（ㄌㄧㄥˊ ㄩˇ）是監獄——「囗」正像四面圍牆。"},
  {id:"p218",grade:11,word:"囫圇吞棗",target:"圇",zhuyin:"ㄌㄨㄣˊ",pinyin:"lún",wrong:[{z:"ㄌㄨㄣˋ",p:"lùn"},{z:"ㄏㄨㄣˊ",p:"hún"}],note:"「囫圇吞棗」讀ㄏㄨˊ ㄌㄨㄣˊ，不加咀嚼地吞下。",deep:"1. 注音比較\n圇：ㄌㄨㄣˊ（二聲）＝囫圇吞棗；ㄌㄨㄣˋ＝無此音（是「論」的讀音）；ㄏㄨㄣˊ＝無此音\n2. 國字拆解與造字原因\n圇：「囗」＋「侖」（聲），「囫圇」（ㄏㄨˊ ㄌㄨㄣˊ）＝完整未破——囫圇吞棗即整顆吞下不咀嚼，比喻學習不求甚解。"},
  {id:"p219",grade:11,word:"呷茶",target:"呷",zhuyin:"ㄒㄧㄚˊ",pinyin:"xiá",wrong:[{z:"ㄐㄧㄚ",p:"jiā"},{z:"ㄍㄚ",p:"gā"}],note:"「呷茶」的「呷」讀ㄒㄧㄚˊ，小口喝。",deep:"1. 注音比較\n呷：ㄒㄧㄚˊ（二聲）＝呷茶、呷一口；ㄐㄧㄚ＝無此音；ㄍㄚ＝無此音\n2. 國字拆解與造字原因\n呷：形聲字，「口」＋「甲」（聲），小口喝→呷茶。讀ㄒㄧㄚˊ（閩南語「呷飯」的呷是借字）。"},
  {id:"p220",grade:11,word:"髀肉復生",target:"髀",zhuyin:"ㄅㄧˋ",pinyin:"bì",wrong:[{z:"ㄆㄧˊ",p:"pí"},{z:"ㄅㄟ",p:"bēi"}],note:"「髀肉復生」的「髀」讀ㄅㄧˋ，大腿。",deep:"1. 注音比較\n髀：ㄅㄧˋ（四聲）＝髀肉復生；ㄆㄧˊ＝無此音（是「皮」的讀音）；ㄅㄟ＝無此音\n2. 國字拆解與造字原因\n髀：形聲字，「骨」＋「卑」（聲），大腿骨、大腿。劉備嘆久不騎馬「髀肉復生」——大腿長回贅肉，功業未建。讀ㄅㄧˋ。"},
  {id:"p221",grade:11,word:"暴殄天物",target:"殄",zhuyin:"ㄊㄧㄢˇ",pinyin:"tiǎn",wrong:[{z:"ㄓㄣ",p:"zhēn"},{z:"ㄊㄧㄢ",p:"tiān"}],note:"「暴殄天物」的「殄」讀ㄊㄧㄢˇ，滅絕糟蹋。",deep:"1. 注音比較\n殄：ㄊㄧㄢˇ（三聲）＝暴殄天物；ㄓㄣ＝無此音（是「珍」的讀音）；ㄊㄧㄢ＝誤讀\n2. 國字拆解與造字原因\n殄：從「歹」（殘骨），滅絕、糟蹋→暴殄天物（任意糟蹋東西）。讀ㄊㄧㄢˇ，與「舔」同音。"},
  {id:"p222",grade:11,word:"沆瀣一氣",target:"沆",zhuyin:"ㄏㄤˋ",pinyin:"hàng",wrong:[{z:"ㄎㄤ",p:"kāng"},{z:"ㄏㄤˊ",p:"háng"}],note:"「沆瀣」讀ㄏㄤˋ ㄒㄧㄝˋ，夜間的水氣。",deep:"1. 注音比較\n沆：ㄏㄤˋ（四聲）＝沆瀣一氣；ㄎㄤ＝無此音；ㄏㄤˊ＝誤讀（受「航」影響）\n2. 國字拆解與造字原因\n沆：「氵」＋「亢」（聲），「沆瀣」（ㄏㄤˋ ㄒㄧㄝˋ）是夜間水氣；唐代主考崔沆錄取考生崔瀣，時人譏「座主門生，沆瀣一氣」→氣味相投（今多貶義：勾結一氣）。"},
  {id:"p223",grade:11,word:"魑魅",target:"魅",zhuyin:"ㄇㄟˋ",pinyin:"mèi",wrong:[{z:"ㄨㄟˋ",p:"wèi"},{z:"ㄇㄟˊ",p:"méi"}],note:"「魑魅」「魅力」的「魅」讀ㄇㄟˋ。",deep:"1. 注音比較\n魅：ㄇㄟˋ（四聲）＝魑魅、魅力、魅惑；ㄨㄟˋ＝無此音（是「未」的讀音）；ㄇㄟˊ＝無此音（是「眉」的讀音）\n2. 國字拆解與造字原因\n魅：從「鬼」、「未」（聲），山林精怪→魑魅；迷惑人的力量→魅力。讀ㄇㄟˋ。"},
  {id:"p224",grade:11,word:"倥傯戎馬",target:"倥",zhuyin:"ㄎㄨㄥˇ",pinyin:"kǒng",wrong:[{z:"ㄎㄨㄥ",p:"kōng"},{z:"ㄎㄨㄥˋ",p:"kòng"}],note:"「倥傯」讀ㄎㄨㄥˇ ㄗㄨㄥˇ。",deep:"1. 注音比較\n倥：ㄎㄨㄥˇ（三聲）＝倥傯；ㄎㄨㄥ＝誤讀（受「空」影響）；ㄎㄨㄥˋ＝無此音\n2. 國字拆解與造字原因\n倥：形聲字，「亻」＋「空」（聲），「倥傯」（ㄎㄨㄥˇ ㄗㄨㄥˇ）＝事務匆迫——「戎馬倥傯」形容軍務繁忙。"},
  {id:"p225",grade:11,word:"擘畫",target:"擘",zhuyin:"ㄅㄛˋ",pinyin:"bò",wrong:[{z:"ㄅㄧˋ",p:"bì"},{z:"ㄆㄧˊ",p:"pí"}],note:"「擘畫」「巨擘」的「擘」讀ㄅㄛˋ。",deep:"1. 注音比較\n擘：ㄅㄛˋ（四聲）＝擘畫、巨擘；ㄅㄧˋ＝無此音（是「臂」的讀音）；ㄆㄧˊ＝無此音\n2. 國字拆解與造字原因\n擘：從「手」、「辟」（聲），本義是大拇指→行業中的頂尖人物（巨擘）；用手分開、規劃（擘畫）。讀ㄅㄛˋ。"},
  {id:"p226",grade:11,word:"箇中翹楚",target:"翹",zhuyin:"ㄑㄧㄠˊ",pinyin:"qiáo",wrong:[{z:"ㄑㄧㄠˋ",p:"qiào"},{z:"ㄐㄧㄠˇ",p:"jiǎo"}],note:"「翹楚」（傑出者）讀ㄑㄧㄠˊ；「翹起」讀ㄑㄧㄠˋ。",deep:"1. 注音比較\n翹：ㄑㄧㄠˊ（二聲）＝翹楚、翹首；ㄑㄧㄠˋ（四聲）＝翹起、翹課；ㄐㄧㄠˇ＝無此音\n2. 國字拆解與造字原因\n翹：「羽」＋「堯」（聲），鳥尾長羽。傑出者（翹楚，本指高出的荊木）、抬頭盼望（翹首）讀ㄑㄧㄠˊ；物體一端上揚讀ㄑㄧㄠˋ。"},
  {id:"p227",grade:11,word:"矯枉過正",target:"枉",zhuyin:"ㄨㄤˇ",pinyin:"wǎng",wrong:[{z:"ㄨㄤˊ",p:"wáng"},{z:"ㄎㄨㄤˊ",p:"kuáng"}],note:"「矯枉過正」的「枉」讀ㄨㄤˇ，彎曲。",deep:"1. 注音比較\n枉：ㄨㄤˇ（三聲）＝矯枉過正、冤枉、枉費；ㄨㄤˊ＝無此音（是「亡」的讀音）；ㄎㄨㄤˊ＝無此音\n2. 國字拆解與造字原因\n枉：形聲字，「木」＋「王」（聲），樹木彎曲→彎曲不直（矯枉過正＝糾正彎曲卻矯過了頭）、冤屈（冤枉）。讀ㄨㄤˇ。"},
  {id:"p228",grade:11,word:"賈禍",target:"賈",zhuyin:"ㄍㄨˇ",pinyin:"gǔ",wrong:[{z:"ㄐㄧㄚˇ",p:"jiǎ"},{z:"ㄐㄧㄚˋ",p:"jià"}],note:"「賈禍」（招致災禍）讀ㄍㄨˇ；姓氏讀ㄐㄧㄚˇ。",deep:"1. 注音比較\n賈：ㄍㄨˇ（三聲）＝賈禍（招致）、商賈、餘勇可賈；ㄐㄧㄚˇ（三聲）＝姓賈；ㄐㄧㄚˋ＝通「價」（古用法）\n2. 國字拆解與造字原因\n賈：從「貝」，本義是做買賣的商人（商賈，ㄍㄨˇ）；由「買」引申為招來（賈禍＝招災）。姓氏讀ㄐㄧㄚˇ。"},
  {id:"p229",grade:11,word:"僕僕風塵",target:"僕",zhuyin:"ㄆㄨˊ",pinyin:"pú",wrong:[{z:"ㄆㄨ",p:"pū"},{z:"ㄅㄨˊ",p:"bú"}],note:"「風塵僕僕」的「僕」讀ㄆㄨˊ。",deep:"1. 注音比較\n僕：ㄆㄨˊ（二聲）＝風塵僕僕、僕人、公僕；ㄆㄨ＝無此音（是「撲」的讀音）；ㄅㄨˊ＝無此音\n2. 國字拆解與造字原因\n僕：從「亻」，供役使的人→僕人；「僕僕」是勞頓奔波的樣子→風塵僕僕。讀ㄆㄨˊ。"},
  {id:"p230",grade:11,word:"咋舌",target:"咋",zhuyin:"ㄗㄜˊ",pinyin:"zé",wrong:[{z:"ㄓㄚˋ",p:"zhà"},{z:"ㄗㄚˇ",p:"zǎ"}],note:"「令人咋舌」的「咋」讀ㄗㄜˊ，咬住。",deep:"1. 注音比較\n咋：ㄗㄜˊ（二聲）＝令人咋舌；ㄓㄚˋ＝無此音（是「炸」的讀音）；ㄗㄚˇ＝北方方言「怎麼」\n2. 國字拆解與造字原因\n咋：形聲字，「口」＋「乍」（聲），咬住→咋舌（驚訝得咬住舌頭說不出話）。讀ㄗㄜˊ。"},
  {id:"p231",grade:12,word:"齷齪",target:"齷",zhuyin:"ㄨㄛˋ",pinyin:"wò",wrong:[{z:"ㄨㄛ",p:"wō"},{z:"ㄩㄝˋ",p:"yuè"}],note:"「齷齪」讀ㄨㄛˋ ㄔㄨㄛˋ，骯髒卑劣。",deep:"1. 注音比較\n齷：ㄨㄛˋ（四聲）＝齷齪；ㄨㄛ＝誤讀；ㄩㄝˋ＝無此音\n2. 國字拆解與造字原因\n齷：從「齒」，「齷齪」（ㄨㄛˋ ㄔㄨㄛˋ）本指牙齒細密，引申為器量狹小、骯髒卑劣（心思齷齪）。"},
  {id:"p232",grade:12,word:"蹭蹬",target:"蹬",zhuyin:"ㄉㄥˋ",pinyin:"dèng",wrong:[{z:"ㄉㄥ",p:"dēng"},{z:"ㄔㄥˊ",p:"chéng"}],note:"「蹭蹬」讀ㄘㄥˋ ㄉㄥˋ，失意潦倒。",deep:"1. 注音比較\n蹬：ㄉㄥˋ（四聲）＝蹭蹬；ㄉㄥ（一聲）＝蹬腿、蹬自行車；ㄔㄥˊ＝無此音\n2. 國字拆解與造字原因\n蹬：「足」＋「登」（聲），用腳踏。「蹭蹬」（ㄘㄥˋ ㄉㄥˋ）指路難行→失意潦倒（仕途蹭蹬）。"},
  {id:"p233",grade:12,word:"踟躕不前",target:"踟",zhuyin:"ㄔˊ",pinyin:"chí",wrong:[{z:"ㄓ",p:"zhī"},{z:"ㄉㄧˊ",p:"dí"}],note:"「踟躕」讀ㄔˊ ㄔㄨˊ，徘徊不前。",deep:"1. 注音比較\n踟：ㄔˊ（二聲）＝踟躕；ㄓ＝誤讀；ㄉㄧˊ＝無此音\n2. 國字拆解與造字原因\n踟：「足」＋「知」（聲），「踟躕」（ㄔˊ ㄔㄨˊ）是連綿詞：徘徊不前、猶豫（〈陌上桑〉「使君從南來，五馬立踟躕」）。"},
  {id:"p234",grade:12,word:"躑躅",target:"躅",zhuyin:"ㄓㄨˊ",pinyin:"zhú",wrong:[{z:"ㄕㄨˇ",p:"shǔ"},{z:"ㄔㄨˊ",p:"chú"}],note:"「躑躅」讀ㄓˊ ㄓㄨˊ，徘徊不進。",deep:"1. 注音比較\n躅：ㄓㄨˊ（二聲）＝躑躅；ㄕㄨˇ＝無此音（是「蜀」的讀音）；ㄔㄨˊ＝無此音\n2. 國字拆解與造字原因\n躅：「足」＋「蜀」（聲），「躑躅」（ㄓˊ ㄓㄨˊ）是連綿詞：徘徊不進。與「踟躕」義近。"},
  {id:"p235",grade:12,word:"矍鑠",target:"矍",zhuyin:"ㄐㄩㄝˊ",pinyin:"jué",wrong:[{z:"ㄍㄨㄛˋ",p:"guò"},{z:"ㄑㄩˊ",p:"qú"}],note:"「精神矍鑠」讀ㄐㄩㄝˊ ㄕㄨㄛˋ，老而強健。",deep:"1. 注音比較\n矍：ㄐㄩㄝˊ（二聲）＝精神矍鑠；ㄍㄨㄛˋ＝無此音；ㄑㄩˊ＝無此音（是「瞿」的讀音）\n2. 國字拆解與造字原因\n矍：從二「目」從「隹」從「又」，本義是鳥驚視張望——目光炯炯。「矍鑠」（ㄐㄩㄝˊ ㄕㄨㄛˋ）形容老人強健有神。"},
  {id:"p236",grade:12,word:"日晷",target:"晷",zhuyin:"ㄍㄨㄟˇ",pinyin:"guǐ",wrong:[{z:"ㄐㄧㄡˋ",p:"jiù"},{z:"ㄍㄨㄟ",p:"guī"}],note:"「日晷」「焚膏繼晷」的「晷」讀ㄍㄨㄟˇ，日影。",deep:"1. 注音比較\n晷：ㄍㄨㄟˇ（三聲）＝日晷、焚膏繼晷；ㄐㄧㄡˋ＝無此音（是「咎」的讀音）；ㄍㄨㄟ＝誤讀\n2. 國字拆解與造字原因\n晷：「日」＋「咎」（聲），日影→日晷（以日影計時的儀器）、繼晷（接續日光）。讀ㄍㄨㄟˇ，與「軌」同音。"},
  {id:"p237",grade:12,word:"褫奪公權",target:"褫",zhuyin:"ㄔˇ",pinyin:"chǐ",wrong:[{z:"ㄉㄧˋ",p:"dì"},{z:"ㄊㄧˇ",p:"tǐ"}],note:"「褫奪」的「褫」讀ㄔˇ，剝奪。",deep:"1. 注音比較\n褫：ㄔˇ（三聲）＝褫奪公權；ㄉㄧˋ＝無此音；ㄊㄧˇ＝無此音\n2. 國字拆解與造字原因\n褫：「衤」＋「虒」（聲），本義是剝去衣服→剝奪（褫奪公權）。讀ㄔˇ，與「恥」同音。"},
  {id:"p238",grade:12,word:"蹙眉",target:"蹙",zhuyin:"ㄘㄨˋ",pinyin:"cù",wrong:[{z:"ㄗㄨˊ",p:"zú"},{z:"ㄑㄧ",p:"qī"}],note:"「蹙眉」「窮蹙」的「蹙」讀ㄘㄨˋ，皺縮。",deep:"1. 注音比較\n蹙：ㄘㄨˋ（四聲）＝蹙眉、窮蹙；ㄗㄨˊ＝無此音（是「足」的讀音）；ㄑㄧ＝無此音\n2. 國字拆解與造字原因\n蹙：從「足」、「戚」（聲），本義是緊迫→皺縮（蹙眉＝皺眉頭）、困窘（窮蹙）。讀ㄘㄨˋ，與「促」同音。"},
  {id:"p239",grade:12,word:"驪歌",target:"驪",zhuyin:"ㄌㄧˊ",pinyin:"lí",wrong:[{z:"ㄌㄧˋ",p:"lì"},{z:"ㄌㄩˊ",p:"lǘ"}],note:"「驪歌」（離別之歌）的「驪」讀ㄌㄧˊ。",deep:"1. 注音比較\n驪：ㄌㄧˊ（二聲）＝驪歌、驪山；ㄌㄧˋ＝誤讀；ㄌㄩˊ＝無此音（是「驢」的讀音）\n2. 國字拆解與造字原因\n驪：「馬」＋「麗」（聲），本義是純黑色的馬。「驪歌」是離別時唱的歌（語出古〈驪駒〉逸詩）。讀ㄌㄧˊ，與「離」同音好記。"},
  {id:"p240",grade:12,word:"蛻變",target:"蛻",zhuyin:"ㄕㄨㄟˋ",pinyin:"shuì",wrong:[{z:"ㄊㄨㄟˋ",p:"tuì"},{z:"ㄩㄝˋ",p:"yuè"}],note:"審訂音「蛻變」的「蛻」讀ㄕㄨㄟˋ。",deep:"1. 注音比較\n蛻：ㄕㄨㄟˋ（四聲）＝蛻變、蛻皮、蟬蛻（審訂音）；ㄊㄨㄟˋ＝俗讀，審訂表不採；ㄩㄝˋ＝無此音\n2. 國字拆解與造字原因\n蛻：「虫」＋「兌」（聲），蟲蛇脫下的皮→蛻皮；脫胎換骨的轉變（蛻變）。審訂音讀ㄕㄨㄟˋ，與「睡」同音。"},
  {id:"p241",grade:12,word:"菌蕈",target:"蕈",zhuyin:"ㄒㄩㄣˋ",pinyin:"xùn",wrong:[{z:"ㄊㄢˊ",p:"tán"},{z:"ㄒㄧㄣ",p:"xīn"}],note:"「蕈類」的「蕈」讀ㄒㄩㄣˋ，菇類。",deep:"1. 注音比較\n蕈：ㄒㄩㄣˋ（四聲）＝蕈類、毒蕈；ㄊㄢˊ＝無此音（是「覃」的讀音）；ㄒㄧㄣ＝無此音\n2. 國字拆解與造字原因\n蕈：「艹」＋「覃」（聲），生於朽木腐土上的菇類→蕈類。讀ㄒㄩㄣˋ，與「訓」同音。"},
  {id:"p242",grade:12,word:"躉售",target:"躉",zhuyin:"ㄉㄨㄣˇ",pinyin:"dǔn",wrong:[{z:"ㄨㄢˋ",p:"wàn"},{z:"ㄉㄨㄣˋ",p:"dùn"}],note:"「躉售」「躉批」的「躉」讀ㄉㄨㄣˇ，整批買賣。",deep:"1. 注音比較\n躉：ㄉㄨㄣˇ（三聲）＝躉售、躉批、船躉；ㄨㄢˋ＝無此音（是「萬」的讀音）；ㄉㄨㄣˋ＝誤讀\n2. 國字拆解與造字原因\n躉：「萬」＋「足」，整數、整批→躉售（整批出售）、躉批。讀ㄉㄨㄣˇ，與「盹」同音。"},
  {id:"p243",grade:12,word:"藺相如",target:"藺",zhuyin:"ㄌㄧㄣˋ",pinyin:"lìn",wrong:[{z:"ㄌㄧˋ",p:"lì"},{z:"ㄌㄢˊ",p:"lán"}],note:"「藺」讀ㄌㄧㄣˋ；藺草、藺相如皆同。",deep:"1. 注音比較\n藺：ㄌㄧㄣˋ（四聲）＝藺相如、藺草；ㄌㄧˋ＝無此音；ㄌㄢˊ＝無此音（是「蘭」的讀音）\n2. 國字拆解與造字原因\n藺：「艹」＋「閵」（聲），草名（藺草可編蓆），也是姓氏（藺相如）。讀ㄌㄧㄣˋ，與「吝」同音。"},
  {id:"p244",grade:12,word:"臺榭樓閣",target:"榭",zhuyin:"ㄒㄧㄝˋ",pinyin:"xiè",wrong:[{z:"ㄒㄧㄝˊ",p:"xié"},{z:"ㄕㄜˋ",p:"shè"}],note:"「樓榭」的「榭」讀ㄒㄧㄝˋ，建在高臺上的屋子。",deep:"1. 注音比較\n榭：ㄒㄧㄝˋ（四聲）＝樓榭、歌臺舞榭；ㄒㄧㄝˊ＝誤讀（受「斜」影響）；ㄕㄜˋ＝無此音（是「射」的讀音）\n2. 國字拆解與造字原因\n榭：「木」＋「射」（聲），建在高臺上的木造敞屋→水榭、舞榭。讀ㄒㄧㄝˋ，與「謝」同音。"},
  {id:"p245",grade:12,word:"橫槊賦詩",target:"槊",zhuyin:"ㄕㄨㄛˋ",pinyin:"shuò",wrong:[{z:"ㄙㄨㄛˇ",p:"suǒ"},{z:"ㄕㄨㄛ",p:"shuō"}],note:"「橫槊賦詩」的「槊」讀ㄕㄨㄛˋ，長矛。",deep:"1. 注音比較\n槊：ㄕㄨㄛˋ（四聲）＝橫槊賦詩；ㄙㄨㄛˇ＝無此音（是「索」的讀音）；ㄕㄨㄛ＝誤讀\n2. 國字拆解與造字原因\n槊：「朔」（聲）＋「木」，長柄的矛。蘇軾〈赤壁賦〉寫曹操「橫槊賦詩」——橫持長矛吟詩。讀ㄕㄨㄛˋ。"},
  {id:"p246",grade:12,word:"耆老",target:"耆",zhuyin:"ㄑㄧˊ",pinyin:"qí",wrong:[{z:"ㄕˋ",p:"shì"},{z:"ㄓˇ",p:"zhǐ"}],note:"「耆老」「耆宿」的「耆」讀ㄑㄧˊ，六十歲以上長者。",deep:"1. 注音比較\n耆：ㄑㄧˊ（二聲）＝耆老、耆宿；ㄕˋ＝無此音（是「嗜」的讀音）；ㄓˇ＝無此音\n2. 國字拆解與造字原因\n耆：從「老（省）」、「旨」（聲），六十歲以上的長者→耆老、耆宿（有名望的老人）。讀ㄑㄧˊ，與「其」同音。"},
  {id:"p247",grade:12,word:"譖言",target:"譖",zhuyin:"ㄗㄣˋ",pinyin:"zèn",wrong:[{z:"ㄐㄧㄢ",p:"jiān"},{z:"ㄑㄧㄢˊ",p:"qián"}],note:"「譖言」的「譖」讀ㄗㄣˋ，誣陷毀謗的話。",deep:"1. 注音比較\n譖：ㄗㄣˋ（四聲）＝譖言；ㄐㄧㄢ＝無此音；ㄑㄧㄢˊ＝無此音（是「潛」的讀音）\n2. 國字拆解與造字原因\n譖：「言」＋「朁」（聲），進讒毀謗→譖言（誣陷的話）。讀ㄗㄣˋ。"},
  {id:"p248",grade:12,word:"詰問",target:"詰",zhuyin:"ㄐㄧㄝˊ",pinyin:"jié",wrong:[{z:"ㄐㄧˊ",p:"jí"},{z:"ㄎㄡˋ",p:"kòu"}],note:"「詰問」「反詰」的「詰」讀ㄐㄧㄝˊ，追問責問。",deep:"1. 注音比較\n詰：ㄐㄧㄝˊ（二聲）＝詰問、反詰、盤詰；ㄐㄧˊ＝誤讀；ㄎㄡˋ＝無此音\n2. 國字拆解與造字原因\n詰：「言」＋「吉」（聲），追問責問→詰問、反詰。讀ㄐㄧㄝˊ，與「傑」同音。"},
  {id:"p249",grade:12,word:"罄竹難書",target:"罄",zhuyin:"ㄑㄧㄥˋ",pinyin:"qìng",wrong:[{z:"ㄑㄧㄥ",p:"qīng"},{z:"ㄒㄧㄣ",p:"xīn"}],note:"「罄竹難書」的「罄」讀ㄑㄧㄥˋ，用盡。",deep:"1. 注音比較\n罄：ㄑㄧㄥˋ（四聲）＝罄竹難書、告罄；ㄑㄧㄥ＝誤讀（受「青」影響）；ㄒㄧㄣ＝無此音（是「馨」的讀音）\n2. 國字拆解與造字原因\n罄：「缶」（瓦器）＋「殸」（聲），器中空了→用盡（存貨告罄、罄竹難書）。讀ㄑㄧㄥˋ，與「慶」同音。"},
  {id:"p250",grade:12,word:"饗宴",target:"饗",zhuyin:"ㄒㄧㄤˇ",pinyin:"xiǎng",wrong:[{z:"ㄒㄧㄤ",p:"xiāng"},{z:"ㄒㄧㄤˋ",p:"xiàng"}],note:"「饗宴」的「饗」讀ㄒㄧㄤˇ，以酒食款待。",deep:"1. 注音比較\n饗：ㄒㄧㄤˇ（三聲）＝饗宴、以饗讀者；ㄒㄧㄤ＝誤讀；ㄒㄧㄤˋ＝無此音（是「向」的讀音）\n2. 國字拆解與造字原因\n饗：「鄉」（聲）＋「食」，以酒食款待賓客→饗宴；提供給人享用（以饗讀者）。讀ㄒㄧㄤˇ，與「享」同音。"},
  {id:"p251",grade:12,word:"戮力同心",target:"戮",zhuyin:"ㄌㄨˋ",pinyin:"lù",wrong:[{z:"ㄌㄧㄡˋ",p:"liù"},{z:"ㄌㄨㄛˋ",p:"luò"}],note:"「戮力同心」的「戮」讀ㄌㄨˋ，合力。",deep:"1. 注音比較\n戮：ㄌㄨˋ（四聲）＝戮力同心、殺戮；ㄌㄧㄡˋ＝無此音；ㄌㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n戮：從「戈」，本義是殺（殺戮）；通「勠」表合力→戮力同心（合力一心）。讀ㄌㄨˋ，與「路」同音。"},
  {id:"p252",grade:12,word:"馘首",target:"馘",zhuyin:"ㄍㄨㄛˊ",pinyin:"guó",wrong:[{z:"ㄒㄩˋ",p:"xù"},{z:"ㄏㄨㄛˋ",p:"huò"}],note:"「馘首」的「馘」讀ㄍㄨㄛˊ，割取首級。",deep:"1. 注音比較\n馘：ㄍㄨㄛˊ（二聲）＝馘首；ㄒㄩˋ＝無此音；ㄏㄨㄛˋ＝無此音（是「獲」的讀音）\n2. 國字拆解與造字原因\n馘：從「首」、「或」（聲），古代戰爭割取敵人首級或左耳計功→馘首。讀ㄍㄨㄛˊ，與「國」同音。"},
  {id:"p253",grade:12,word:"耄耋之年",target:"耄",zhuyin:"ㄇㄠˋ",pinyin:"mào",wrong:[{z:"ㄇㄠˊ",p:"máo"},{z:"ㄌㄠˇ",p:"lǎo"}],note:"「耄」讀ㄇㄠˋ，八九十歲。",deep:"1. 注音比較\n耄：ㄇㄠˋ（四聲）＝耄耋之年；ㄇㄠˊ＝無此音（是「毛」的讀音）；ㄌㄠˇ＝無此音（是「老」的讀音）\n2. 國字拆解與造字原因\n耄：從「老（省）」、「毛」（聲），八九十歲高齡→耄耋（ㄇㄠˋ ㄉㄧㄝˊ）。讀ㄇㄠˋ，與「冒」同音。"},
  {id:"p254",grade:12,word:"觥籌交錯",target:"觥",zhuyin:"ㄍㄨㄥ",pinyin:"gōng",wrong:[{z:"ㄍㄨㄤ",p:"guāng"},{z:"ㄏㄨㄤˊ",p:"huáng"}],note:"「觥」讀ㄍㄨㄥ，古代酒器。",deep:"1. 注音比較\n觥：ㄍㄨㄥ（一聲）＝觥籌交錯；ㄍㄨㄤ＝誤讀（受「光」影響）；ㄏㄨㄤˊ＝無此音\n2. 國字拆解與造字原因\n觥：從「角」，古代獸角形的酒器→觥籌交錯（酒杯與酒籌錯雜，宴飲盡歡）。讀ㄍㄨㄥ，與「公」同音。"},
  {id:"p255",grade:12,word:"泅水",target:"泅",zhuyin:"ㄑㄧㄡˊ",pinyin:"qiú",wrong:[{z:"ㄒㄧㄡ",p:"xiū"},{z:"ㄧㄡˊ",p:"yóu"}],note:"「泅水」的「泅」讀ㄑㄧㄡˊ，游泳。",deep:"1. 注音比較\n泅：ㄑㄧㄡˊ（二聲）＝泅水、泅泳；ㄒㄧㄡ＝無此音（是「修」的讀音）；ㄧㄡˊ＝無此音（是「游」的讀音）\n2. 國字拆解與造字原因\n泅：「氵」＋「囚」（聲），游水→泅水渡河。讀ㄑㄧㄡˊ，與「求」同音。"},
  {id:"p256",grade:12,word:"胼手胝足",target:"胝",zhuyin:"ㄓ",pinyin:"zhī",wrong:[{z:"ㄉㄧˇ",p:"dǐ"},{z:"ㄓˇ",p:"zhǐ"}],note:"「胼手胝足」讀ㄆㄧㄢˊ ㄕㄡˇ ㄓ ㄗㄨˊ，手腳長繭，形容辛勞。",deep:"1. 注音比較\n胝：ㄓ（一聲）＝胼手胝足；ㄉㄧˇ＝無此音（是「底」的讀音）；ㄓˇ＝誤讀\n2. 國字拆解與造字原因\n胝：「月（肉）」＋「氐」（聲），手腳因勞動磨出的厚繭。「胼手胝足」（ㄆㄧㄢˊ ㄕㄡˇ ㄓ ㄗㄨˊ）形容極其辛勞。讀一聲ㄓ。"},
  {id:"p257",grade:12,word:"杯盤狼藉",target:"藉",zhuyin:"ㄐㄧˊ",pinyin:"jí",wrong:[{z:"ㄐㄧㄝˋ",p:"jiè"},{z:"ㄒㄧˊ",p:"xí"}],note:"「狼藉」讀ㄌㄤˊ ㄐㄧˊ；「藉口」「憑藉」讀ㄐㄧㄝˋ。",deep:"1. 注音比較\n藉：ㄐㄧˊ（二聲）＝杯盤狼藉、聲名狼藉；ㄐㄧㄝˋ（四聲）＝藉口、憑藉、慰藉；ㄒㄧˊ＝無此音\n2. 國字拆解與造字原因\n藉：「艹」＋「耤」（聲），本義是草墊。「狼藉」（傳說狼群臥草後一片凌亂）讀ㄐㄧˊ；依靠、假託讀ㄐㄧㄝˋ。記法：狼藉ㄐㄧˊ、藉口ㄐㄧㄝˋ。"},
  {id:"p258",grade:12,word:"掣肘",target:"掣",zhuyin:"ㄔㄜˋ",pinyin:"chè",wrong:[{z:"ㄓˋ",p:"zhì"},{z:"ㄕˋ",p:"shì"}],note:"「掣肘」的「掣」讀ㄔㄜˋ，牽制阻撓。",deep:"1. 注音比較\n掣：ㄔㄜˋ（四聲）＝掣肘、風馳電掣；ㄓˋ＝誤讀（受「制」影響）；ㄕˋ＝無此音\n2. 國字拆解與造字原因\n掣：「制」（聲）＋「手」，拉扯、牽制→掣肘（拉住手肘，比喻從旁阻撓）；快速拉過→電掣。讀ㄔㄜˋ，與「徹」同音。"},
  {id:"p259",grade:12,word:"僭主",target:"僭",zhuyin:"ㄐㄧㄢˋ",pinyin:"jiàn",wrong:[{z:"ㄗㄢˋ",p:"zàn"},{z:"ㄑㄧㄢ",p:"qiān"}],note:"「僭」讀ㄐㄧㄢˋ，越分冒用。",deep:"1. 注音比較\n僭：ㄐㄧㄢˋ（四聲）＝僭主、僭越；ㄗㄢˋ＝無此音（是「贊」的讀音）；ㄑㄧㄢ＝無此音\n2. 國字拆解與造字原因\n僭：「亻」＋「朁」（聲），超越本分冒用上位名器→僭越、僭主（非法奪位者）。讀ㄐㄧㄢˋ，與「見」同音。"},
  {id:"p260",grade:12,word:"謳歌",target:"謳",zhuyin:"ㄡ",pinyin:"ōu",wrong:[{z:"ㄑㄩ",p:"qū"},{z:"ㄡˇ",p:"ǒu"}],note:"「謳歌」的「謳」讀ㄡ，歌頌。",deep:"1. 注音比較\n謳：ㄡ（一聲）＝謳歌；ㄑㄩ＝無此音（是「驅」的讀音）；ㄡˇ＝誤讀\n2. 國字拆解與造字原因\n謳：「言」＋「區」（聲），歌唱→謳歌（歌頌讚美）。讀一聲ㄡ，與「歐」同音。"},
  {id:"p261",grade:6,word:"拓印",target:"拓",zhuyin:"ㄊㄚˋ",pinyin:"tà",wrong:[{z:"ㄊㄨㄛˋ",p:"tuò"},{z:"ㄓㄨㄛˊ",p:"zhuó"}],note:"「拓印」「拓本」讀ㄊㄚˋ；「開拓」讀ㄊㄨㄛˋ。",deep:"1. 注音比較\n拓：ㄊㄚˋ（四聲）＝拓印、拓本、拓碑；ㄊㄨㄛˋ（四聲）＝開拓、拓展；ㄓㄨㄛˊ＝無此音\n2. 國字拆解與造字原因\n拓：形聲字，「扌」＋「石」（聲）。用手開墾擴展讀ㄊㄨㄛˋ（開拓）；把碑刻文字撲印在紙上讀ㄊㄚˋ（拓印、拓本）。記法：印碑ㄊㄚˋ、開展ㄊㄨㄛˋ。"},
  {id:"p262",grade:6,word:"綻開",target:"綻",zhuyin:"ㄓㄢˋ",pinyin:"zhàn",wrong:[{z:"ㄉㄧㄥˋ",p:"dìng"},{z:"ㄒㄧㄢˋ",p:"xiàn"}],note:"「綻開」「綻裂」的「綻」讀ㄓㄢˋ。",deep:"1. 注音比較\n綻：ㄓㄢˋ（四聲）＝綻開、綻放、破綻；ㄉㄧㄥˋ＝無此音（是「定」的讀音）；ㄒㄧㄢˋ＝無此音\n2. 國字拆解與造字原因\n綻：形聲字，「糸」＋「定」（聲），衣縫裂開→破綻；花苞裂開→綻放。從「定」得聲卻讀ㄓㄢˋ。"},
  {id:"p263",grade:6,word:"魚鰭",target:"鰭",zhuyin:"ㄑㄧˊ",pinyin:"qí",wrong:[{z:"ㄑㄧ",p:"qī"},{z:"ㄕˋ",p:"shì"}],note:"「魚鰭」的「鰭」讀ㄑㄧˊ。",deep:"1. 注音比較\n鰭：ㄑㄧˊ（二聲）＝魚鰭、背鰭；ㄑㄧ＝誤讀；ㄕˋ＝無此音\n2. 國字拆解與造字原因\n鰭：形聲字，「魚」＋「耆」（聲），魚類游泳的薄膜器官。與「旗」同音ㄑㄧˊ——魚鰭像魚身上的小旗，好記。"},
  {id:"p264",grade:6,word:"迂迴",target:"迂",zhuyin:"ㄩ",pinyin:"yū",wrong:[{z:"ㄩˊ",p:"yú"},{z:"ㄒㄩ",p:"xū"}],note:"「迂迴」「迂腐」的「迂」讀ㄩ。",deep:"1. 注音比較\n迂：ㄩ（一聲）＝迂迴、迂腐；ㄩˊ＝誤讀（受「于」影響）；ㄒㄩ＝無此音（是「需」的讀音）\n2. 國字拆解與造字原因\n迂：形聲字，「辶」＋「于」（聲），繞遠路→迂迴；思想繞遠不切實際→迂腐。讀一聲ㄩ。"},
  {id:"p265",grade:6,word:"眷戀",target:"眷",zhuyin:"ㄐㄩㄢˋ",pinyin:"juàn",wrong:[{z:"ㄐㄩㄢ",p:"juān"},{z:"ㄑㄩㄢˋ",p:"quàn"}],note:"「眷戀」「眷村」的「眷」讀ㄐㄩㄢˋ。",deep:"1. 注音比較\n眷：ㄐㄩㄢˋ（四聲）＝眷戀、眷屬、眷村；ㄐㄩㄢ＝無此音（是「捐」的讀音）；ㄑㄩㄢˋ＝無此音（是「勸」的讀音）\n2. 國字拆解與造字原因\n眷：從「目」，本義是回頭看→顧念不捨（眷戀）；所顧念的家人→眷屬。讀ㄐㄩㄢˋ。"},
  {id:"p266",grade:6,word:"堤岸",target:"岸",zhuyin:"ㄢˋ",pinyin:"àn",wrong:[{z:"ㄢˊ",p:"án"},{z:"ㄏㄢˋ",p:"hàn"}],note:"「堤岸」讀ㄊㄧˊ ㄢˋ。",deep:"1. 注音比較\n岸：ㄢˋ（四聲）＝堤岸、河岸、對岸；ㄢˊ＝無此音；ㄏㄢˋ＝無此音（是「漢」的讀音）\n2. 國字拆解與造字原因\n岸：形聲字，「山」＋「厂」「干」（聲），水邊高起的陸地→河岸、海岸。讀ㄢˋ。"},
  {id:"p267",grade:6,word:"卑躬屈膝",target:"屈",zhuyin:"ㄑㄩ",pinyin:"qū",wrong:[{z:"ㄑㄩˇ",p:"qǔ"},{z:"ㄐㄩˊ",p:"jú"}],note:"「屈膝」「委屈」的「屈」讀ㄑㄩ。",deep:"1. 注音比較\n屈：ㄑㄩ（一聲）＝屈膝、委屈、屈服；ㄑㄩˇ＝無此音（是「取」的讀音）；ㄐㄩˊ＝無此音（是「局」的讀音）\n2. 國字拆解與造字原因\n屈：形聲字，「尸」（人形）＋「出」（聲），身體彎曲→屈膝；受壓不能伸張→委屈、屈服。讀一聲ㄑㄩ。"},
  {id:"p268",grade:6,word:"手足無措",target:"措",zhuyin:"ㄘㄨㄛˋ",pinyin:"cuò",wrong:[{z:"ㄗㄨㄛˋ",p:"zuò"},{z:"ㄘㄨㄛ",p:"cuō"}],note:"「措手不及」「措施」的「措」讀ㄘㄨㄛˋ。",deep:"1. 注音比較\n措：ㄘㄨㄛˋ（四聲）＝措施、措手不及、手足無措；ㄗㄨㄛˋ＝無此音（是「做」的讀音）；ㄘㄨㄛ＝無此音（是「搓」的讀音）\n2. 國字拆解與造字原因\n措：形聲字，「扌」＋「昔」（聲），本義是安放、安排→措施（安排的辦法）、手足無措（手腳不知往哪放）。讀ㄘㄨㄛˋ。"},
  {id:"p269",grade:6,word:"諷刺",target:"諷",zhuyin:"ㄈㄥˋ",pinyin:"fèng",wrong:[{z:"ㄈㄥ",p:"fēng"},{z:"ㄈㄥˊ",p:"féng"}],note:"「諷刺」「嘲諷」的「諷」讀ㄈㄥˋ。",deep:"1. 注音比較\n諷：ㄈㄥˋ（四聲）＝諷刺、嘲諷、譏諷；ㄈㄥ＝誤讀（受「風」影響）；ㄈㄥˊ＝無此音（是「逢」的讀音）\n2. 國字拆解與造字原因\n諷：形聲字，「言」＋「風」（聲），本義是不看書本背誦，引申為用含蓄的話勸告譏刺→諷刺。讀四聲ㄈㄥˋ。"},
  {id:"p270",grade:6,word:"泥濘",target:"濘",zhuyin:"ㄋㄧㄥˋ",pinyin:"nìng",wrong:[{z:"ㄋㄧㄥˊ",p:"níng"},{z:"ㄓㄥ",p:"zhēng"}],note:"「泥濘」的「濘」讀ㄋㄧㄥˋ。",deep:"1. 注音比較\n濘：ㄋㄧㄥˋ（四聲）＝泥濘；ㄋㄧㄥˊ＝誤讀（受「寧」影響）；ㄓㄥ＝無此音\n2. 國字拆解與造字原因\n濘：形聲字，「氵」＋「寧」（聲），爛泥積水→泥濘。從「寧」得聲卻讀四聲ㄋㄧㄥˋ。"},
  {id:"p271",grade:7,word:"惋惜",target:"惋",zhuyin:"ㄨㄢˇ",pinyin:"wǎn",wrong:[{z:"ㄨㄢˋ",p:"wàn"},{z:"ㄩㄢˋ",p:"yuàn"}],note:"「惋惜」的「惋」讀ㄨㄢˇ。",deep:"1. 注音比較\n惋：ㄨㄢˇ（三聲）＝惋惜；ㄨㄢˋ＝誤讀（受「腕」影響）；ㄩㄢˋ＝無此音（是「怨」的讀音）\n2. 國字拆解與造字原因\n惋：形聲字，「忄」＋「宛」（聲），心中嘆惜→惋惜。讀三聲ㄨㄢˇ，與「腕」（ㄨㄢˋ）不同。"},
  {id:"p272",grade:7,word:"貯藏",target:"貯",zhuyin:"ㄓㄨˇ",pinyin:"zhǔ",wrong:[{z:"ㄔㄨˊ",p:"chú"},{z:"ㄉㄧㄥˇ",p:"dǐng"}],note:"「貯藏」「貯存」的「貯」讀ㄓㄨˇ。",deep:"1. 注音比較\n貯：ㄓㄨˇ（三聲）＝貯藏、貯存、貯水；ㄔㄨˊ＝無此音（是「儲」的讀音）；ㄉㄧㄥˇ＝無此音\n2. 國字拆解與造字原因\n貯：形聲字，「貝」（財物）＋「宁」（聲），積存財物→貯藏。與同義的「儲」（ㄔㄨˊ）讀音不同，注意分辨。"},
  {id:"p273",grade:7,word:"瑰麗",target:"瑰",zhuyin:"ㄍㄨㄟ",pinyin:"guī",wrong:[{z:"ㄍㄨㄟˋ",p:"guì"},{z:"ㄎㄨㄟˊ",p:"kuí"}],note:"「瑰麗」「玫瑰」的「瑰」讀ㄍㄨㄟ。",deep:"1. 注音比較\n瑰：ㄍㄨㄟ（一聲）＝瑰麗、玫瑰、瑰寶；ㄍㄨㄟˋ＝誤讀；ㄎㄨㄟˊ＝無此音（是「魁」的讀音）\n2. 國字拆解與造字原因\n瑰：形聲字，「𤣩（玉）」＋「鬼」（聲），美玉、美石→瑰寶、瑰麗（如美玉般華美）。讀一聲ㄍㄨㄟ。"},
  {id:"p274",grade:7,word:"剎那",target:"剎",zhuyin:"ㄔㄚˋ",pinyin:"chà",wrong:[{z:"ㄕㄚ",p:"shā"},{z:"ㄙㄚˋ",p:"sà"}],note:"「剎那」讀ㄔㄚˋ；「煞車」的「煞」讀ㄕㄚ。",deep:"1. 注音比較\n剎：ㄔㄚˋ（四聲）＝剎那、古剎；ㄕㄚ（一聲）＝剎車（同「煞車」）；ㄙㄚˋ＝無此音\n2. 國字拆解與造字原因\n剎：梵語音譯字，「剎那」（極短時間）、「古剎」（佛寺）讀ㄔㄚˋ；「剎車」借作「煞車」讀ㄕㄚ。"},
  {id:"p275",grade:7,word:"眼眶",target:"眶",zhuyin:"ㄎㄨㄤ",pinyin:"kuāng",wrong:[{z:"ㄎㄨㄤˋ",p:"kuàng"},{z:"ㄍㄨㄤ",p:"guāng"}],note:"「眼眶」的「眶」讀ㄎㄨㄤ，常被誤讀成ㄎㄨㄤˋ。",deep:"1. 注音比較\n眶：ㄎㄨㄤ（一聲）＝眼眶、熱淚盈眶；ㄎㄨㄤˋ＝誤讀（受「況」影響）；ㄍㄨㄤ＝無此音\n2. 國字拆解與造字原因\n眶：形聲字，「目」＋「匡」（聲，方框），眼睛周圍的框→眼眶。讀一聲ㄎㄨㄤ。"},
  {id:"p276",grade:7,word:"歸咎",target:"咎",zhuyin:"ㄐㄧㄡˋ",pinyin:"jiù",wrong:[{z:"ㄐㄧㄡ",p:"jiū"},{z:"ㄍㄨˋ",p:"gù"}],note:"「歸咎」「咎由自取」的「咎」讀ㄐㄧㄡˋ，過失。",deep:"1. 注音比較\n咎：ㄐㄧㄡˋ（四聲）＝歸咎、咎由自取、引咎辭職；ㄐㄧㄡ＝誤讀；ㄍㄨˋ＝無此音\n2. 國字拆解與造字原因\n咎：會意字，「人」＋「各」（相違背），人與人相違而生過失→罪過、責備（歸咎）。讀ㄐㄧㄡˋ。"},
  {id:"p277",grade:7,word:"星羅棋布",target:"布",zhuyin:"ㄅㄨˋ",pinyin:"bù",wrong:[{z:"ㄅㄨˇ",p:"bǔ"},{z:"ㄆㄨ",p:"pū"}],note:"「星羅棋布」的「布」讀ㄅㄨˋ，分布。",deep:"1. 注音比較\n布：ㄅㄨˋ（四聲）＝星羅棋布、分布、宣布；ㄅㄨˇ＝無此音（是「補」的讀音）；ㄆㄨ＝無此音（是「鋪」的讀音）\n2. 國字拆解與造字原因\n布：從「巾」，本義是麻織品，鋪展開來→分布、散布。「星羅棋布」＝像星星羅列、棋子分布，形容多而密。"},
  {id:"p278",grade:7,word:"傾瀉",target:"瀉",zhuyin:"ㄒㄧㄝˋ",pinyin:"xiè",wrong:[{z:"ㄒㄧㄝˇ",p:"xiě"},{z:"ㄕㄜˋ",p:"shè"}],note:"「傾瀉」「腹瀉」的「瀉」讀ㄒㄧㄝˋ。",deep:"1. 注音比較\n瀉：ㄒㄧㄝˋ（四聲）＝傾瀉、腹瀉、一瀉千里；ㄒㄧㄝˇ＝誤讀（受「寫」影響）；ㄕㄜˋ＝無此音\n2. 國字拆解與造字原因\n瀉：形聲字，「氵」＋「寫」（聲），水急速往下流→傾瀉、腹瀉。讀ㄒㄧㄝˋ，與「寫」（ㄒㄧㄝˇ）不同調。"},
  {id:"p279",grade:7,word:"游說",target:"游",zhuyin:"ㄧㄡˊ",pinyin:"yóu",wrong:[{z:"ㄧㄡˋ",p:"yòu"},{z:"ㄌㄧㄡˊ",p:"liú"}],note:"「游說」讀ㄧㄡˊ ㄕㄨㄟˋ。",deep:"1. 注音比較\n游：ㄧㄡˊ（二聲）＝游說（ㄧㄡˊ ㄕㄨㄟˋ）、游泳；ㄧㄡˋ＝無此音（是「右」的讀音）；ㄌㄧㄡˊ＝無此音（是「流」的讀音）\n2. 國字拆解與造字原因\n游：形聲字，「氵」＋「斿」（聲），本義是在水中行進；「游說」是奔走各國勸說（像水般流動奔走），「游」讀ㄧㄡˊ、「說」讀ㄕㄨㄟˋ。"},
  {id:"p280",grade:7,word:"埋伏",target:"埋",zhuyin:"ㄇㄞˊ",pinyin:"mái",wrong:[{z:"ㄇㄢˊ",p:"mán"},{z:"ㄌㄧˇ",p:"lǐ"}],note:"「埋伏」「掩埋」讀ㄇㄞˊ；「埋怨」讀ㄇㄢˊ。",deep:"1. 注音比較\n埋：ㄇㄞˊ（二聲）＝埋伏、掩埋、埋藏；ㄇㄢˊ（二聲）＝埋怨；ㄌㄧˇ＝無此音（是「里」的讀音）\n2. 國字拆解與造字原因\n埋：形聲字，「土」＋「里」（聲），把東西藏進土裡→掩埋、埋伏（ㄇㄞˊ）；心中藏著不滿說出來→埋怨（ㄇㄢˊ）。"},
  {id:"p281",grade:8,word:"翩翩起舞",target:"翩",zhuyin:"ㄆㄧㄢ",pinyin:"piān",wrong:[{z:"ㄅㄧㄢ",p:"biān"},{z:"ㄆㄧㄢˊ",p:"pián"}],note:"「翩翩」的「翩」讀ㄆㄧㄢ。",deep:"1. 注音比較\n翩：ㄆㄧㄢ（一聲）＝翩翩起舞、翩然；ㄅㄧㄢ＝無此音（是「編」的讀音）；ㄆㄧㄢˊ＝無此音\n2. 國字拆解與造字原因\n翩：形聲字，「羽」＋「扁」（聲），鳥輕快飛翔的樣子→翩翩起舞（輕盈飄逸）。讀一聲ㄆㄧㄢ。"},
  {id:"p282",grade:8,word:"信箋",target:"箋",zhuyin:"ㄐㄧㄢ",pinyin:"jiān",wrong:[{z:"ㄑㄧㄢ",p:"qiān"},{z:"ㄐㄧㄢˋ",p:"jiàn"}],note:"「信箋」「便箋」的「箋」讀ㄐㄧㄢ。",deep:"1. 注音比較\n箋：ㄐㄧㄢ（一聲）＝信箋、便箋、箋注；ㄑㄧㄢ＝誤讀（受「籤」影響）；ㄐㄧㄢˋ＝無此音\n2. 國字拆解與造字原因\n箋：形聲字，「竹」＋「戔」（聲），本義是注釋經書的小竹片→書信用紙（信箋）。讀ㄐㄧㄢ。"},
  {id:"p283",grade:8,word:"抽搐",target:"搐",zhuyin:"ㄔㄨˋ",pinyin:"chù",wrong:[{z:"ㄒㄩˋ",p:"xù"},{z:"ㄉㄨˋ",p:"dù"}],note:"「抽搐」的「搐」讀ㄔㄨˋ。",deep:"1. 注音比較\n搐：ㄔㄨˋ（四聲）＝抽搐；ㄒㄩˋ＝誤讀（受「蓄」影響）；ㄉㄨˋ＝無此音\n2. 國字拆解與造字原因\n搐：形聲字，「扌」＋「畜」（聲），肌肉不自主地牽動抽動→抽搐。讀ㄔㄨˋ。"},
  {id:"p284",grade:8,word:"踱步",target:"踱",zhuyin:"ㄉㄨㄛˋ",pinyin:"duò",wrong:[{z:"ㄉㄨˋ",p:"dù"},{z:"ㄊㄨㄛˋ",p:"tuò"}],note:"「踱步」的「踱」讀ㄉㄨㄛˋ，慢步行走。",deep:"1. 注音比較\n踱：ㄉㄨㄛˋ（四聲）＝踱步、踱來踱去；ㄉㄨˋ＝誤讀（受「度」影響）；ㄊㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n踱：形聲字，「足」＋「度」（聲），慢步行走→踱步。從「度」得聲卻讀ㄉㄨㄛˋ。"},
  {id:"p285",grade:8,word:"堆疊",target:"疊",zhuyin:"ㄉㄧㄝˊ",pinyin:"dié",wrong:[{z:"ㄊㄚˇ",p:"tǎ"},{z:"ㄉㄧㄝˋ",p:"diè"}],note:"「堆疊」「重疊」的「疊」讀ㄉㄧㄝˊ。",deep:"1. 注音比較\n疊：ㄉㄧㄝˊ（二聲）＝堆疊、重疊、疊字；ㄊㄚˇ＝無此音（是「塔」的讀音）；ㄉㄧㄝˋ＝誤讀\n2. 國字拆解與造字原因\n疊：會意字，物品一層層堆起（畾＝堆積）→重疊、摺疊。讀二聲ㄉㄧㄝˊ。"},
  {id:"p286",grade:8,word:"要塞",target:"塞",zhuyin:"ㄙㄞˋ",pinyin:"sài",wrong:[{z:"ㄙㄞ",p:"sāi"},{z:"ㄙㄜˋ",p:"sè"}],note:"「要塞」「邊塞」讀ㄙㄞˋ；「瓶塞」讀ㄙㄞ；「閉塞」讀ㄙㄜˋ。",deep:"1. 注音比較\n塞：ㄙㄞˋ（四聲）＝要塞、邊塞、塞外；ㄙㄞ（一聲）＝瓶塞、塞住；ㄙㄜˋ（四聲）＝閉塞、阻塞\n2. 國字拆解與造字原因\n塞：屋內填土堵塞之形。堵住讀ㄙㄞ；邊防要地（堵住敵人之處）讀ㄙㄞˋ；文言的堵塞不通讀ㄙㄜˋ。一字三音常考。"},
  {id:"p287",grade:8,word:"胚胎",target:"胚",zhuyin:"ㄆㄟ",pinyin:"pēi",wrong:[{z:"ㄅㄟ",p:"bēi"},{z:"ㄆㄧ",p:"pī"}],note:"「胚胎」的「胚」讀ㄆㄟ。",deep:"1. 注音比較\n胚：ㄆㄟ（一聲）＝胚胎、胚芽；ㄅㄟ＝誤讀（受「杯」影響）；ㄆㄧ＝無此音（是「批」的讀音）\n2. 國字拆解與造字原因\n胚：形聲字，「月（肉）」＋「丕」（聲），生物發育初期的雛體→胚胎、胚芽。讀ㄆㄟ。"},
  {id:"p288",grade:8,word:"眺望",target:"眺",zhuyin:"ㄊㄧㄠˋ",pinyin:"tiào",wrong:[{z:"ㄓㄠˋ",p:"zhào"},{z:"ㄊㄧㄠ",p:"tiāo"}],note:"「眺望」「遠眺」的「眺」讀ㄊㄧㄠˋ。",deep:"1. 注音比較\n眺：ㄊㄧㄠˋ（四聲）＝眺望、遠眺；ㄓㄠˋ＝無此音（是「兆」的讀音）；ㄊㄧㄠ＝無此音（是「挑」的讀音）\n2. 國字拆解與造字原因\n眺：形聲字，「目」＋「兆」（聲），從高處向遠方看→眺望。讀ㄊㄧㄠˋ，與「跳」同音。"},
  {id:"p289",grade:8,word:"揣測",target:"揣",zhuyin:"ㄔㄨㄞˇ",pinyin:"chuǎi",wrong:[{z:"ㄔㄨㄢˇ",p:"chuǎn"},{z:"ㄉㄨㄢ",p:"duān"}],note:"「揣測」「揣摩」的「揣」讀ㄔㄨㄞˇ。",deep:"1. 注音比較\n揣：ㄔㄨㄞˇ（三聲）＝揣測、揣摩；ㄔㄨㄢˇ＝無此音（是「喘」的讀音）；ㄉㄨㄢ＝無此音（是「端」的讀音）\n2. 國字拆解與造字原因\n揣：形聲字，「扌」＋「耑」（聲），本義是估量——用手掂量→揣測、揣摩（用心推想）。讀ㄔㄨㄞˇ。"},
  {id:"p290",grade:8,word:"隕石",target:"隕",zhuyin:"ㄩㄣˇ",pinyin:"yǔn",wrong:[{z:"ㄩㄣˊ",p:"yún"},{z:"ㄩㄢˊ",p:"yuán"}],note:"「隕石」「隕落」的「隕」讀ㄩㄣˇ。",deep:"1. 注音比較\n隕：ㄩㄣˇ（三聲）＝隕石、隕落；ㄩㄣˊ＝誤讀（受「雲」影響）；ㄩㄢˊ＝無此音（是「員」的讀音）\n2. 國字拆解與造字原因\n隕：形聲字，「阝（阜，高處）」＋「員」（聲），從高處墜落→隕落、隕石（天上掉下的石頭）。讀ㄩㄣˇ。"},
  {id:"p291",grade:9,word:"作坊",target:"坊",zhuyin:"ㄈㄤˊ",pinyin:"fáng",wrong:[{z:"ㄈㄤ",p:"fāng"},{z:"ㄈㄤˇ",p:"fǎng"}],note:"「作坊」「磨坊」讀ㄈㄤˊ；「牌坊」「街坊」讀ㄈㄤ。",deep:"1. 注音比較\n坊：ㄈㄤˊ（二聲）＝作坊、磨坊、染坊；ㄈㄤ（一聲）＝牌坊、街坊、坊間；ㄈㄤˇ＝無此音（是「仿」的讀音）\n2. 國字拆解與造字原因\n坊：形聲字，「土」＋「方」（聲），本義是里巷（街坊，ㄈㄤ）；手工作業的場所讀ㄈㄤˊ（作坊、磨坊）。記法：街區一聲、工場二聲。"},
  {id:"p292",grade:9,word:"栓塞",target:"塞",zhuyin:"ㄙㄜˋ",pinyin:"sè",wrong:[{z:"ㄙㄞ",p:"sāi"},{z:"ㄙㄞˋ",p:"sài"}],note:"醫學「栓塞」「梗塞」的「塞」讀ㄙㄜˋ。",deep:"1. 注音比較\n塞：ㄙㄜˋ（四聲）＝栓塞、梗塞、閉塞（書面文言）；ㄙㄞ（一聲）＝塞車、塞住；ㄙㄞˋ（四聲）＝要塞\n2. 國字拆解與造字原因\n塞：填堵之義。醫學與書面語的「堵塞不通」讀ㄙㄜˋ（心肌梗塞、栓塞）；口語動作讀ㄙㄞ；邊防要地讀ㄙㄞˋ。"},
  {id:"p293",grade:9,word:"挾持",target:"挾",zhuyin:"ㄒㄧㄝˊ",pinyin:"xié",wrong:[{z:"ㄐㄧㄚˊ",p:"jiá"},{z:"ㄒㄧㄚˊ",p:"xiá"}],note:"「挾持」「要挾」的「挾」讀ㄒㄧㄝˊ。",deep:"1. 注音比較\n挾：ㄒㄧㄝˊ（二聲）＝挾持、要挾、挾怨；ㄐㄧㄚˊ＝舊讀，審訂表不採；ㄒㄧㄚˊ＝無此音（是「狹」的讀音）\n2. 國字拆解與造字原因\n挾：形聲字，「扌」＋「夾」（聲），用胳膊夾住→挾持（用強力控制人）、挾怨（心懷怨恨）。審訂音讀ㄒㄧㄝˊ。"},
  {id:"p294",grade:9,word:"稜角",target:"稜",zhuyin:"ㄌㄥˊ",pinyin:"léng",wrong:[{z:"ㄌㄧㄥˊ",p:"líng"},{z:"ㄌㄥˋ",p:"lèng"}],note:"「稜角」「三稜鏡」的「稜」讀ㄌㄥˊ。",deep:"1. 注音比較\n稜：ㄌㄥˊ（二聲）＝稜角、三稜鏡、模稜兩可；ㄌㄧㄥˊ＝誤讀（受「陵」影響）；ㄌㄥˋ＝無此音\n2. 國字拆解與造字原因\n稜：形聲字，「禾」＋「夌」（聲），物體的邊角條紋→稜角、稜線。讀ㄌㄥˊ。"},
  {id:"p295",grade:9,word:"粗礪",target:"礪",zhuyin:"ㄌㄧˋ",pinyin:"lì",wrong:[{z:"ㄌㄞˋ",p:"lài"},{z:"ㄨㄟˋ",p:"wèi"}],note:"「砥礪」「磨礪」的「礪」讀ㄌㄧˋ，磨刀石。",deep:"1. 注音比較\n礪：ㄌㄧˋ（四聲）＝砥礪、磨礪；ㄌㄞˋ＝無此音（是「賴」的讀音）；ㄨㄟˋ＝無此音\n2. 國字拆解與造字原因\n礪：形聲字，「石」＋「厲」（聲），粗磨刀石→磨練（砥礪品行）。讀ㄌㄧˋ，與「厲」音近意通（「再接再厲」的厲即通礪）。"},
  {id:"p296",grade:9,word:"憎惡",target:"惡",zhuyin:"ㄨˋ",pinyin:"wù",wrong:[{z:"ㄜˋ",p:"è"},{z:"ㄨ",p:"wū"}],note:"「憎惡」「厭惡」（討厭）讀ㄨˋ；「罪惡」讀ㄜˋ；「惡心」讀ㄜˇ。",deep:"1. 注音比較\n惡：ㄨˋ（四聲）＝憎惡、厭惡、深惡痛絕（討厭）；ㄜˋ（四聲）＝罪惡、惡人（壞）；ㄜˇ（三聲）＝惡心\n2. 國字拆解與造字原因\n惡：形聲字，「亞」（聲）＋「心」，心所厭棄。當名詞形容詞「壞」讀ㄜˋ；當動詞「討厭」讀ㄨˋ；「惡心」（想吐）讀ㄜˇ。一字三音常考。"},
  {id:"p297",grade:9,word:"擂臺",target:"擂",zhuyin:"ㄌㄟˊ",pinyin:"léi",wrong:[{z:"ㄌㄟˋ",p:"lèi"},{z:"ㄌㄟˇ",p:"lěi"}],note:"審訂音「擂臺」「打擂」的「擂」讀ㄌㄟˊ。",deep:"1. 注音比較\n擂：ㄌㄟˊ（二聲）＝擂臺、打擂、自吹自擂（審訂音）；ㄌㄟˋ＝俗讀，審訂表不採；ㄌㄟˇ＝無此音\n2. 國字拆解與造字原因\n擂：形聲字，「扌」＋「雷」（聲），敲打（擂鼓）→比武的高臺「擂臺」（敲鼓開賽）。審訂音統讀ㄌㄟˊ。"},
  {id:"p298",grade:9,word:"畜牧",target:"畜",zhuyin:"ㄒㄩˋ",pinyin:"xù",wrong:[{z:"ㄔㄨˋ",p:"chù"},{z:"ㄒㄩ",p:"xū"}],note:"「畜牧」「畜養」（動詞）讀ㄒㄩˋ；「牲畜」「家畜」（名詞）讀ㄔㄨˋ。",deep:"1. 注音比較\n畜：ㄒㄩˋ（四聲）＝畜牧、畜養（動詞：飼養）；ㄔㄨˋ（四聲）＝牲畜、家畜（名詞：動物）；ㄒㄩ＝無此音\n2. 國字拆解與造字原因\n畜：田中積存草料以養牲口。飼養的動作讀ㄒㄩˋ；被養的動物讀ㄔㄨˋ。記法：動詞ㄒㄩˋ、名詞ㄔㄨˋ。"},
  {id:"p299",grade:9,word:"軋戲",target:"軋",zhuyin:"ㄍㄚˊ",pinyin:"gá",wrong:[{z:"ㄧㄚˋ",p:"yà"},{z:"ㄓㄚˊ",p:"zhá"}],note:"「軋戲」「軋車」讀ㄍㄚˊ；「傾軋」讀ㄧㄚˋ。",deep:"1. 注音比較\n軋：ㄍㄚˊ（二聲）＝軋戲、軋車、軋朋友（口語：擠、結交）；ㄧㄚˋ（四聲）＝傾軋、軋棉（碾壓、排擠）；ㄓㄚˊ＝軋鋼（軋輥）\n2. 國字拆解與造字原因\n軋：形聲字，「車」＋「乙」（聲），本義是車輪碾壓（ㄧㄚˋ）；口語「擠、趕場」讀ㄍㄚˊ（軋戲）；工業軋鋼讀ㄓㄚˊ。一字三音。"},
  {id:"p300",grade:9,word:"畏縮",target:"縮",zhuyin:"ㄙㄨㄛ",pinyin:"suō",wrong:[{z:"ㄙㄨˋ",p:"sù"},{z:"ㄕㄨㄛˋ",p:"shuò"}],note:"「畏縮」「縮小」的「縮」讀ㄙㄨㄛ。",deep:"1. 注音比較\n縮：ㄙㄨㄛ（一聲）＝畏縮、縮小、退縮；ㄙㄨˋ＝無此音（是「宿」的讀音）；ㄕㄨㄛˋ＝無此音\n2. 國字拆解與造字原因\n縮：形聲字，「糸」＋「宿」（聲），繩子收緊變短→縮小、退縮。讀ㄙㄨㄛ。"},
  // ---- 2026-08-02 三輪擴充:p301-p450 ----
  {id:"p301",grade:1,word:"三更",target:"更",zhuyin:"ㄍㄥ",pinyin:"gēng",wrong:[{z:"ㄍㄥˋ",p:"gèng"},{z:"ㄍㄥˇ",p:"gěng"}],note:"「三更半夜」「更換」讀ㄍㄥ;「更加」「更好」讀ㄍㄥˋ。",deep:"1. 注音比較\n更：ㄍㄥ（一聲）＝三更半夜、更換、更正；ㄍㄥˋ（四聲）＝更加、更好；ㄍㄥˇ＝無此音（是「梗」的讀音）\n2. 國字拆解與造字原因\n更：形聲字，小篆從「攵」（手持器具）、「丙」（聲），本義是改變、替換→「更換、更正」（ㄍㄥ）；古代夜間輪班報時也是輪「換」，一夜分五更→「三更半夜」（ㄍㄥ）；事情再進一層→「更加」（ㄍㄥˋ）。"},
  {id:"p302",grade:1,word:"首都",target:"都",zhuyin:"ㄉㄨ",pinyin:"dū",wrong:[{z:"ㄉㄡ",p:"dōu"},{z:"ㄉㄨˇ",p:"dǔ"}],note:"「首都」「都市」讀ㄉㄨ;「都是」「全都」讀ㄉㄡ。",deep:"1. 注音比較\n都：ㄉㄨ（一聲）＝首都、都市；ㄉㄡ（一聲）＝都是、全都；ㄉㄨˇ＝無此音（是「賭」的讀音）\n2. 國字拆解與造字原因\n都：形聲字，「者」（聲）＋「阝（邑，城市）」，本義是大城市、君王所在的城→「首都、都市」（ㄉㄨ）；大城聚集了所有的人和物，引申為「全部」→「都是、全都」（ㄉㄡ）。"},
  {id:"p303",grade:1,word:"少年",target:"少",zhuyin:"ㄕㄠˋ",pinyin:"shào",wrong:[{z:"ㄕㄠˇ",p:"shǎo"},{z:"ㄕㄠ",p:"shāo"}],note:"「少年」「少女」讀ㄕㄠˋ;「多少」「減少」讀ㄕㄠˇ。",deep:"1. 注音比較\n少：ㄕㄠˋ（四聲）＝少年、少女；ㄕㄠˇ（三聲）＝多少、減少；ㄕㄠ＝無此音（是「捎」的讀音）\n2. 國字拆解與造字原因\n少：指事字，「小」加一撇，表示比小還細微，本義是數量不多→「多少、減少」（ㄕㄠˇ）；年紀不多、年輕→「少年、少女」（ㄕㄠˋ）。記法：指數量讀三聲，指年紀讀四聲。"},
  {id:"p304",grade:1,word:"相信",target:"相",zhuyin:"ㄒㄧㄤ",pinyin:"xiāng",wrong:[{z:"ㄒㄧㄤˋ",p:"xiàng"},{z:"ㄒㄧㄤˇ",p:"xiǎng"}],note:"「相信」「互相」讀ㄒㄧㄤ;「相片」「相貌」讀ㄒㄧㄤˋ。",deep:"1. 注音比較\n相：ㄒㄧㄤ（一聲）＝相信、互相、相親相愛；ㄒㄧㄤˋ（四聲）＝相片、相貌、首相；ㄒㄧㄤˇ＝無此音（是「想」的讀音）\n2. 國字拆解與造字原因\n相：會意字，「木」＋「目」，用眼睛觀察樹木，本義是察看。彼此對看→「互相、相信」（ㄒㄧㄤ）；看到的外貌→「相貌、相片」（ㄒㄧㄤˋ），輔助君王察事的人→「宰相、首相」（ㄒㄧㄤˋ）。"},
  {id:"p305",grade:1,word:"相簿",target:"相",zhuyin:"ㄒㄧㄤˋ",pinyin:"xiàng",wrong:[{z:"ㄒㄧㄤ",p:"xiāng"},{z:"ㄒㄧㄤˇ",p:"xiǎng"}],note:"「相簿」「照相」讀ㄒㄧㄤˋ;「相親相愛」讀ㄒㄧㄤ。",deep:"1. 注音比較\n相：ㄒㄧㄤˋ（四聲）＝相簿、照相、相貌；ㄒㄧㄤ（一聲）＝相親相愛、互相；ㄒㄧㄤˇ＝無此音（是「想」的讀音）\n2. 國字拆解與造字原因\n相：會意字，「木」＋「目」，用眼睛察看樹木。表「外貌、影像」時讀ㄒㄧㄤˋ→「相簿、照相」；表「彼此、互相」時讀ㄒㄧㄤ→「相親相愛」。記法：看得到的「樣子」讀四聲，兩人之間的「互相」讀一聲。"},
  {id:"p306",grade:2,word:"將來",target:"將",zhuyin:"ㄐㄧㄤ",pinyin:"jiāng",wrong:[{z:"ㄐㄧㄤˋ",p:"jiàng"},{z:"ㄑㄧㄤ",p:"qiāng"}],note:"「將來」「將要」讀ㄐㄧㄤ;「將領」「大將」讀ㄐㄧㄤˋ。",deep:"1. 注音比較\n將：ㄐㄧㄤ（一聲）＝將來、將要、將近；ㄐㄧㄤˋ（四聲）＝將領、大將；ㄑㄧㄤ＝罕用音（《詩經》「將進酒」的請求義）\n2. 國字拆解與造字原因\n將：形聲字，從「寸」（手），本義是扶持、帶領。快要發生（副詞）→「將來、將要」（ㄐㄧㄤ）；帶兵的人→「將領」（ㄐㄧㄤˋ）。"},
  {id:"p307",grade:2,word:"大將",target:"將",zhuyin:"ㄐㄧㄤˋ",pinyin:"jiàng",wrong:[{z:"ㄐㄧㄤ",p:"jiāng"},{z:"ㄑㄧㄤˊ",p:"qiáng"}],note:"「大將」「將軍」讀ㄐㄧㄤˋ;「將近」讀ㄐㄧㄤ。",deep:"1. 注音比較\n將：ㄐㄧㄤˋ（四聲）＝大將、將軍、將士；ㄐㄧㄤ（一聲）＝將近、即將；ㄑㄧㄤˊ＝無此音（是「強」的讀音）\n2. 國字拆解與造字原因\n將：從「寸」（手），本義扶持、帶領。統帥軍隊的人（名詞）讀ㄐㄧㄤˋ；表「快要」的副詞讀ㄐㄧㄤ。記法：官職四聲、副詞一聲。"},
  {id:"p308",grade:2,word:"困難",target:"難",zhuyin:"ㄋㄢˊ",pinyin:"nán",wrong:[{z:"ㄋㄢˋ",p:"nàn"},{z:"ㄋㄢˇ",p:"nǎn"}],note:"「困難」「難題」讀ㄋㄢˊ;「災難」「避難」讀ㄋㄢˋ。",deep:"1. 注音比較\n難：ㄋㄢˊ（二聲）＝困難、難題、難過；ㄋㄢˋ（四聲）＝災難、避難、難民；ㄋㄢˇ＝無此音\n2. 國字拆解與造字原因\n難：形聲字，「隹」（短尾鳥）＋「堇」（聲），本是一種鳥名，假借表「不容易」→「困難」（ㄋㄢˊ）；不容易度過的禍事→「災難」（ㄋㄢˋ）。記法：形容詞二聲、名詞（禍事）四聲。"},
  {id:"p309",grade:2,word:"災難",target:"難",zhuyin:"ㄋㄢˋ",pinyin:"nàn",wrong:[{z:"ㄋㄢˊ",p:"nán"},{z:"ㄋㄚˋ",p:"nà"}],note:"「災難」「難民」讀ㄋㄢˋ;「難過」讀ㄋㄢˊ。",deep:"1. 注音比較\n難：ㄋㄢˋ（四聲）＝災難、難民、遇難；ㄋㄢˊ（二聲）＝難過、困難；ㄋㄚˋ＝無此音（是「納」的讀音）\n2. 國字拆解與造字原因\n難：「隹」＋「堇」（聲），假借表「不容易」。指禍事、劫難（名詞）讀ㄋㄢˋ；指「不容易」（形容詞）讀ㄋㄢˊ。"},
  {id:"p310",grade:2,word:"分開",target:"分",zhuyin:"ㄈㄣ",pinyin:"fēn",wrong:[{z:"ㄈㄣˋ",p:"fèn"},{z:"ㄈㄢ",p:"fān"}],note:"「分開」「分數」讀ㄈㄣ;「本分」「分量」讀ㄈㄣˋ。",deep:"1. 注音比較\n分：ㄈㄣ（一聲）＝分開、分數、十分；ㄈㄣˋ（四聲）＝本分、分量、身分；ㄈㄢ＝無此音（是「翻」的讀音）\n2. 國字拆解與造字原因\n分：會意字，「八」（分開之形）＋「刀」，用刀把東西切開，本義是分開（ㄈㄣ）；分到自己名下的職責、地位→「本分、身分」（ㄈㄣˋ）。記法：動作一聲、名分四聲。"},
  {id:"p311",grade:2,word:"本分",target:"分",zhuyin:"ㄈㄣˋ",pinyin:"fèn",wrong:[{z:"ㄈㄣ",p:"fēn"},{z:"ㄅㄣˇ",p:"běn"}],note:"「本分」「過分」讀ㄈㄣˋ;「分別」讀ㄈㄣ。",deep:"1. 注音比較\n分：ㄈㄣˋ（四聲）＝本分、過分、安分；ㄈㄣ（一聲）＝分別、分開；ㄅㄣˇ＝無此音（是「本」的讀音）\n2. 國字拆解與造字原因\n分：「八」＋「刀」，以刀分物。切開的動作讀ㄈㄣ；每人「分」得的職責、限度讀ㄈㄣˋ（守本分、不過分）。"},
  {id:"p312",grade:2,word:"天空",target:"空",zhuyin:"ㄎㄨㄥ",pinyin:"kōng",wrong:[{z:"ㄎㄨㄥˋ",p:"kòng"},{z:"ㄎㄨㄥˇ",p:"kǒng"}],note:"「天空」「空氣」讀ㄎㄨㄥ;「空地」「空白」讀ㄎㄨㄥˋ。",deep:"1. 注音比較\n空：ㄎㄨㄥ（一聲）＝天空、空氣、空曠；ㄎㄨㄥˋ（四聲）＝空地、空白、有空；ㄎㄨㄥˇ＝無此音（是「恐」的讀音）\n2. 國字拆解與造字原因\n空：形聲字，「穴」（洞）＋「工」（聲），洞穴裡什麼都沒有，本義是空虛→「天空、空氣」（ㄎㄨㄥ）；騰出來沒被占用的→「空地、有空」（ㄎㄨㄥˋ）。"},
  {id:"p313",grade:2,word:"空地",target:"空",zhuyin:"ㄎㄨㄥˋ",pinyin:"kòng",wrong:[{z:"ㄎㄨㄥ",p:"kōng"},{z:"ㄎㄨㄥˇ",p:"kǒng"}],note:"「空地」「空檔」「填空」讀ㄎㄨㄥˋ;「空曠」讀ㄎㄨㄥ。",deep:"1. 注音比較\n空：ㄎㄨㄥˋ（四聲）＝空地、空檔、填空；ㄎㄨㄥ（一聲）＝空曠、天空；ㄎㄨㄥˇ＝無此音\n2. 國字拆解與造字原因\n空：「穴」＋「工」（聲）。指「什麼都沒有」的狀態讀ㄎㄨㄥ；指「騰出、留出的位置或時間」讀ㄎㄨㄥˋ（空位、空檔）。"},
  {id:"p314",grade:2,word:"擔心",target:"擔",zhuyin:"ㄉㄢ",pinyin:"dān",wrong:[{z:"ㄉㄢˋ",p:"dàn"},{z:"ㄊㄢˊ",p:"tán"}],note:"「擔心」「承擔」讀ㄉㄢ;「重擔」「扁擔」讀ㄉㄢˋ。",deep:"1. 注音比較\n擔：ㄉㄢ（一聲）＝擔心、承擔、擔任；ㄉㄢˋ（四聲）＝重擔、扁擔、一擔水；ㄊㄢˊ＝無此音（是「談」的讀音）\n2. 國字拆解與造字原因\n擔：形聲字，「扌」＋「詹」（聲），本義是用肩挑東西（動詞，ㄉㄢ）→引申承受（擔心、承擔）；挑的東西或工具（名詞）讀ㄉㄢˋ（重擔、扁擔）。記法：動詞一聲、名詞四聲。"},
  {id:"p315",grade:2,word:"重擔",target:"擔",zhuyin:"ㄉㄢˋ",pinyin:"dàn",wrong:[{z:"ㄉㄢ",p:"dān"},{z:"ㄓㄨㄥˋ",p:"zhòng"}],note:"「重擔」「一擔水」讀ㄉㄢˋ;「擔任」讀ㄉㄢ。",deep:"1. 注音比較\n擔：ㄉㄢˋ（四聲）＝重擔、一擔水；ㄉㄢ（一聲）＝擔任、擔憂；ㄓㄨㄥˋ＝無此音（是「重」的讀音）\n2. 國字拆解與造字原因\n擔：「扌」＋「詹」（聲），肩挑的動作讀ㄉㄢ；肩上挑的貨物、責任（名詞）讀ㄉㄢˋ，也當量詞（一擔水）。"},
  {id:"p316",grade:2,word:"彈琴",target:"彈",zhuyin:"ㄊㄢˊ",pinyin:"tán",wrong:[{z:"ㄉㄢˋ",p:"dàn"},{z:"ㄊㄢˇ",p:"tǎn"}],note:"「彈琴」「彈跳」讀ㄊㄢˊ;「子彈」「彈藥」讀ㄉㄢˋ。",deep:"1. 注音比較\n彈：ㄊㄢˊ（二聲）＝彈琴、彈跳、彈性；ㄉㄢˋ（四聲）＝子彈、彈藥、炸彈；ㄊㄢˇ＝無此音（是「坦」的讀音）\n2. 國字拆解與造字原因\n彈：形聲字，「弓」＋「單」（聲），本義是用弓發射的小丸（名詞，ㄉㄢˋ）→子彈；用手指撥動、彈射的動作讀ㄊㄢˊ（彈琴、彈跳）。記法：名詞四聲、動詞二聲。"},
  {id:"p317",grade:2,word:"子彈",target:"彈",zhuyin:"ㄉㄢˋ",pinyin:"dàn",wrong:[{z:"ㄊㄢˊ",p:"tán"},{z:"ㄉㄢ",p:"dān"}],note:"「子彈」「飛彈」讀ㄉㄢˋ;「彈鋼琴」讀ㄊㄢˊ。",deep:"1. 注音比較\n彈：ㄉㄢˋ（四聲）＝子彈、飛彈、彈殼；ㄊㄢˊ（二聲）＝彈鋼琴、彈簧；ㄉㄢ＝無此音（是「擔」的讀音）\n2. 國字拆解與造字原因\n彈：「弓」＋「單」（聲），弓上發射的彈丸（名詞）讀ㄉㄢˋ；撥動、跳動的動作讀ㄊㄢˊ。"},
  {id:"p318",grade:3,word:"歌曲",target:"曲",zhuyin:"ㄑㄩˇ",pinyin:"qǔ",wrong:[{z:"ㄑㄩ",p:"qū"},{z:"ㄑㄩˋ",p:"qù"}],note:"「歌曲」「作曲」讀ㄑㄩˇ;「彎曲」「曲折」讀ㄑㄩ。",deep:"1. 注音比較\n曲：ㄑㄩˇ（三聲）＝歌曲、作曲、戲曲；ㄑㄩ（一聲）＝彎曲、曲折、曲線；ㄑㄩˋ＝無此音（是「去」的讀音）\n2. 國字拆解與造字原因\n曲：象形字，像彎曲的器物，本義是彎（ㄑㄩ）；樂音高低轉折如彎曲的線條→「樂曲」（ㄑㄩˇ）。記法：彎的一聲、歌的三聲。"},
  {id:"p319",grade:3,word:"彎曲",target:"曲",zhuyin:"ㄑㄩ",pinyin:"qū",wrong:[{z:"ㄑㄩˇ",p:"qǔ"},{z:"ㄨㄢ",p:"wān"}],note:"「彎曲」「曲解」讀ㄑㄩ;「戲曲」讀ㄑㄩˇ。",deep:"1. 注音比較\n曲：ㄑㄩ（一聲）＝彎曲、曲解、曲線；ㄑㄩˇ（三聲）＝戲曲、歌曲；ㄨㄢ＝無此音（是「彎」的讀音）\n2. 國字拆解與造字原因\n曲：象形字，像彎曲之物。形容彎、不直（含「歪曲事實」的曲解）讀ㄑㄩ；音樂作品讀ㄑㄩˇ。"},
  {id:"p320",grade:3,word:"磨刀",target:"磨",zhuyin:"ㄇㄛˊ",pinyin:"mó",wrong:[{z:"ㄇㄛˋ",p:"mò"},{z:"ㄇㄚˊ",p:"má"}],note:"「磨刀」「磨練」讀ㄇㄛˊ;「石磨」「磨坊」讀ㄇㄛˋ。",deep:"1. 注音比較\n磨：ㄇㄛˊ（二聲）＝磨刀、磨練、折磨；ㄇㄛˋ（四聲）＝石磨、磨坊；ㄇㄚˊ＝無此音（是「麻」的讀音）\n2. 國字拆解與造字原因\n磨：形聲字，「石」＋「麻」（聲），本義是用石頭研磨（動詞，ㄇㄛˊ）；研磨穀物的器具（名詞）讀ㄇㄛˋ（石磨）。記法：動詞二聲、器具四聲。"},
  {id:"p321",grade:3,word:"石磨",target:"磨",zhuyin:"ㄇㄛˋ",pinyin:"mò",wrong:[{z:"ㄇㄛˊ",p:"mó"},{z:"ㄇㄛ",p:"mō"}],note:"「石磨」「磨豆漿的磨」讀ㄇㄛˋ;「折磨」讀ㄇㄛˊ。",deep:"1. 注音比較\n磨：ㄇㄛˋ（四聲）＝石磨、磨坊、推磨；ㄇㄛˊ（二聲）＝折磨、磨墨；ㄇㄛ＝無此音\n2. 國字拆解與造字原因\n磨：「石」＋「麻」（聲）。磨東西的動作讀ㄇㄛˊ；磨穀物的石製器具讀ㄇㄛˋ。"},
  {id:"p322",grade:3,word:"關卡",target:"卡",zhuyin:"ㄑㄧㄚˇ",pinyin:"qiǎ",wrong:[{z:"ㄎㄚˇ",p:"kǎ"},{z:"ㄑㄧㄚˋ",p:"qià"}],note:"「關卡」「卡住」讀ㄑㄧㄚˇ;「卡片」「刷卡」讀ㄎㄚˇ。",deep:"1. 注音比較\n卡：ㄑㄧㄚˇ（三聲）＝關卡、卡住、卡子；ㄎㄚˇ（三聲）＝卡片、刷卡、卡車（外來語音譯）；ㄑㄧㄚˋ＝無此音（是「恰」的讀音）\n2. 國字拆解與造字原因\n卡：會意字，「上」「下」合體，不上不下夾在中間→「卡住、關卡」（ㄑㄧㄚˇ）；音譯外來語 card、car 時讀ㄎㄚˇ（卡片、卡車）。"},
  {id:"p323",grade:3,word:"撒嬌",target:"撒",zhuyin:"ㄙㄚ",pinyin:"sā",wrong:[{z:"ㄙㄚˇ",p:"sǎ"},{z:"ㄕㄚ",p:"shā"}],note:"「撒嬌」「撒手」讀ㄙㄚ;「撒種」「撒鹽」讀ㄙㄚˇ。",deep:"1. 注音比較\n撒：ㄙㄚ（一聲）＝撒嬌、撒手、撒謊；ㄙㄚˇ（三聲）＝撒種、撒鹽；ㄕㄚ＝無此音（是「沙」的讀音）\n2. 國字拆解與造字原因\n撒：形聲字，「扌」＋「散」（聲）。放開、盡量施展讀ㄙㄚ（撒手、撒嬌）；把顆粒狀東西散布出去讀ㄙㄚˇ（撒種）。記法：放開一聲、散布三聲。"},
  {id:"p324",grade:3,word:"掃帚",target:"掃",zhuyin:"ㄙㄠˋ",pinyin:"sào",wrong:[{z:"ㄙㄠˇ",p:"sǎo"},{z:"ㄕㄠˋ",p:"shào"}],note:"「掃帚」讀ㄙㄠˋ;「掃地」「打掃」讀ㄙㄠˇ。",deep:"1. 注音比較\n掃：ㄙㄠˋ（四聲）＝掃帚；ㄙㄠˇ（三聲）＝掃地、打掃、掃描；ㄕㄠˋ＝無此音（是「哨」的讀音）\n2. 國字拆解與造字原因\n掃：會意字，「扌」＋「帚」（掃帚），手持帚清除塵土。清掃的動作讀ㄙㄠˇ；只有器具「掃帚」一詞讀ㄙㄠˋ。"},
  {id:"p325",grade:3,word:"悶熱",target:"悶",zhuyin:"ㄇㄣ",pinyin:"mēn",wrong:[{z:"ㄇㄣˋ",p:"mèn"},{z:"ㄇㄧㄣˇ",p:"mǐn"}],note:"「悶熱」「悶著頭」讀ㄇㄣ;「煩悶」「苦悶」讀ㄇㄣˋ。",deep:"1. 注音比較\n悶：ㄇㄣ（一聲）＝悶熱、悶著頭、悶不吭聲；ㄇㄣˋ（四聲）＝煩悶、苦悶、解悶；ㄇㄧㄣˇ＝無此音（是「憫」的讀音）\n2. 國字拆解與造字原因\n悶：會意兼形聲，「心」被關在「門」內，心情鬱塞。空氣不流通、不出聲讀ㄇㄣ（悶熱）；心中鬱悶的情緒讀ㄇㄣˋ（苦悶）。記法：外在環境一聲、內心情緒四聲。"},
  {id:"p326",grade:3,word:"調皮",target:"調",zhuyin:"ㄊㄧㄠˊ",pinyin:"tiáo",wrong:[{z:"ㄉㄧㄠˋ",p:"diào"},{z:"ㄊㄧㄠˋ",p:"tiào"}],note:"「調皮」「調整」讀ㄊㄧㄠˊ;「調查」「聲調」讀ㄉㄧㄠˋ。",deep:"1. 注音比較\n調：ㄊㄧㄠˊ（二聲）＝調皮、調整、調味；ㄉㄧㄠˋ（四聲）＝調查、聲調、調動；ㄊㄧㄠˋ＝無此音（是「跳」的讀音）\n2. 國字拆解與造字原因\n調：形聲字，「言」＋「周」（聲），本義是和諧——使之和諧的動作讀ㄊㄧㄠˊ（調整、調和）；轉換、考核讀ㄉㄧㄠˋ（調動、調查），聲音的高低也叫調（聲調）。"},
  {id:"p327",grade:3,word:"勞累",target:"累",zhuyin:"ㄌㄟˋ",pinyin:"lèi",wrong:[{z:"ㄌㄟˇ",p:"lěi"},{z:"ㄌㄟˊ",p:"léi"}],note:"「勞累」「疲累」讀ㄌㄟˋ;「累積」讀ㄌㄟˇ;「果實累累」讀ㄌㄟˊ。",deep:"1. 注音比較\n累：ㄌㄟˋ（四聲）＝勞累、疲累；ㄌㄟˇ（三聲）＝累積、連累；ㄌㄟˊ（二聲）＝果實累累\n2. 國字拆解與造字原因\n累：從「糸」（絲繩），本義是繩索捆綁、串連→堆疊串連讀ㄌㄟˇ（累積）；被事情捆住而疲乏讀ㄌㄟˋ（勞累）；果實成串下垂讀ㄌㄟˊ（累累）。"},
  {id:"p328",grade:3,word:"累積",target:"累",zhuyin:"ㄌㄟˇ",pinyin:"lěi",wrong:[{z:"ㄌㄟˋ",p:"lèi"},{z:"ㄌㄟˊ",p:"léi"}],note:"「累積」「積累」「日積月累」讀ㄌㄟˇ。",deep:"1. 注音比較\n累：ㄌㄟˇ（三聲）＝累積、積累、日積月累、連累；ㄌㄟˋ（四聲）＝累壞了；ㄌㄟˊ（二聲）＝碩果累累\n2. 國字拆解與造字原因\n累：從「糸」，繩索串連之義。一層層堆疊讀ㄌㄟˇ；疲倦讀ㄌㄟˋ。「日積月累」是堆疊義，讀ㄌㄟˇ。"},
  {id:"p329",grade:3,word:"樹蔭",target:"蔭",zhuyin:"ㄧㄣˋ",pinyin:"yìn",wrong:[{z:"ㄧㄣ",p:"yīn"},{z:"ㄧㄣˊ",p:"yín"}],note:"審訂音「蔭」一律讀ㄧㄣˋ,如「樹蔭」「庇蔭」,常被誤讀成ㄧㄣ。",deep:"1. 注音比較\n蔭：ㄧㄣˋ（四聲）＝樹蔭、庇蔭、綠樹成蔭（審訂音統讀）；ㄧㄣ＝舊讀，審訂表不採；ㄧㄣˊ＝無此音（是「銀」的讀音）\n2. 國字拆解與造字原因\n蔭：形聲字，「艹」＋「陰」（聲），樹下背光的影子，引申為遮蔽、庇護。教育部審訂音一律讀ㄧㄣˋ，「樹蔭」「林蔭大道」都不再讀一聲。"},
  {id:"p330",grade:3,word:"彷彿",target:"彿",zhuyin:"ㄈㄨˊ",pinyin:"fú",wrong:[{z:"ㄈㄛˊ",p:"fó"},{z:"ㄈㄨˇ",p:"fǔ"}],note:"「彷彿」讀ㄈㄤˇ ㄈㄨˊ。",deep:"1. 注音比較\n彿：ㄈㄨˊ（二聲）＝彷彿；ㄈㄛˊ＝無此音（是「佛」的讀音）；ㄈㄨˇ＝無此音（是「府」的讀音）\n2. 國字拆解與造字原因\n彿：形聲字，「彳」（行走）＋「弗」（聲），「彷彿」是連綿詞，形容似有若無、好像。注意「彷彿」（ㄈㄤˇ ㄈㄨˊ）與「佛」（ㄈㄛˊ）字形相近、讀音不同。"},
  {id:"p331",grade:4,word:"亞軍",target:"亞",zhuyin:"ㄧㄚˇ",pinyin:"yǎ",wrong:[{z:"ㄧㄚˋ",p:"yà"},{z:"ㄧㄚ",p:"yā"}],note:"審訂音「亞」讀ㄧㄚˇ,如「亞軍」「亞洲」,常被誤讀成ㄧㄚˋ。",deep:"1. 注音比較\n亞：ㄧㄚˇ（三聲）＝亞軍、亞洲、亞熱帶（審訂音）；ㄧㄚˋ＝俗讀，審訂表不採；ㄧㄚ＝無此音（是「壓」的讀音）\n2. 國字拆解與造字原因\n亞：象形字，像古代建築的方形基座，本義是次一等→亞軍（第二名）、亞熱帶（次於熱帶）。台灣審訂音讀ㄧㄚˇ。"},
  {id:"p332",grade:4,word:"檔案",target:"檔",zhuyin:"ㄉㄤˇ",pinyin:"dǎng",wrong:[{z:"ㄉㄤˋ",p:"dàng"},{z:"ㄉㄤ",p:"dāng"}],note:"審訂音「檔」讀ㄉㄤˇ,如「檔案」「檔次」,常被誤讀成ㄉㄤˋ。",deep:"1. 注音比較\n檔：ㄉㄤˇ（三聲）＝檔案、檔次、空檔（審訂音）；ㄉㄤˋ＝俗讀，審訂表不採；ㄉㄤ＝無此音\n2. 國字拆解與造字原因\n檔：形聲字，「木」＋「當」（聲），本義是木櫃的框格，存放文書之處→檔案。審訂音讀三聲ㄉㄤˇ。"},
  {id:"p333",grade:4,word:"柵欄",target:"柵",zhuyin:"ㄓㄚˋ",pinyin:"zhà",wrong:[{z:"ㄕㄢ",p:"shān"},{z:"ㄘㄜˋ",p:"cè"}],note:"「柵欄」「木柵」的「柵」讀ㄓㄚˋ。",deep:"1. 注音比較\n柵：ㄓㄚˋ（四聲）＝柵欄、木柵；ㄕㄢ＝無此音（柵極為電子學譯名）；ㄘㄜˋ＝無此音（是「冊」的讀音）\n2. 國字拆解與造字原因\n柵：會意兼形聲，「木」＋「冊」（竹簡編排之形），木條像竹簡一樣排列成的圍欄→柵欄。"},
  {id:"p334",grade:4,word:"嫉妒",target:"嫉",zhuyin:"ㄐㄧˊ",pinyin:"jí",wrong:[{z:"ㄐㄧˋ",p:"jì"},{z:"ㄑㄧˊ",p:"qí"}],note:"「嫉妒」「嫉惡如仇」的「嫉」讀ㄐㄧˊ,常被誤讀成ㄐㄧˋ。",deep:"1. 注音比較\n嫉：ㄐㄧˊ（二聲）＝嫉妒、嫉惡如仇；ㄐㄧˋ＝誤讀（受「忌」影響）；ㄑㄧˊ＝無此音\n2. 國字拆解與造字原因\n嫉：形聲字，「女」＋「疾」（聲），因別人比自己好而心裡難受。與「疾」同音讀ㄐㄧˊ，別受同義詞「忌妒」影響誤讀成ㄐㄧˋ。"},
  {id:"p335",grade:4,word:"侮辱",target:"侮",zhuyin:"ㄨˇ",pinyin:"wǔ",wrong:[{z:"ㄨˊ",p:"wú"},{z:"ㄇㄟˇ",p:"měi"}],note:"「侮辱」「欺侮」的「侮」讀ㄨˇ。",deep:"1. 注音比較\n侮：ㄨˇ（三聲）＝侮辱、欺侮；ㄨˊ＝無此音（是「無」的讀音）；ㄇㄟˇ＝無此音（受「每」影響的誤讀）\n2. 國字拆解與造字原因\n侮：形聲字，「亻」＋「每」（聲），輕慢、欺凌他人→侮辱。從「每」得聲但讀ㄨˇ，是形聲字聲符變化的例子。"},
  {id:"p336",grade:4,word:"誣陷",target:"誣",zhuyin:"ㄨ",pinyin:"wū",wrong:[{z:"ㄨˊ",p:"wú"},{z:"ㄨˇ",p:"wǔ"}],note:"「誣陷」「誣賴」的「誣」讀ㄨ。",deep:"1. 注音比較\n誣：ㄨ（一聲）＝誣陷、誣賴、誣告；ㄨˊ＝誤讀（受「巫」影響）；ㄨˇ＝無此音（是「侮」的讀音）\n2. 國字拆解與造字原因\n誣：形聲字，「言」＋「巫」（聲），用言語捏造事實冤枉人→誣陷。讀一聲ㄨ。"},
  {id:"p337",grade:4,word:"噩耗",target:"噩",zhuyin:"ㄜˋ",pinyin:"è",wrong:[{z:"ㄋㄜˋ",p:"nè"},{z:"ㄏㄠˋ",p:"hào"}],note:"「噩耗」「噩夢」的「噩」讀ㄜˋ。",deep:"1. 注音比較\n噩：ㄜˋ（四聲）＝噩耗、噩夢；ㄋㄜˋ＝無此音；ㄏㄠˋ＝無此音（是「耗」的讀音）\n2. 國字拆解與造字原因\n噩：會意字，多個「口」圍著「王」形，象徵驚愕喧嘩，本義是驚人的、不祥的→噩耗（壞消息）、噩夢。與「惡」（ㄜˋ）同音。"},
  {id:"p338",grade:4,word:"酗酒",target:"酗",zhuyin:"ㄒㄩˋ",pinyin:"xù",wrong:[{z:"ㄒㄩㄥ",p:"xiōng"},{z:"ㄑㄩˋ",p:"qù"}],note:"「酗酒」的「酗」讀ㄒㄩˋ,常被誤讀成ㄒㄩㄥ。",deep:"1. 注音比較\n酗：ㄒㄩˋ（四聲）＝酗酒；ㄒㄩㄥ＝誤讀（受「凶」影響）；ㄑㄩˋ＝無此音\n2. 國字拆解與造字原因\n酗：形聲字，「酉」（酒罈）＋「凶」（聲），喝酒過量而撒野→酗酒。從「凶」得聲卻讀ㄒㄩˋ，是常考的誤讀字。"},
  {id:"p339",grade:4,word:"徘徊",target:"徊",zhuyin:"ㄏㄨㄞˊ",pinyin:"huái",wrong:[{z:"ㄏㄨㄟˊ",p:"huí"},{z:"ㄏㄨㄞˋ",p:"huài"}],note:"「徘徊」讀ㄆㄞˊ ㄏㄨㄞˊ,「徊」常被誤讀成ㄏㄨㄟˊ。",deep:"1. 注音比較\n徊：ㄏㄨㄞˊ（二聲）＝徘徊；ㄏㄨㄟˊ＝誤讀（受「回」影響）；ㄏㄨㄞˋ＝無此音（是「壞」的讀音）\n2. 國字拆解與造字原因\n徊：形聲字，「彳」（行走）＋「回」（聲），「徘徊」是連綿詞：來回走動、猶豫不前。「徊」讀ㄏㄨㄞˊ不讀ㄏㄨㄟˊ。"},
  {id:"p340",grade:4,word:"蜿蜒",target:"蜿",zhuyin:"ㄨㄢ",pinyin:"wān",wrong:[{z:"ㄨㄢˇ",p:"wǎn"},{z:"ㄩㄢ",p:"yuān"}],note:"「蜿蜒」讀ㄨㄢ ㄧㄢˊ,山路曲折延伸的樣子。",deep:"1. 注音比較\n蜿：ㄨㄢ（一聲）＝蜿蜒；ㄨㄢˇ＝誤讀（受「宛」影響）；ㄩㄢ＝無此音（是「冤」的讀音）\n2. 國字拆解與造字原因\n蜿：形聲字，「虫」＋「宛」（聲），「蜿蜒」形容像蛇一樣彎彎曲曲地延伸（山路蜿蜒）。讀一聲ㄨㄢ。"},
  {id:"p341",grade:4,word:"骯髒",target:"骯",zhuyin:"ㄤ",pinyin:"āng",wrong:[{z:"ㄎㄤ",p:"kāng"},{z:"ㄤˊ",p:"áng"}],note:"「骯髒」讀ㄤ ㄗㄤ。",deep:"1. 注音比較\n骯：ㄤ（一聲）＝骯髒；ㄎㄤ＝無此音（是「康」的讀音）；ㄤˊ＝無此音（是「昂」的讀音）\n2. 國字拆解與造字原因\n骯：形聲字，「骨」＋「亢」（聲），「骯髒」（ㄤ ㄗㄤ）是連綿詞，形容汙穢不潔。"},
  {id:"p342",grade:4,word:"花蕾",target:"蕾",zhuyin:"ㄌㄟˇ",pinyin:"lěi",wrong:[{z:"ㄌㄟˊ",p:"léi"},{z:"ㄌㄟˋ",p:"lèi"}],note:"「花蕾」「蓓蕾」的「蕾」讀ㄌㄟˇ。",deep:"1. 注音比較\n蕾：ㄌㄟˇ（三聲）＝花蕾、蓓蕾、芭蕾；ㄌㄟˊ＝無此音（是「雷」的讀音）；ㄌㄟˋ＝無此音（是「累」的讀音）\n2. 國字拆解與造字原因\n蕾：形聲字，「艹」＋「雷」（聲），含苞未開的花。從「雷」得聲但讀三聲ㄌㄟˇ。"},
  {id:"p343",grade:5,word:"給予",target:"給",zhuyin:"ㄐㄧˇ",pinyin:"jǐ",wrong:[{z:"ㄍㄟˇ",p:"gěi"},{z:"ㄐㄧˋ",p:"jì"}],note:"「給予」「補給」「供給」讀ㄐㄧˇ;「給你」讀ㄍㄟˇ。",deep:"1. 注音比較\n給：ㄐㄧˇ（三聲）＝給予、補給、供給、自給自足；ㄍㄟˇ（三聲）＝給你、送給（口語）；ㄐㄧˋ＝無此音（是「寄」的讀音）\n2. 國字拆解與造字原因\n給：形聲字，「糸」＋「合」（聲），本義是豐足、供應→書面語「給予、供給」讀ㄐㄧˇ；口語交付東西讀ㄍㄟˇ。記法：書面ㄐㄧˇ、口語ㄍㄟˇ。"},
  {id:"p344",grade:5,word:"提供",target:"供",zhuyin:"ㄍㄨㄥ",pinyin:"gōng",wrong:[{z:"ㄍㄨㄥˋ",p:"gòng"},{z:"ㄍㄨㄥˇ",p:"gǒng"}],note:"「提供」「供應」讀ㄍㄨㄥ;「供品」「口供」讀ㄍㄨㄥˋ。",deep:"1. 注音比較\n供：ㄍㄨㄥ（一聲）＝提供、供應、供不應求；ㄍㄨㄥˋ（四聲）＝供品、口供、供奉；ㄍㄨㄥˇ＝無此音（是「拱」的讀音）\n2. 國字拆解與造字原因\n供：形聲字，「亻」＋「共」（聲），本義是安排、供給（ㄍㄨㄥ）；擺設祭品敬奉、陳述案情讀ㄍㄨㄥˋ（供奉、招供）。"},
  {id:"p345",grade:5,word:"供品",target:"供",zhuyin:"ㄍㄨㄥˋ",pinyin:"gòng",wrong:[{z:"ㄍㄨㄥ",p:"gōng"},{z:"ㄍㄨㄥˇ",p:"gǒng"}],note:"「供品」「供奉」「招供」讀ㄍㄨㄥˋ;「供給」讀ㄍㄨㄥ。",deep:"1. 注音比較\n供：ㄍㄨㄥˋ（四聲）＝供品、供奉、招供、口供；ㄍㄨㄥ（一聲）＝供給、供應；ㄍㄨㄥˇ＝無此音\n2. 國字拆解與造字原因\n供：「亻」＋「共」（聲）。日常供應讀ㄍㄨㄥ；與祭祀、審訊有關讀ㄍㄨㄥˋ。記法：拜拜與問案四聲。"},
  {id:"p346",grade:5,word:"削鉛筆",target:"削",zhuyin:"ㄒㄧㄠ",pinyin:"xiāo",wrong:[{z:"ㄒㄩㄝˋ",p:"xuè"},{z:"ㄒㄧㄠˋ",p:"xiào"}],note:"口語「削鉛筆」「削皮」讀ㄒㄧㄠ;書面「剝削」「削減」讀ㄒㄩㄝˋ。",deep:"1. 注音比較\n削：ㄒㄧㄠ（一聲）＝削鉛筆、削皮（口語）；ㄒㄩㄝˋ（四聲）＝剝削、削減、瘦削（書面）；ㄒㄧㄠˋ＝無此音\n2. 國字拆解與造字原因\n削：形聲字，「刂」（刀）＋「肖」（聲），用刀斜著去掉外層。口語具體動作讀ㄒㄧㄠ（削蘋果）；書面抽象義讀ㄒㄩㄝˋ（剝削、削弱）。"},
  {id:"p347",grade:5,word:"剝削",target:"削",zhuyin:"ㄒㄩㄝˋ",pinyin:"xuè",wrong:[{z:"ㄒㄧㄠ",p:"xiāo"},{z:"ㄒㄩㄝ",p:"xuē"}],note:"「剝削」「削弱」讀ㄒㄩㄝˋ;「削蘋果」讀ㄒㄧㄠ。",deep:"1. 注音比較\n削：ㄒㄩㄝˋ（四聲）＝剝削、削弱、削價；ㄒㄧㄠ（一聲）＝削果皮；ㄒㄩㄝ＝無此音\n2. 國字拆解與造字原因\n削：「刂」＋「肖」（聲）。抽象的減損、壓榨讀ㄒㄩㄝˋ；動手削東西讀ㄒㄧㄠ。記法：書面文言四聲、口語動作一聲。"},
  {id:"p348",grade:5,word:"月暈",target:"暈",zhuyin:"ㄩㄣˋ",pinyin:"yùn",wrong:[{z:"ㄩㄣ",p:"yūn"},{z:"ㄏㄨㄣ",p:"hūn"}],note:"「月暈」「暈染」「燈暈」讀ㄩㄣˋ;「頭暈」「暈倒」讀ㄩㄣ。",deep:"1. 注音比較\n暈：ㄩㄣˋ（四聲）＝月暈、暈染、燈暈；ㄩㄣ（一聲）＝頭暈、暈倒、暈車；ㄏㄨㄣ＝無此音（是「昏」的讀音）\n2. 國字拆解與造字原因\n暈：形聲字，「日」＋「軍」（聲），本義是日月周圍的光圈（ㄩㄣˋ，月暈）；頭腦昏眩像被光圈罩住讀ㄩㄣ（頭暈）。記法：光圈名詞四聲、昏眩一聲。"},
  {id:"p349",grade:5,word:"豬圈",target:"圈",zhuyin:"ㄐㄩㄢˋ",pinyin:"juàn",wrong:[{z:"ㄑㄩㄢ",p:"quān"},{z:"ㄐㄩㄢ",p:"juān"}],note:"「豬圈」「羊圈」讀ㄐㄩㄢˋ;「圓圈」「圈套」讀ㄑㄩㄢ。",deep:"1. 注音比較\n圈：ㄐㄩㄢˋ（四聲）＝豬圈、羊圈；ㄑㄩㄢ（一聲）＝圓圈、圈套、生活圈；ㄐㄩㄢ＝無此音\n2. 國字拆解與造字原因\n圈：形聲字，「囗」（圍）＋「卷」（聲），圍起來的範圍。畫的環形讀ㄑㄩㄢ；關牲畜的欄舍讀ㄐㄩㄢˋ（豬圈）。"},
  {id:"p350",grade:5,word:"校對",target:"校",zhuyin:"ㄐㄧㄠˋ",pinyin:"jiào",wrong:[{z:"ㄒㄧㄠˋ",p:"xiào"},{z:"ㄐㄧㄠˇ",p:"jiǎo"}],note:"「校對」「校正」讀ㄐㄧㄠˋ;「學校」「校園」讀ㄒㄧㄠˋ。",deep:"1. 注音比較\n校：ㄐㄧㄠˋ（四聲）＝校對、校正、校稿；ㄒㄧㄠˋ（四聲）＝學校、校園、校長；ㄐㄧㄠˇ＝無此音（是「腳」的讀音）\n2. 國字拆解與造字原因\n校：形聲字，「木」＋「交」（聲），本義是木囚具，引申為核對、比較→校對（ㄐㄧㄠˋ）；教學的場所讀ㄒㄧㄠˋ（學校）。"},
  {id:"p351",grade:5,word:"人質",target:"質",zhuyin:"ㄓˋ",pinyin:"zhì",wrong:[{z:"ㄓˊ",p:"zhí"},{z:"ㄓˇ",p:"zhǐ"}],note:"「人質」「質押」讀ㄓˋ;「品質」「本質」讀ㄓˊ。",deep:"1. 注音比較\n質：ㄓˋ（四聲）＝人質、質押、質疑；ㄓˊ（二聲）＝品質、本質、性質；ㄓˇ＝無此音（是「紙」的讀音）\n2. 國字拆解與造字原因\n質：形聲字，「貝」（財物）＋「斦」（聲），本義是抵押品→人質、質押讀ㄓˋ；事物的本體、底子讀ㄓˊ（本質、品質）。"},
  {id:"p352",grade:5,word:"論語",target:"論",zhuyin:"ㄌㄨㄣˊ",pinyin:"lún",wrong:[{z:"ㄌㄨㄣˋ",p:"lùn"},{z:"ㄌㄨㄣˇ",p:"lǔn"}],note:"《論語》的「論」讀ㄌㄨㄣˊ;「討論」「言論」讀ㄌㄨㄣˋ。",deep:"1. 注音比較\n論：ㄌㄨㄣˊ（二聲）＝《論語》；ㄌㄨㄣˋ（四聲）＝討論、言論、理論；ㄌㄨㄣˇ＝無此音\n2. 國字拆解與造字原因\n論：形聲字，「言」＋「侖」（聲，條理），有條理地說→討論（ㄌㄨㄣˋ）。《論語》是「編纂論次孔子之語」，書名讀ㄌㄨㄣˊ，是特殊讀法。"},
  {id:"p353",grade:5,word:"屏息",target:"屏",zhuyin:"ㄅㄧㄥˇ",pinyin:"bǐng",wrong:[{z:"ㄆㄧㄥˊ",p:"píng"},{z:"ㄅㄧㄥˋ",p:"bìng"}],note:"「屏息」「屏氣」「屏除」讀ㄅㄧㄥˇ;「屏風」「屏東」讀ㄆㄧㄥˊ。",deep:"1. 注音比較\n屏：ㄅㄧㄥˇ（三聲）＝屏息、屏氣、屏除；ㄆㄧㄥˊ（二聲）＝屏風、屏障、屏東；ㄅㄧㄥˋ＝無此音\n2. 國字拆解與造字原因\n屏：從「尸」（遮蔽）＋「并」（聲），本義是遮擋的牆（屏風，ㄆㄧㄥˊ）；把氣「擋住」不呼出→屏息（ㄅㄧㄥˇ）。記法：遮蔽物二聲、憋住排除三聲。"},
  {id:"p354",grade:5,word:"木訥",target:"訥",zhuyin:"ㄋㄚˋ",pinyin:"nà",wrong:[{z:"ㄋㄜˋ",p:"nè"},{z:"ㄋㄟˋ",p:"nèi"}],note:"審訂音「木訥」的「訥」讀ㄋㄚˋ,不善言辭之意。",deep:"1. 注音比較\n訥：ㄋㄚˋ（四聲）＝木訥（審訂音）；ㄋㄜˋ＝俗讀，審訂表不採；ㄋㄟˋ＝無此音（是「內」的讀音）\n2. 國字拆解與造字原因\n訥：形聲字，「言」＋「內」（聲），話悶在「內」說不出來→言語遲鈍（木訥）。《論語》「君子欲訥於言而敏於行」。審訂音讀ㄋㄚˋ。"},
  {id:"p355",grade:5,word:"拘泥",target:"泥",zhuyin:"ㄋㄧˋ",pinyin:"nì",wrong:[{z:"ㄋㄧˊ",p:"ní"},{z:"ㄋㄧˇ",p:"nǐ"}],note:"「拘泥」(固執)讀ㄋㄧˋ;「泥土」「泥巴」讀ㄋㄧˊ。",deep:"1. 注音比較\n泥：ㄋㄧˋ（四聲）＝拘泥、泥古不化；ㄋㄧˊ（二聲）＝泥土、泥巴；ㄋㄧˇ＝無此音（是「你」的讀音）\n2. 國字拆解與造字原因\n泥：形聲字，「氵」＋「尼」（聲），本義是水和土的泥漿（ㄋㄧˊ）；像陷在泥中不知變通讀ㄋㄧˋ（拘泥）。記法：名詞二聲、固執義四聲。"},
  {id:"p356",grade:5,word:"嗚咽",target:"咽",zhuyin:"ㄧㄝˋ",pinyin:"yè",wrong:[{z:"ㄧㄢ",p:"yān"},{z:"ㄧㄢˋ",p:"yàn"}],note:"「嗚咽」「哽咽」讀ㄧㄝˋ;「咽喉」讀ㄧㄢ。",deep:"1. 注音比較\n咽：ㄧㄝˋ（四聲）＝嗚咽、哽咽；ㄧㄢ（一聲）＝咽喉；ㄧㄢˋ＝同「嚥」（吞嚥）\n2. 國字拆解與造字原因\n咽：形聲字，「口」＋「因」（聲），本義是喉嚨（ㄧㄢ，咽喉）；哭聲堵在喉嚨→嗚咽（ㄧㄝˋ）；吞下讀ㄧㄢˋ。一字三音依部位、哭聲、吞嚥區分。"},
  {id:"p357",grade:5,word:"丟三落四",target:"落",zhuyin:"ㄌㄚˋ",pinyin:"là",wrong:[{z:"ㄌㄨㄛˋ",p:"luò"},{z:"ㄌㄠˋ",p:"lào"}],note:"「丟三落四」「落了東西」讀ㄌㄚˋ;「落葉」讀ㄌㄨㄛˋ;「落枕」讀ㄌㄠˋ。",deep:"1. 注音比較\n落：ㄌㄚˋ（四聲）＝丟三落四、落了東西（遺漏）；ㄌㄨㄛˋ（四聲）＝落葉、降落；ㄌㄠˋ（四聲）＝落枕\n2. 國字拆解與造字原因\n落：形聲字，「艹」＋「洛」（聲），本義是草木凋落（ㄌㄨㄛˋ）；口語「遺漏、忘記帶」讀ㄌㄚˋ（落東西）；「落枕、落價」等口語讀ㄌㄠˋ。"},
  {id:"p358",grade:5,word:"落枕",target:"落",zhuyin:"ㄌㄠˋ",pinyin:"lào",wrong:[{z:"ㄌㄨㄛˋ",p:"luò"},{z:"ㄌㄚˋ",p:"là"}],note:"「落枕」讀ㄌㄠˋ;「降落」讀ㄌㄨㄛˋ。",deep:"1. 注音比較\n落：ㄌㄠˋ（四聲）＝落枕；ㄌㄨㄛˋ（四聲）＝降落、落後；ㄌㄚˋ（四聲）＝落下東西（遺漏）\n2. 國字拆解與造字原因\n落：草木凋零為本義。「落枕」（睡姿不當致頸痛）是口語詞，讀ㄌㄠˋ；一般書面義讀ㄌㄨㄛˋ。"},
  {id:"p359",grade:6,word:"拮据",target:"据",zhuyin:"ㄐㄩ",pinyin:"jū",wrong:[{z:"ㄐㄩˋ",p:"jù"},{z:"ㄎㄨˋ",p:"kù"}],note:"「拮据」讀ㄐㄧㄝˊ ㄐㄩ,經濟困窘,「据」常被誤讀成ㄐㄩˋ。",deep:"1. 注音比較\n据：ㄐㄩ（一聲）＝拮据；ㄐㄩˋ＝誤讀（受「據」影響）；ㄎㄨˋ＝無此音\n2. 國字拆解與造字原因\n据：形聲字，「扌」＋「居」（聲），「拮据」（ㄐㄧㄝˊ ㄐㄩ）本指鳥銜草築巢辛勞（《詩經》「予手拮据」），引申為經濟困窘。「据」在此讀一聲，不同於「據」。"},
  {id:"p360",grade:6,word:"會計",target:"會",zhuyin:"ㄎㄨㄞˋ",pinyin:"kuài",wrong:[{z:"ㄏㄨㄟˋ",p:"huì"},{z:"ㄍㄨㄟˋ",p:"guì"}],note:"「會計」的「會」讀ㄎㄨㄞˋ;「開會」「會議」讀ㄏㄨㄟˋ。",deep:"1. 注音比較\n會：ㄎㄨㄞˋ（四聲）＝會計；ㄏㄨㄟˋ（四聲）＝開會、會議、機會；ㄍㄨㄟˋ＝無此音\n2. 國字拆解與造字原因\n會：會意字，像器皿加蓋相合，本義是聚合（開會，ㄏㄨㄟˋ）；總計財物的專業讀ㄎㄨㄞˋ（會計），是古音遺留。"},
  {id:"p361",grade:6,word:"龜裂",target:"龜",zhuyin:"ㄐㄩㄣ",pinyin:"jūn",wrong:[{z:"ㄍㄨㄟ",p:"guī"},{z:"ㄑㄧㄡ",p:"qiū"}],note:"「龜裂」讀ㄐㄩㄣ ㄌㄧㄝˋ;「烏龜」讀ㄍㄨㄟ;「龜茲」讀ㄑㄧㄡ。",deep:"1. 注音比較\n龜：ㄐㄩㄣ（一聲）＝龜裂；ㄍㄨㄟ（一聲）＝烏龜、龜甲；ㄑㄧㄡ（一聲）＝龜茲（古西域國名）\n2. 國字拆解與造字原因\n龜：象形字，像烏龜側面之形（ㄍㄨㄟ）。皮膚、土地裂開如龜甲紋路讀ㄐㄩㄣ（龜裂）；古國名「龜茲」讀ㄑㄧㄡ ㄘˊ。一字三音都要記。"},
  {id:"p362",grade:6,word:"木屐",target:"屐",zhuyin:"ㄐㄧ",pinyin:"jī",wrong:[{z:"ㄐㄧˊ",p:"jí"},{z:"ㄑㄧ",p:"qī"}],note:"「木屐」的「屐」讀ㄐㄧ。",deep:"1. 注音比較\n屐：ㄐㄧ（一聲）＝木屐、屐痕；ㄐㄧˊ＝誤讀；ㄑㄧ＝無此音\n2. 國字拆解與造字原因\n屐：形聲字，「尸」（人）＋「彳」「支」，木底鞋→木屐。讀一聲ㄐㄧ。"},
  {id:"p363",grade:6,word:"熾熱",target:"熾",zhuyin:"ㄔˋ",pinyin:"chì",wrong:[{z:"ㄓˋ",p:"zhì"},{z:"ㄕˋ",p:"shì"}],note:"「熾熱」「熾烈」的「熾」讀ㄔˋ,常被誤讀成ㄓˋ。",deep:"1. 注音比較\n熾：ㄔˋ（四聲）＝熾熱、熾烈；ㄓˋ＝誤讀（受「織」「幟」影響）；ㄕˋ＝無此音\n2. 國字拆解與造字原因\n熾：形聲字，「火」＋「戠」（聲），火勢旺盛→熾熱、熾烈。讀ㄔˋ，與「斥」同音，別受「幟」（ㄓˋ）影響。"},
  {id:"p364",grade:6,word:"蟄伏",target:"蟄",zhuyin:"ㄓˊ",pinyin:"zhí",wrong:[{z:"ㄓㄜˊ",p:"zhé"},{z:"ㄓㄜˋ",p:"zhè"}],note:"審訂音「蟄伏」「驚蟄」的「蟄」讀ㄓˊ。",deep:"1. 注音比較\n蟄：ㄓˊ（二聲）＝蟄伏、驚蟄（審訂音）；ㄓㄜˊ＝俗讀，審訂表不採；ㄓㄜˋ＝無此音\n2. 國字拆解與造字原因\n蟄：形聲字，「執」（聲）＋「虫」，蟲類藏伏土中過冬→蟄伏；節氣「驚蟄」是春雷驚醒冬眠之蟲。審訂音讀ㄓˊ。"},
  {id:"p365",grade:6,word:"匍匐",target:"匐",zhuyin:"ㄈㄨˊ",pinyin:"fú",wrong:[{z:"ㄈㄨˋ",p:"fù"},{z:"ㄅㄨˊ",p:"bú"}],note:"「匍匐前進」讀ㄆㄨˊ ㄈㄨˊ。",deep:"1. 注音比較\n匐：ㄈㄨˊ（二聲）＝匍匐；ㄈㄨˋ＝誤讀；ㄅㄨˊ＝無此音\n2. 國字拆解與造字原因\n匐：形聲字，「勹」（人彎曲形）＋「畐」（聲），「匍匐」（ㄆㄨˊ ㄈㄨˊ）是連綿詞：身體貼地爬行。"},
  {id:"p366",grade:6,word:"婀娜",target:"婀",zhuyin:"ㄜ",pinyin:"ē",wrong:[{z:"ㄚ",p:"ā"},{z:"ㄜˇ",p:"ě"}],note:"「婀娜多姿」讀ㄜ ㄋㄨㄛˇ。",deep:"1. 注音比較\n婀：ㄜ（一聲）＝婀娜多姿；ㄚ＝誤讀；ㄜˇ＝無此音\n2. 國字拆解與造字原因\n婀：形聲字，「女」＋「阿」（聲），「婀娜」（ㄜ ㄋㄨㄛˇ）是連綿詞：女子姿態柔美。"},
  {id:"p367",grade:6,word:"蚌殼",target:"蚌",zhuyin:"ㄅㄤˋ",pinyin:"bàng",wrong:[{z:"ㄈㄥ",p:"fēng"},{z:"ㄅㄥˋ",p:"bèng"}],note:"「蚌殼」「鷸蚌相爭」的「蚌」讀ㄅㄤˋ。",deep:"1. 注音比較\n蚌：ㄅㄤˋ（四聲）＝蚌殼、鷸蚌相爭；ㄈㄥ＝無此音（是「蜂」的讀音）；ㄅㄥˋ＝無此音（是「蹦」的讀音）\n2. 國字拆解與造字原因\n蚌：形聲字，「虫」＋「丰」（聲），雙殼軟體動物，殼內能生珍珠。讀ㄅㄤˋ，與「棒」同音。"},
  {id:"p368",grade:6,word:"水汞",target:"汞",zhuyin:"ㄍㄨㄥˇ",pinyin:"gǒng",wrong:[{z:"ㄍㄨㄥ",p:"gōng"},{z:"ㄏㄨㄥˇ",p:"hǒng"}],note:"「汞」讀ㄍㄨㄥˇ,即水銀。",deep:"1. 注音比較\n汞：ㄍㄨㄥˇ（三聲）＝汞（水銀）、汞中毒；ㄍㄨㄥ＝誤讀；ㄏㄨㄥˇ＝無此音（是「哄」的讀音）\n2. 國字拆解與造字原因\n汞：會意兼形聲，「工」（聲）＋「水」，常溫下呈液態的金屬——「像水的金屬」，即水銀。讀三聲ㄍㄨㄥˇ。"},
  {id:"p369",grade:6,word:"陀螺",target:"陀",zhuyin:"ㄊㄨㄛˊ",pinyin:"tuó",wrong:[{z:"ㄉㄨㄛˋ",p:"duò"},{z:"ㄊㄚ",p:"tā"}],note:"「陀螺」讀ㄊㄨㄛˊ ㄌㄨㄛˊ。",deep:"1. 注音比較\n陀：ㄊㄨㄛˊ（二聲）＝陀螺、佛陀；ㄉㄨㄛˋ＝無此音（是「舵」的讀音）；ㄊㄚ＝無此音（是「它」的讀音）\n2. 國字拆解與造字原因\n陀：形聲字，「阝（阜）」＋「它」（聲），本義是山坡不平，「陀螺」（ㄊㄨㄛˊ ㄌㄨㄛˊ）是旋轉的玩具。"},
  {id:"p370",grade:6,word:"呢絨",target:"呢",zhuyin:"ㄋㄧˊ",pinyin:"ní",wrong:[{z:"ㄋㄜ",p:"ne"},{z:"ㄋㄧˇ",p:"nǐ"}],note:"「呢絨」「呢帽」讀ㄋㄧˊ;語尾助詞「呢」讀輕聲ㄋㄜ。",deep:"1. 注音比較\n呢：ㄋㄧˊ（二聲）＝呢絨、呢帽、毛呢；˙ㄋㄜ（輕聲）＝好呢、怎麼辦呢（語尾助詞）；ㄋㄧˇ＝無此音（是「你」的讀音）\n2. 國字拆解與造字原因\n呢：形聲字，「口」＋「尼」（聲）。指毛織品讀ㄋㄧˊ（呢絨）；當句尾語氣詞讀輕聲ㄋㄜ。記法：布料二聲、語氣詞輕聲。"},
  {id:"p371",grade:7,word:"字帖",target:"帖",zhuyin:"ㄊㄧㄝˋ",pinyin:"tiè",wrong:[{z:"ㄊㄧㄝˇ",p:"tiě"},{z:"ㄊㄧㄝ",p:"tiē"}],note:"「字帖」「碑帖」讀ㄊㄧㄝˋ;「請帖」讀ㄊㄧㄝˇ;「妥帖」讀ㄊㄧㄝ。",deep:"1. 注音比較\n帖：ㄊㄧㄝˋ（四聲）＝字帖、碑帖、畫帖；ㄊㄧㄝˇ（三聲）＝請帖、喜帖；ㄊㄧㄝ（一聲）＝妥帖、服帖\n2. 國字拆解與造字原因\n帖：形聲字，「巾」＋「占」（聲），本義是寫在布帛上的文字。習字範本讀ㄊㄧㄝˋ（字帖）；邀請卡片讀ㄊㄧㄝˇ（請帖）；安穩順從讀ㄊㄧㄝ（妥帖）。一字三音是常考重點。"},
  {id:"p372",grade:7,word:"請帖",target:"帖",zhuyin:"ㄊㄧㄝˇ",pinyin:"tiě",wrong:[{z:"ㄊㄧㄝˋ",p:"tiè"},{z:"ㄊㄧㄝ",p:"tiē"}],note:"「請帖」「喜帖」讀ㄊㄧㄝˇ;「字帖」讀ㄊㄧㄝˋ。",deep:"1. 注音比較\n帖：ㄊㄧㄝˇ（三聲）＝請帖、喜帖、名帖；ㄊㄧㄝˋ（四聲）＝字帖、法帖；ㄊㄧㄝ（一聲）＝服帖\n2. 國字拆解與造字原因\n帖：「巾」＋「占」（聲）。邀請、通知的卡片讀ㄊㄧㄝˇ；供臨摹的書法範本讀ㄊㄧㄝˋ；平順服貼讀ㄊㄧㄝ。"},
  {id:"p373",grade:7,word:"妥帖",target:"帖",zhuyin:"ㄊㄧㄝ",pinyin:"tiē",wrong:[{z:"ㄊㄧㄝˇ",p:"tiě"},{z:"ㄊㄧㄝˋ",p:"tiè"}],note:"「妥帖」「服帖」讀ㄊㄧㄝ。",deep:"1. 注音比較\n帖：ㄊㄧㄝ（一聲）＝妥帖、服帖、俯首帖耳；ㄊㄧㄝˇ（三聲）＝柬帖；ㄊㄧㄝˋ（四聲）＝碑帖\n2. 國字拆解與造字原因\n帖：「巾」＋「占」（聲）。表「安穩、順從」讀ㄊㄧㄝ（妥帖）；卡片讀ㄊㄧㄝˇ；字帖讀ㄊㄧㄝˋ。"},
  {id:"p374",grade:7,word:"攢動",target:"攢",zhuyin:"ㄘㄨㄢˊ",pinyin:"cuán",wrong:[{z:"ㄗㄢˇ",p:"zǎn"},{z:"ㄗㄢˋ",p:"zàn"}],note:"「萬頭攢動」(聚集)讀ㄘㄨㄢˊ;「積攢」(儲蓄)讀ㄗㄢˇ。",deep:"1. 注音比較\n攢：ㄘㄨㄢˊ（二聲）＝萬頭攢動、攢聚（聚集）；ㄗㄢˇ（三聲）＝積攢（儲蓄）；ㄗㄢˋ＝無此音（是「贊」的讀音）\n2. 國字拆解與造字原因\n攢：形聲字，「扌」＋「贊」（聲）。聚集在一起讀ㄘㄨㄢˊ（萬頭攢動）；一點一點存錢讀ㄗㄢˇ（積攢）。"},
  {id:"p375",grade:7,word:"佝僂",target:"佝",zhuyin:"ㄎㄡˋ",pinyin:"kòu",wrong:[{z:"ㄍㄡ",p:"gōu"},{z:"ㄐㄩˋ",p:"jù"}],note:"審訂音「佝僂」讀ㄎㄡˋ ㄌㄡˊ,駝背彎腰。",deep:"1. 注音比較\n佝：ㄎㄡˋ（四聲）＝佝僂（審訂音ㄎㄡˋ ㄌㄡˊ）；ㄍㄡ＝俗讀，審訂表不採；ㄐㄩˋ＝無此音\n2. 國字拆解與造字原因\n佝：形聲字，「亻」＋「句」（聲，彎曲），「佝僂」是背脊彎曲——駝背。審訂音讀ㄎㄡˋ。"},
  {id:"p376",grade:7,word:"綏靖",target:"綏",zhuyin:"ㄙㄨㄟ",pinyin:"suī",wrong:[{z:"ㄙㄨㄟˊ",p:"suí"},{z:"ㄊㄨㄛˇ",p:"tuǒ"}],note:"「綏靖」讀ㄙㄨㄟ ㄐㄧㄥˋ,安撫平定。",deep:"1. 注音比較\n綏：ㄙㄨㄟ（一聲）＝綏靖；ㄙㄨㄟˊ＝誤讀（受「隨」影響）；ㄊㄨㄛˇ＝無此音（是「妥」的讀音）\n2. 國字拆解與造字原因\n綏：從「糸」從「妥」，本義是登車時拉的繩子——拉繩使穩，引申為安撫→「綏靖」（安撫平定）。讀一聲ㄙㄨㄟ。"},
  {id:"p377",grade:7,word:"檜木",target:"檜",zhuyin:"ㄍㄨㄟˋ",pinyin:"guì",wrong:[{z:"ㄏㄨㄟˋ",p:"huì"},{z:"ㄎㄨㄞˋ",p:"kuài"}],note:"「檜木」讀ㄍㄨㄟˋ;人名「秦檜」讀ㄏㄨㄟˋ。",deep:"1. 注音比較\n檜：ㄍㄨㄟˋ（四聲）＝檜木、紅檜；ㄏㄨㄟˋ（四聲）＝秦檜（人名）；ㄎㄨㄞˋ＝無此音（是「快」的讀音）\n2. 國字拆解與造字原因\n檜：形聲字，「木」＋「會」（聲），常綠大喬木→檜木（ㄍㄨㄟˋ）；南宋奸臣「秦檜」人名讀ㄏㄨㄟˋ。"},
  {id:"p378",grade:7,word:"傍晚",target:"傍",zhuyin:"ㄅㄤ",pinyin:"bāng",wrong:[{z:"ㄅㄤˋ",p:"bàng"},{z:"ㄆㄤˊ",p:"páng"}],note:"審訂音「傍晚」的「傍」讀ㄅㄤ;「依傍」讀ㄅㄤˋ。",deep:"1. 注音比較\n傍：ㄅㄤ（一聲）＝傍晚（審訂音）；ㄅㄤˋ（四聲）＝依傍、傍人門戶；ㄆㄤˊ＝無此音（是「旁」的讀音）\n2. 國字拆解與造字原因\n傍：形聲字，「亻」＋「旁」（聲），本義是靠近→依傍（ㄅㄤˋ）；「傍晚」（靠近晚上）審訂音讀ㄅㄤ。"},
  {id:"p379",grade:7,word:"跛腳",target:"跛",zhuyin:"ㄅㄛˇ",pinyin:"bǒ",wrong:[{z:"ㄆㄛˇ",p:"pǒ"},{z:"ㄅㄞˇ",p:"bǎi"}],note:"「跛腳」「跛行」的「跛」讀ㄅㄛˇ。",deep:"1. 注音比較\n跛：ㄅㄛˇ（三聲）＝跛腳、跛行；ㄆㄛˇ＝誤讀；ㄅㄞˇ＝無此音（是「擺」的讀音）\n2. 國字拆解與造字原因\n跛：形聲字，「足」＋「皮」（聲），腳有毛病走路不穩→跛腳。讀ㄅㄛˇ。"},
  {id:"p380",grade:7,word:"胴體",target:"胴",zhuyin:"ㄉㄨㄥˋ",pinyin:"dòng",wrong:[{z:"ㄊㄨㄥˊ",p:"tóng"},{z:"ㄉㄨㄥ",p:"dōng"}],note:"「胴體」的「胴」讀ㄉㄨㄥˋ,軀體。",deep:"1. 注音比較\n胴：ㄉㄨㄥˋ（四聲）＝胴體；ㄊㄨㄥˊ＝誤讀（受「同」影響）；ㄉㄨㄥ＝無此音（是「東」的讀音）\n2. 國字拆解與造字原因\n胴：形聲字，「月（肉）」＋「同」（聲），軀幹→胴體。讀四聲ㄉㄨㄥˋ。"},
  {id:"p381",grade:8,word:"可汗",target:"汗",zhuyin:"ㄏㄢˊ",pinyin:"hán",wrong:[{z:"ㄏㄢˋ",p:"hàn"},{z:"ㄍㄢ",p:"gān"}],note:"「可汗」讀ㄎㄜˋ ㄏㄢˊ,古代北方君長稱號;「流汗」讀ㄏㄢˋ。",deep:"1. 注音比較\n汗：ㄏㄢˊ（二聲）＝可汗（ㄎㄜˋ ㄏㄢˊ）；ㄏㄢˋ（四聲）＝流汗、汗水；ㄍㄢ＝無此音\n2. 國字拆解與造字原因\n汗：「氵」＋「干」（聲），身體排出的水分（ㄏㄢˋ）。「可汗」是古代北方遊牧民族君長稱號的音譯，「汗」讀ㄏㄢˊ。"},
  {id:"p382",grade:8,word:"單于",target:"單",zhuyin:"ㄔㄢˊ",pinyin:"chán",wrong:[{z:"ㄉㄢ",p:"dān"},{z:"ㄕㄢˋ",p:"shàn"}],note:"「單于」讀ㄔㄢˊ ㄩˊ,匈奴君長;姓氏「單」讀ㄕㄢˋ。",deep:"1. 注音比較\n單：ㄔㄢˊ（二聲）＝單于（ㄔㄢˊ ㄩˊ）；ㄉㄢ（一聲）＝單獨、簡單；ㄕㄢˋ（四聲）＝姓氏（單先生）\n2. 國字拆解與造字原因\n單：象形字，像狩獵的叉形武器。「單于」是匈奴君長稱號的音譯讀ㄔㄢˊ；姓氏讀ㄕㄢˋ；常義讀ㄉㄢ。一字三音常考。"},
  {id:"p383",grade:8,word:"燕京",target:"燕",zhuyin:"ㄧㄢ",pinyin:"yān",wrong:[{z:"ㄧㄢˋ",p:"yàn"},{z:"ㄧㄢˇ",p:"yǎn"}],note:"地名「燕京」「燕山」讀ㄧㄢ;「燕子」讀ㄧㄢˋ。",deep:"1. 注音比較\n燕：ㄧㄢ（一聲）＝燕京、燕山、燕國（地名國名）；ㄧㄢˋ（四聲）＝燕子、燕窩；ㄧㄢˇ＝無此音\n2. 國字拆解與造字原因\n燕：象形字，像燕子展翅之形（ㄧㄢˋ）。古國名、地名（河北一帶）讀ㄧㄢ（燕京＝北京舊稱）。記法：鳥四聲、地名一聲。"},
  {id:"p384",grade:8,word:"鐵騎",target:"騎",zhuyin:"ㄐㄧˋ",pinyin:"jì",wrong:[{z:"ㄑㄧˊ",p:"qí"},{z:"ㄐㄧˇ",p:"jǐ"}],note:"名詞「鐵騎」「輕騎」讀ㄐㄧˋ;動詞「騎馬」讀ㄑㄧˊ。",deep:"1. 注音比較\n騎：ㄐㄧˋ（四聲）＝鐵騎、輕騎、車騎（名詞）；ㄑㄧˊ（二聲）＝騎馬、騎車（動詞）；ㄐㄧˇ＝無此音\n2. 國字拆解與造字原因\n騎：形聲字，「馬」＋「奇」（聲），跨坐馬上（動詞，ㄑㄧˊ）；騎馬的士兵、馬隊（名詞）讀ㄐㄧˋ（鐵騎）。記法：動詞ㄑㄧˊ、名詞ㄐㄧˋ。"},
  {id:"p385",grade:8,word:"羽扇綸巾",target:"綸",zhuyin:"ㄍㄨㄢ",pinyin:"guān",wrong:[{z:"ㄌㄨㄣˊ",p:"lún"},{z:"ㄍㄨㄢˋ",p:"guàn"}],note:"「綸巾」讀ㄍㄨㄢ ㄐㄧㄣ;「經綸」讀ㄌㄨㄣˊ。",deep:"1. 注音比較\n綸：ㄍㄨㄢ（一聲）＝綸巾（ㄍㄨㄢ ㄐㄧㄣ）；ㄌㄨㄣˊ（二聲）＝經綸、滿腹經綸；ㄍㄨㄢˋ＝無此音\n2. 國字拆解與造字原因\n綸：形聲字，「糸」＋「侖」（聲），本義是青絲帶——青絲頭巾「綸巾」讀ㄍㄨㄢ（羽扇綸巾指諸葛亮）；整理絲線引申為治理才能（經綸）讀ㄌㄨㄣˊ。"},
  {id:"p386",grade:8,word:"道行",target:"行",zhuyin:"ㄏㄥˊ",pinyin:"héng",wrong:[{z:"ㄒㄧㄥˊ",p:"xíng"},{z:"ㄏㄤˊ",p:"háng"}],note:"「道行」(修為)讀ㄏㄥˊ;「行走」讀ㄒㄧㄥˊ;「銀行」讀ㄏㄤˊ。",deep:"1. 注音比較\n行：ㄏㄥˊ（二聲）＝道行（修為功力）；ㄒㄧㄥˊ（二聲）＝行走、行為；ㄏㄤˊ（二聲）＝銀行、行列\n2. 國字拆解與造字原因\n行：象形字，十字路口。走路讀ㄒㄧㄥˊ；行列讀ㄏㄤˊ；僧道修煉的功夫「道行」讀ㄏㄥˊ，是特殊讀音。"},
  {id:"p387",grade:8,word:"傳記",target:"傳",zhuyin:"ㄓㄨㄢˋ",pinyin:"zhuàn",wrong:[{z:"ㄔㄨㄢˊ",p:"chuán"},{z:"ㄓㄨㄢ",p:"zhuān"}],note:"「傳記」「自傳」「水滸傳」讀ㄓㄨㄢˋ;「傳說」讀ㄔㄨㄢˊ。",deep:"1. 注音比較\n傳：ㄓㄨㄢˋ（四聲）＝傳記、自傳、《水滸傳》；ㄔㄨㄢˊ（二聲）＝傳說、傳遞、流傳；ㄓㄨㄢ＝無此音（是「專」的讀音）\n2. 國字拆解與造字原因\n傳：「亻」＋「專」（聲），驛站遞送（ㄔㄨㄢˊ）；記載生平的著作讀ㄓㄨㄢˋ（列傳、傳記）。記法：動詞ㄔㄨㄢˊ、書與記事ㄓㄨㄢˋ。"},
  {id:"p388",grade:8,word:"標識",target:"識",zhuyin:"ㄓˋ",pinyin:"zhì",wrong:[{z:"ㄕˋ",p:"shì"},{z:"ㄓ",p:"zhī"}],note:"「標識」(通「誌」,記號)讀ㄓˋ;「認識」「知識」讀ㄕˋ。",deep:"1. 注音比較\n識：ㄓˋ（四聲）＝標識（通「誌」，記號）、博聞強識；ㄕˋ（四聲）＝認識、知識、見識；ㄓ＝無此音\n2. 國字拆解與造字原因\n識：形聲字，「言」＋「戠」（聲），本義是知道分辨（ㄕˋ）；作「記住、記號」解時通「誌」讀ㄓˋ（標識、強識）。"},
  {id:"p389",grade:8,word:"畜生",target:"畜",zhuyin:"ㄔㄨˋ",pinyin:"chù",wrong:[{z:"ㄒㄩˋ",p:"xù"},{z:"ㄒㄩ",p:"xū"}],note:"名詞「畜生」「牲畜」讀ㄔㄨˋ;動詞「畜牧」讀ㄒㄩˋ。",deep:"1. 注音比較\n畜：ㄔㄨˋ（四聲）＝畜生、牲畜、家畜（名詞）；ㄒㄩˋ（四聲）＝畜牧、畜養（動詞）；ㄒㄩ＝無此音\n2. 國字拆解與造字原因\n畜：會意字，田中積存草料，本義是積養。飼養的動作讀ㄒㄩˋ（畜牧）；養的動物（名詞）讀ㄔㄨˋ（牲畜）。記法：動詞ㄒㄩˋ、名詞ㄔㄨˋ。"},
  {id:"p390",grade:8,word:"稱心如意",target:"稱",zhuyin:"ㄔㄣˋ",pinyin:"chèn",wrong:[{z:"ㄔㄥ",p:"chēng"},{z:"ㄔㄥˋ",p:"chèng"}],note:"「稱心」「相稱」讀ㄔㄣˋ;「稱呼」讀ㄔㄥ。",deep:"1. 注音比較\n稱：ㄔㄣˋ（四聲）＝稱心如意、相稱、對稱；ㄔㄥ（一聲）＝稱呼、稱讚；ㄔㄥˋ（四聲）＝同「秤」\n2. 國字拆解與造字原因\n稱：舉禾衡量。相合、合意讀ㄔㄣˋ（稱心、勻稱）；叫名、讚美讀ㄔㄥ。記法：合適ㄔㄣˋ、叫名ㄔㄥ。"},
  {id:"p391",grade:9,word:"簞食壺漿",target:"食",zhuyin:"ㄙˋ",pinyin:"sì",wrong:[{z:"ㄕˊ",p:"shí"},{z:"ㄧˋ",p:"yì"}],note:"文言「簞食壺漿」「食馬者」的「食」讀ㄙˋ,給人吃;「食物」讀ㄕˊ。",deep:"1. 注音比較\n食：ㄙˋ（四聲）＝簞食壺漿、食馬者（文言：給人吃、餵養）；ㄕˊ（二聲）＝食物、飲食；ㄧˋ＝人名用音（酈食其）\n2. 國字拆解與造字原因\n食：象形字，像盛食物的器皿。一般「吃、食物」讀ㄕˊ；文言「拿食物給人／餵養」讀ㄙˋ（簞食壺漿以迎王師）。"},
  {id:"p392",grade:9,word:"智者樂水",target:"樂",zhuyin:"ㄧㄠˋ",pinyin:"yào",wrong:[{z:"ㄌㄜˋ",p:"lè"},{z:"ㄩㄝˋ",p:"yuè"}],note:"「智者樂水,仁者樂山」的「樂」讀ㄧㄠˋ,喜好之意。",deep:"1. 注音比較\n樂：ㄧㄠˋ（四聲）＝智者樂水、仁者樂山（喜好）；ㄌㄜˋ（四聲）＝快樂；ㄩㄝˋ（四聲）＝音樂\n2. 國字拆解與造字原因\n樂：樂器象形。《論語》「智者樂水，仁者樂山」的「樂」是「喜好」，文言讀ㄧㄠˋ。三音口訣：音樂ㄩㄝˋ、快樂ㄌㄜˋ、喜好ㄧㄠˋ。"},
  {id:"p393",grade:9,word:"屬文",target:"屬",zhuyin:"ㄓㄨˇ",pinyin:"zhǔ",wrong:[{z:"ㄕㄨˇ",p:"shǔ"},{z:"ㄕㄨˋ",p:"shù"}],note:"文言「屬文」「屬予作文以記之」的「屬」通「囑」,讀ㄓㄨˇ;「屬於」讀ㄕㄨˇ。",deep:"1. 注音比較\n屬：ㄓㄨˇ（三聲）＝屬文、屬予作文以記之（通「囑」）；ㄕㄨˇ（三聲）＝屬於、金屬、家屬；ㄕㄨˋ＝無此音\n2. 國字拆解與造字原因\n屬：從「尾」，本義是連接。文言「連綴文字（寫作）、囑託」讀ㄓㄨˇ（〈岳陽樓記〉「屬予作文以記之」）；歸屬義讀ㄕㄨˇ。"},
  {id:"p394",grade:9,word:"期年",target:"期",zhuyin:"ㄐㄧ",pinyin:"jī",wrong:[{z:"ㄑㄧˊ",p:"qí"},{z:"ㄑㄧ",p:"qī"}],note:"文言「期年」(滿一年)「期月」的「期」讀ㄐㄧ;「期待」讀ㄑㄧˊ。",deep:"1. 注音比較\n期：ㄐㄧ（一聲）＝期年（滿一年）、期月；ㄑㄧˊ（二聲）＝期待、日期、學期；ㄑㄧ＝無此音\n2. 國字拆解與造字原因\n期：形聲字，「月」＋「其」（聲），本義是約定的時日（ㄑㄧˊ）。文言「滿一年／一月」讀ㄐㄧ（期年之後，雖欲言，無可進者）。"},
  {id:"p395",grade:9,word:"遺贈",target:"遺",zhuyin:"ㄨㄟˋ",pinyin:"wèi",wrong:[{z:"ㄧˊ",p:"yí"},{z:"ㄨㄟˊ",p:"wéi"}],note:"文言「遺之千金」(贈送)讀ㄨㄟˋ;「遺失」「遺產」讀ㄧˊ。",deep:"1. 注音比較\n遺：ㄨㄟˋ（四聲）＝遺之千金、遺書（文言：贈送）；ㄧˊ（二聲）＝遺失、遺產、遺憾；ㄨㄟˊ＝無此音\n2. 國字拆解與造字原因\n遺：形聲字，「辶」＋「貴」（聲），本義是丟失（ㄧˊ）；文言「送給」讀ㄨㄟˋ（父母歲有裘葛之遺）。記法：丟失ㄧˊ、贈送ㄨㄟˋ。"},
  {id:"p396",grade:9,word:"退避三舍",target:"舍",zhuyin:"ㄕㄜˋ",pinyin:"shè",wrong:[{z:"ㄕㄜˇ",p:"shě"},{z:"ㄕㄚˋ",p:"shà"}],note:"「退避三舍」的「舍」讀ㄕㄜˋ,古代行軍三十里為一舍。",deep:"1. 注音比較\n舍：ㄕㄜˋ（四聲）＝退避三舍、宿舍、寒舍；ㄕㄜˇ（三聲）＝同「捨」（舍棄）；ㄕㄚˋ＝無此音（是「廈」的讀音）\n2. 國字拆解與造字原因\n舍：象形字，像簡易房屋。古代行軍三十里紮營一次為「一舍」——「退避三舍」即退讓九十里，讀ㄕㄜˋ；放棄義同「捨」讀ㄕㄜˇ。"},
  {id:"p397",grade:9,word:"王天下",target:"王",zhuyin:"ㄨㄤˋ",pinyin:"wàng",wrong:[{z:"ㄨㄤˊ",p:"wáng"},{z:"ㄨㄤˇ",p:"wǎng"}],note:"文言動詞「王天下」(稱王)讀ㄨㄤˋ;名詞「國王」讀ㄨㄤˊ。",deep:"1. 注音比較\n王：ㄨㄤˋ（四聲）＝王天下（文言動詞：稱王統治）；ㄨㄤˊ（二聲）＝國王、王子；ㄨㄤˇ＝無此音（是「往」的讀音）\n2. 國字拆解與造字原因\n王：象形字，像大斧（王權象徵）。名詞讀ㄨㄤˊ；文言動詞「稱王」讀ㄨㄤˋ（然而不王者，未之有也）。"},
  {id:"p398",grade:9,word:"雨雪",target:"雨",zhuyin:"ㄩˋ",pinyin:"yù",wrong:[{z:"ㄩˇ",p:"yǔ"},{z:"ㄩ",p:"yū"}],note:"文言動詞「雨雪霏霏」(降下)讀ㄩˋ;名詞「下雨」讀ㄩˇ。",deep:"1. 注音比較\n雨：ㄩˋ（四聲）＝雨雪霏霏（文言動詞：降下）；ㄩˇ（三聲）＝下雨、雨天；ㄩ＝無此音\n2. 國字拆解與造字原因\n雨：象形字，天上落下水滴之形。名詞讀ㄩˇ；文言當動詞「降下」讀ㄩˋ（天雨雪、雨我公田）。"},
  {id:"p399",grade:9,word:"衣錦還鄉",target:"衣",zhuyin:"ㄧˋ",pinyin:"yì",wrong:[{z:"ㄧ",p:"yī"},{z:"ㄧˇ",p:"yǐ"}],note:"文言動詞「衣錦還鄉」(穿)讀ㄧˋ;名詞「衣服」讀ㄧ。",deep:"1. 注音比較\n衣：ㄧˋ（四聲）＝衣錦還鄉（文言動詞：穿）；ㄧ（一聲）＝衣服、衣裳；ㄧˇ＝無此音\n2. 國字拆解與造字原因\n衣：象形字，像上衣的領袖衣襟。名詞讀ㄧ；文言當動詞「穿」讀ㄧˋ（衣錦還鄉、解衣衣我）。"},
  {id:"p400",grade:9,word:"語人",target:"語",zhuyin:"ㄩˋ",pinyin:"yù",wrong:[{z:"ㄩˇ",p:"yǔ"},{z:"ㄩˊ",p:"yú"}],note:"文言動詞「不以語人」(告訴)讀ㄩˋ;名詞「語言」讀ㄩˇ。",deep:"1. 注音比較\n語：ㄩˋ（四聲）＝不以語人（文言動詞：告訴）；ㄩˇ（三聲）＝語言、成語、國語；ㄩˊ＝無此音\n2. 國字拆解與造字原因\n語：形聲字，「言」＋「吾」（聲），本義是談話（ㄩˇ）；文言「告訴某人」讀ㄩˋ（此中人語云：不足為外人道也）。記法：名詞ㄩˇ、告訴ㄩˋ。"},
  {id:"p401",grade:10,word:"咀嚼",target:"嚼",zhuyin:"ㄐㄩㄝˊ",pinyin:"jué",wrong:[{z:"ㄐㄧㄠˊ",p:"jiáo"},{z:"ㄐㄩㄝˋ",p:"juè"}],note:"書面「咀嚼」讀ㄐㄩˇ ㄐㄩㄝˊ;口語「嚼口香糖」讀ㄐㄧㄠˊ。",deep:"1. 注音比較\n嚼：ㄐㄩㄝˊ（二聲）＝咀嚼（書面）；ㄐㄧㄠˊ（二聲）＝嚼口香糖、細嚼慢嚥（口語）；ㄐㄩㄝˋ＝無此音\n2. 國字拆解與造字原因\n嚼：形聲字，「口」＋「爵」（聲），用牙磨碎食物。書面語「咀嚼」（ㄐㄩˇ ㄐㄩㄝˊ，也指反覆體會）讀ㄐㄩㄝˊ；口語讀ㄐㄧㄠˊ。"},
  {id:"p402",grade:10,word:"間諜活動",target:"間",zhuyin:"ㄐㄧㄢˋ",pinyin:"jiàn",wrong:[{z:"ㄐㄧㄢ",p:"jiān"},{z:"ㄐㄧㄢˇ",p:"jiǎn"}],note:"「間諜」「離間」「間隔」讀ㄐㄧㄢˋ;「中間」讀ㄐㄧㄢ。",deep:"1. 注音比較\n間：ㄐㄧㄢˋ（四聲）＝間諜、離間、間隔、間接；ㄐㄧㄢ（一聲）＝中間、房間、時間；ㄐㄧㄢˇ＝無此音（是「簡」的讀音）\n2. 國字拆解與造字原因\n間：門縫透月光，本義是縫隙。「置身縫隙中打探、拉開距離」的引申義讀ㄐㄧㄢˋ（間諜、離間、間隔）；表方位、單位讀ㄐㄧㄢ。"},
  {id:"p403",grade:10,word:"慰藉",target:"藉",zhuyin:"ㄐㄧㄝˋ",pinyin:"jiè",wrong:[{z:"ㄐㄧˊ",p:"jí"},{z:"ㄗㄜˋ",p:"zè"}],note:"「慰藉」「藉口」讀ㄐㄧㄝˋ;「狼藉」讀ㄐㄧˊ。",deep:"1. 注音比較\n藉：ㄐㄧㄝˋ（四聲）＝慰藉、藉口、憑藉；ㄐㄧˊ（二聲）＝狼藉；ㄗㄜˋ＝無此音\n2. 國字拆解與造字原因\n藉：「艹」＋「耤」（聲），本義是草墊→依靠（憑藉）、安慰（慰藉）讀ㄐㄧㄝˋ；「狼藉」（雜亂）讀ㄐㄧˊ。"},
  {id:"p404",grade:10,word:"乘客",target:"乘",zhuyin:"ㄔㄥˊ",pinyin:"chéng",wrong:[{z:"ㄕㄥˋ",p:"shèng"},{z:"ㄔㄥˋ",p:"chèng"}],note:"「乘客」「乘車」讀ㄔㄥˊ;「萬乘之國」「史乘」讀ㄕㄥˋ。",deep:"1. 注音比較\n乘：ㄔㄥˊ（二聲）＝乘客、乘車、乘機；ㄕㄥˋ（四聲）＝萬乘之國、史乘（車輛單位、史書）；ㄔㄥˋ＝無此音\n2. 國字拆解與造字原因\n乘：象形字，人爬在樹上，本義是登上→搭乘（ㄔㄥˊ）；古代四馬一車為一乘，兵車單位與史書讀ㄕㄥˋ（千乘之國）。"},
  {id:"p405",grade:10,word:"泡茶",target:"泡",zhuyin:"ㄆㄠˋ",pinyin:"pào",wrong:[{z:"ㄆㄠ",p:"pāo"},{z:"ㄅㄠˋ",p:"bào"}],note:"「泡茶」「泡沫」讀ㄆㄠˋ;「眼泡」「豆腐泡兒」讀ㄆㄠ。",deep:"1. 注音比較\n泡：ㄆㄠˋ（四聲）＝泡茶、泡沫、氣泡；ㄆㄠ（一聲）＝眼泡、豆腐泡兒（鬆軟之物）；ㄅㄠˋ＝無此音\n2. 國字拆解與造字原因\n泡：形聲字，「氵」＋「包」（聲），水包著空氣的球→泡沫；浸在水裡→泡茶（ㄆㄠˋ）；鬆軟鼓起之物讀ㄆㄠ（眼泡）。"},
  {id:"p406",grade:10,word:"擂鼓",target:"擂",zhuyin:"ㄌㄟˊ",pinyin:"léi",wrong:[{z:"ㄌㄟˋ",p:"lèi"},{z:"ㄌㄟˇ",p:"lěi"}],note:"「擂鼓」「自吹自擂」讀ㄌㄟˊ;審訂音「擂臺」亦讀ㄌㄟˊ。",deep:"1. 注音比較\n擂：ㄌㄟˊ（二聲）＝擂鼓、自吹自擂、擂臺；ㄌㄟˋ＝俗讀（擂臺），審訂表不採；ㄌㄟˇ＝無此音\n2. 國字拆解與造字原因\n擂：「扌」＋「雷」（聲），用力敲打（如雷聲）→擂鼓、自吹自擂。審訂音統讀ㄌㄟˊ。"},
  {id:"p407",grade:10,word:"揶揄",target:"揄",zhuyin:"ㄩˊ",pinyin:"yú",wrong:[{z:"ㄩˋ",p:"yù"},{z:"ㄕㄨ",p:"shū"}],note:"「揶揄」讀ㄧㄝˊ ㄩˊ,嘲笑戲弄。",deep:"1. 注音比較\n揄：ㄩˊ（二聲）＝揶揄；ㄩˋ＝誤讀；ㄕㄨ＝無此音\n2. 國字拆解與造字原因\n揄：形聲字，「扌」＋「俞」（聲），「揶揄」（ㄧㄝˊ ㄩˊ）＝出手戲弄、言語嘲笑。"},
  {id:"p408",grade:10,word:"炮烙",target:"烙",zhuyin:"ㄌㄨㄛˋ",pinyin:"luò",wrong:[{z:"ㄌㄠˋ",p:"lào"},{z:"ㄍㄜˊ",p:"gé"}],note:"古刑「炮烙」讀ㄆㄠˊ ㄌㄨㄛˋ;「烙印」「烙餅」讀ㄌㄠˋ。",deep:"1. 注音比較\n烙：ㄌㄨㄛˋ（四聲）＝炮烙（ㄆㄠˊ ㄌㄨㄛˋ，古酷刑）；ㄌㄠˋ（四聲）＝烙印、烙餅；ㄍㄜˊ＝無此音\n2. 國字拆解與造字原因\n烙：形聲字，「火」＋「各」（聲），用燒熱的金屬燙→烙印（ㄌㄠˋ）；商紂的酷刑「炮烙」讀ㄌㄨㄛˋ。記法：日常ㄌㄠˋ、古刑ㄌㄨㄛˋ。"},
  {id:"p409",grade:10,word:"馥郁",target:"馥",zhuyin:"ㄈㄨˋ",pinyin:"fù",wrong:[{z:"ㄈㄨˊ",p:"fú"},{z:"ㄅㄨˋ",p:"bù"}],note:"「馥郁」的「馥」讀ㄈㄨˋ,香氣濃厚。",deep:"1. 注音比較\n馥：ㄈㄨˋ（四聲）＝馥郁；ㄈㄨˊ＝誤讀；ㄅㄨˋ＝無此音\n2. 國字拆解與造字原因\n馥：形聲字，「香」＋「复」（聲），香氣濃厚→馥郁（花香馥郁）。讀ㄈㄨˋ。"},
  {id:"p410",grade:10,word:"陰霾",target:"霾",zhuyin:"ㄇㄞˊ",pinyin:"mái",wrong:[{z:"ㄌㄧˊ",p:"lí"},{z:"ㄇㄢˊ",p:"mán"}],note:"「陰霾」「霾害」的「霾」讀ㄇㄞˊ。",deep:"1. 注音比較\n霾：ㄇㄞˊ（二聲）＝陰霾、霾害、霧霾；ㄌㄧˊ＝無此音（是「狸」的讀音）；ㄇㄢˊ＝無此音\n2. 國字拆解與造字原因\n霾：形聲字，「雨」＋「貍」（聲），風夾塵土使天色昏暗→陰霾（也比喻心頭陰影）。讀ㄇㄞˊ，與「埋」同音。"},
  {id:"p411",grade:10,word:"忖度",target:"忖",zhuyin:"ㄘㄨㄣˇ",pinyin:"cǔn",wrong:[{z:"ㄘㄨㄣˊ",p:"cún"},{z:"ㄈㄨˋ",p:"fù"}],note:"「忖度」「思忖」的「忖」讀ㄘㄨㄣˇ,揣測。",deep:"1. 注音比較\n忖：ㄘㄨㄣˇ（三聲）＝忖度、思忖、自忖；ㄘㄨㄣˊ＝誤讀（受「存」影響）；ㄈㄨˋ＝無此音\n2. 國字拆解與造字原因\n忖：形聲字，「忄」＋「寸」（聲），心中丈量→揣測（忖度）。讀ㄘㄨㄣˇ。"},
  {id:"p412",grade:10,word:"殷實",target:"殷",zhuyin:"ㄧㄣ",pinyin:"yīn",wrong:[{z:"ㄧㄢ",p:"yān"},{z:"ㄧㄣˇ",p:"yǐn"}],note:"「殷實」「殷勤」讀ㄧㄣ;「殷紅」讀ㄧㄢ。",deep:"1. 注音比較\n殷：ㄧㄣ（一聲）＝殷實、殷勤、殷商；ㄧㄢ（一聲）＝殷紅（深紅帶黑）；ㄧㄣˇ＝殷殷（雷聲）\n2. 國字拆解與造字原因\n殷：本義是盛大→富足（殷實）、懇切（殷勤）讀ㄧㄣ；深紅色讀ㄧㄢ（殷紅的血）。記法：紅色讀ㄧㄢ，其他多讀ㄧㄣ。"},
  {id:"p413",grade:10,word:"憩息",target:"憩",zhuyin:"ㄑㄧˋ",pinyin:"qì",wrong:[{z:"ㄒㄧ",p:"xī"},{z:"ㄎㄜˋ",p:"kè"}],note:"「休憩」「小憩」的「憩」讀ㄑㄧˋ。",deep:"1. 注音比較\n憩：ㄑㄧˋ（四聲）＝休憩、小憩、憩息；ㄒㄧ＝無此音（是「息」的讀音）；ㄎㄜˋ＝無此音\n2. 國字拆解與造字原因\n憩：從「舌」「息」，休息→小憩片刻。讀ㄑㄧˋ，與「氣」同音。"},
  {id:"p414",grade:10,word:"僧侶",target:"僧",zhuyin:"ㄙㄥ",pinyin:"sēng",wrong:[{z:"ㄗㄥ",p:"zēng"},{z:"ㄘㄥˊ",p:"céng"}],note:"「僧侶」「高僧」的「僧」讀ㄙㄥ。",deep:"1. 注音比較\n僧：ㄙㄥ（一聲）＝僧侶、高僧、僧多粥少；ㄗㄥ＝誤讀（受「曾」影響）；ㄘㄥˊ＝無此音\n2. 國字拆解與造字原因\n僧：形聲字，「亻」＋「曾」（聲），梵語「僧伽」的省稱——出家修行的人→僧侶。讀ㄙㄥ。"},
  {id:"p415",grade:10,word:"蒼穹",target:"穹",zhuyin:"ㄑㄩㄥˊ",pinyin:"qióng",wrong:[{z:"ㄍㄨㄥ",p:"gōng"},{z:"ㄎㄨㄥ",p:"kōng"}],note:"「蒼穹」「穹蒼」的「穹」讀ㄑㄩㄥˊ,天空。",deep:"1. 注音比較\n穹：ㄑㄩㄥˊ（二聲）＝蒼穹、穹蒼、穹頂；ㄍㄨㄥ＝無此音（是「弓」的讀音）；ㄎㄨㄥ＝無此音（是「空」的讀音）\n2. 國字拆解與造字原因\n穹：形聲字，「穴」＋「弓」（聲），中間隆起如弓的洞形→天空（蒼穹，天像圓頂罩著大地）。讀ㄑㄩㄥˊ。"},
  {id:"p416",grade:10,word:"泥鰍",target:"鰍",zhuyin:"ㄑㄧㄡ",pinyin:"qiū",wrong:[{z:"ㄐㄧㄡ",p:"jiū"},{z:"ㄑㄧㄡˊ",p:"qiú"}],note:"「泥鰍」的「鰍」讀ㄑㄧㄡ。",deep:"1. 注音比較\n鰍：ㄑㄧㄡ（一聲）＝泥鰍；ㄐㄧㄡ＝無此音；ㄑㄧㄡˊ＝誤讀\n2. 國字拆解與造字原因\n鰍：形聲字，「魚」＋「秋」（聲），生活在泥中的細長小魚→泥鰍。與「秋」同音ㄑㄧㄡ。"},
  {id:"p417",grade:10,word:"愜意",target:"愜",zhuyin:"ㄑㄧㄝˋ",pinyin:"qiè",wrong:[{z:"ㄒㄧㄚˊ",p:"xiá"},{z:"ㄐㄧㄚˊ",p:"jiá"}],note:"「愜意」的「愜」讀ㄑㄧㄝˋ,滿足舒暢。",deep:"1. 注音比較\n愜：ㄑㄧㄝˋ（四聲）＝愜意、愜心；ㄒㄧㄚˊ＝無此音（是「狹」的讀音）；ㄐㄧㄚˊ＝無此音\n2. 國字拆解與造字原因\n愜：形聲字，「忄」＋「匧」（聲），心中滿足舒暢→愜意。讀ㄑㄧㄝˋ，與「怯」同音。"},
  {id:"p418",grade:10,word:"髭鬚",target:"髭",zhuyin:"ㄗ",pinyin:"zī",wrong:[{z:"ㄘˊ",p:"cí"},{z:"ㄗˇ",p:"zǐ"}],note:"「髭鬚」的「髭」讀ㄗ,嘴上邊的鬍子。",deep:"1. 注音比較\n髭：ㄗ（一聲）＝髭鬚；ㄘˊ＝無此音（是「慈」的讀音）；ㄗˇ＝誤讀\n2. 國字拆解與造字原因\n髭：形聲字，「髟」（毛髮）＋「此」（聲），嘴脣上方的鬍子→髭鬚。讀一聲ㄗ。"},
  {id:"p419",grade:10,word:"頷首",target:"頷",zhuyin:"ㄏㄢˋ",pinyin:"hàn",wrong:[{z:"ㄏㄢˊ",p:"hán"},{z:"ㄧㄢˊ",p:"yán"}],note:"「頷首」的「頷」讀ㄏㄢˋ,點頭。",deep:"1. 注音比較\n頷：ㄏㄢˋ（四聲）＝頷首、下頷；ㄏㄢˊ＝誤讀（受「含」影響）；ㄧㄢˊ＝無此音\n2. 國字拆解與造字原因\n頷：形聲字，「頁」（頭）＋「含」（聲），本義是下巴→頷首（點頭）。讀ㄏㄢˋ。"},
  {id:"p420",grade:10,word:"打鼾",target:"鼾",zhuyin:"ㄏㄢ",pinyin:"hān",wrong:[{z:"ㄍㄢ",p:"gān"},{z:"ㄏㄢˊ",p:"hán"}],note:"「打鼾」「鼾聲」的「鼾」讀ㄏㄢ。",deep:"1. 注音比較\n鼾：ㄏㄢ（一聲）＝打鼾、鼾聲如雷；ㄍㄢ＝無此音（是「干」的讀音）；ㄏㄢˊ＝誤讀\n2. 國字拆解與造字原因\n鼾：形聲字，「鼻」＋「干」（聲），睡覺時鼻息作聲→打鼾。讀一聲ㄏㄢ。"},
];
